You are correct that my previous suggestion embeds the `ArtistDetailScreen` right inside the `FirstScreen` composable. If you want to navigate to a separate composable entirely, you can make use of Jetpack Compose Navigation. Here's how you can achieve navigation between the screens using the navigation library:

1. Add the Jetpack Compose Navigation dependency to the `build.gradle` file:

```groovy
dependencies {
    // ...
    implementation 'androidx.navigation:navigation-compose:2.4.1'
}
```

2. In `MainActivity`, replace the `MainScreen` function with the following:

```kotlin
@Composable
fun MainScreen() {
    val navController = rememberNavController()

    NavHost(navController, startDestination = "musicCategories") {
        composable("musicCategories") {
            CategoriesScreen(navController)
        }
        composable("artistsDetail/{categoryId}") { backStackEntry ->
            val categoryId = backStackEntry.arguments?.getString("categoryId")?.toIntOrNull()
            if (categoryId != null) {
                ArtistsDetailScreen(navController, categoryId)
            }
        }
    }
}
```

3. Create a `CategoriesScreen` composable that hosts the `MusicCategoriesScreen` and accepts a `NavController` as a parameter:

```kotlin
@Composable
fun CategoriesScreen(navController: NavController) {
    val categoriesViewModel: CategoriesViewModel = viewModel()
    val categories by categoriesViewModel.categories.collectAsState()

    Scaffold(
        content = { padding ->
            Column(
                modifier = Modifier.padding(padding)
            ) {
                MusicCategoriesScreen(
                    categories = categories,
                    onCategorySelected = { category ->
                        navController.navigate("artistsDetail/${category.id}")
                    },
                    topBar = { TopBar(title = "Music Categories") }
                )
            }
        }
    )
}
```

4. Create an `ArtistsDetailScreen` composable that accepts both `NavController` and `categoryId` as parameters and fetches the relevant category:

```kotlin
@Composable
fun ArtistsDetailScreen(navController: NavController, categoryId: Int) {
    // Get CategoryViewModel and fetch category
    val categoriesViewModel: CategoriesViewModel = viewModel()
    val allCategories by categoriesViewModel.categories.collectAsState()
    val category = allCategories.firstOrNull { it.id == categoryId }

    // Get ArtistsViewModel and fetch artists
    val artistsViewModel: ArtistsViewModel = viewModel()
    val artists by artistsViewModel.artists.collectAsState()
    artistsViewModel.fetchArtists(categoryId)

    if (category != null) {
        Scaffold(
            topBar = { TopBar(title = category.name) },
            content = { padding ->
                Column(modifier = Modifier.padding(padding)) {
                    ArtistsDetailScreenContent(
                        genre = category,
                        artists = artists,
                        onArtistSelected = { /* Handle artist selection here */ }
                    )
                }
            }
        )
    } else {
        Text("Category not found")
    }
}
