        enemyY = obstacle.y - ENEMY_RADIUS * 2;
      } else if (enemyY > obstacle.y + obstacle.height - 5) {
        enemyY = obstacle.y + obstacle.height;
        enemySpeedY = 0;
      } else {
        enemySpeedX = 0;
      }
    }
  }
