interface DeezerApiService {
    @GET("genre")
    suspend fun getGenres(): DeezerResponse<Category>

    @GET("genre/{genre_id}/artists")
    suspend fun getArtists(@Path("genre_id") genreId: Int): DeezerResponse<Artist>

