Following are examples of simple Java client and server programs that use SSL/TLS with the given cipher suite configurations:

1. SecureClient.java

```java
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.Socket;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLSocketFactory;

public class SecureClient {
   public static void main(String[] args) {
      try {
         // Set the cipher suite configuration for the client
         SSLContext context = SSLContext.getInstance("SSL");
         String[] cipher_suites = {"SSL_DH_RSA_WITH_AES_256_CBC_SHA256"};

         // Create an SSL socket factory with the custom cipher suites
         SSLSocketFactory factory = context.getSocketFactory();
         SSLSocket socket = (SSLSocket) factory.createSocket("localhost", 1234);
         socket.setEnabledCipherSuites(cipher_suites);

         // Perform basic read/write operations with the server
         BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));
         BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));

         writer.write("Hello, secure server!\n");
         writer.flush();

         String response = reader.readLine();
         System.out.println("Server response: " + response);

         writer.close();
         reader.close();
         socket.close();
      } catch (Exception e) {
         e.printStackTrace();
      }
   }
}
```

2. SecureServer.java

```java
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.ServerSocket;
import javax.net.ServerSocketFactory;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLServerSocket;
import javax.net.ssl.SSLServerSocketFactory;
import javax.net.ssl.SSLSocket;

public class SecureServer {
   public static void main(String[] args) {
      try {
         // Set the cipher suite configuration for the server
         SSLContext context = SSLContext.getInstance("SSL");
         String[] cipher_suites = {"SSL_DH_anon_WITH_3DES_EDE_CBC_SHA"};

         // Create an SSL server socket factory with the custom cipher suites
         ServerSocketFactory factory = context.getServerSocketFactory();
         SSLServerSocket serverSocket = (SSLServerSocket) factory.createServerSocket(1234);
         serverSocket.setEnabledCipherSuites(cipher_suites);

         while (true) {
            SSLSocket socket = (SSLSocket) serverSocket.accept();

            // Perform basic read/write operations with the client
            BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));

            String message = reader.readLine();
            System.out.println("Client message: " + message);

            writer.write("Hello, secure client!\n");
            writer.flush();

            writer.close();
            reader.close();
            socket.close();
         }
      } catch (Exception e) {
         e.printStackTrace();
      }
   }
}
```

