function handlePlayerCollision(obstacle, axis) {
  if (axis === "horizontal") {
    if (playerSpeedX > 0) { // moving right, hit left edge
      playerX = obstacle.x - PLAYER_RADIUS * 2 - 1;
    } else { // moving left, hit right edge
      playerX = obstacle.x + obstacle.width + 1;
