            InetAddress receiverAddress = InetAddress.getByName("192.168.0.1");
            int receiverPort = 5600;
            byte[] buffer = new byte[BUFFER_SIZE];

            String message = "The message you want to send";
            int startIndex = 0, endIndex;

            while (startIndex < message.length()) {
                endIndex = Math.min(startIndex + 100, message.length());
                String fragment = message.substring(startIndex, endIndex);
                byte[] fragmentBytes = fragment.getBytes("UTF-8");

                DatagramPacket packet = new DatagramPacket(fragmentBytes, fragmentBytes.length,
                        receiverAddress, receiverPort);
                packet.setTrafficClass(0x1B);
                socket.send(packet);

                startIndex = endIndex;
            }

        } catch (IOException e) {
