If your houses are in a collection group, you cannot use a direct path to retrieve a document by its ID. Instead, you can use the `collectionGroup` to run a query with `where('__name__', '==', id)` to filter the results by the document ID. Here's the modified function for this case:

```javascript
import { collectionGroup, getDocs, query, where } from "firebase/firestore";

export const getHouseById = async (id) => {
  const q = query(collectionGroup(FirebaseDB, "houses"), where("__name__", "==", id));

  const querySnapshot = await getDocs(q);

  let house = null;
  querySnapshot.forEach((doc) => {
    if (doc.exists()) {
      house = doc.data();
    }
  });
  return house;
};
