        const overlapY = Math.min(aabbPlatform.maxY - aabbPlayer.minY, aabbPlayer.maxY - aabbPlatform.minY);

        if (overlapX < overlapY) {
            // Move player in X direction
            if (aabbPlayer.maxX < aabbPlatform.maxX) {
                // Move to the left
                for (let i = 0; i < playerPolygon.vertices.length; i++) {
                    playerPolygon.vertices[i][0] -= overlapX;
                }
                normal[0] = -1;
            } else {
                // Move to the right
                for (let i = 0; i < playerPolygon.vertices.length; i++) {
                    playerPolygon.vertices[i][0] += overlapX;
                }
                normal[0] = 1;
            }
            normal[1] = 0;
