```c
#include <stdio.h>
#include <stdlib.h>

typedef enum {
    OP_ICONST_0,
    OP_ICONST_1,
    OP_IADD,
    OP_ISUB,
    OP_IMUL,
    OP_IDIV,
    OP_IREM,
    OP_INEG,
    OP_IINC,
    OP_GOTO,
    OP_IF_ICMPEQ,
    OP_ILOAD_0,
    OP_ISTORE_0,
    OP_HALT
} OpCode;

static OpCode program[] = {
    OP_ICONST_1,
    OP_ISTORE_0,
    OP_ILOAD_0,
    OP_ICONST_1,
    OP_IADD,
    OP_ISTORE_0,
    OP_ILOAD_0,
    OP_HALT
};

#define MAX_STACK 256
#define MAX_LOCALS 256
static int locals[MAX_LOCALS];
static int stack[MAX_STACK];
static int sp = 0; // Stack pointer
static int ip = 0; // Instruction pointer

void execute(OpCode opcode) {
    switch (opcode) {
        case OP_ICONST_0: stack[sp++] = 0; break;
        case OP_ICONST_1: stack[sp++] = 1; break;
        case OP_IADD: stack[sp - 2] = stack[sp - 2] + stack[--sp]; break;
        case OP_ISUB: stack[sp - 2] = stack[sp - 2] - stack[--sp]; break;
        case OP_IMUL: stack[sp - 2] = stack[sp - 2] * stack[--sp]; break;
        case OP_IDIV: stack[sp - 2] = stack[sp - 2] / stack[--sp]; break;
        case OP_IREM: stack[sp - 2] = stack[sp - 2] % stack[--sp]; break;
        case OP_INEG: stack[sp - 1] = -stack[sp - 1]; break;
        case OP_IINC: locals[0]++; break;
        case OP_ILOAD_0: stack[sp++] = locals[0]; break;
        case OP_ISTORE_0: locals[0] = stack[--sp]; break;
        case OP_GOTO: ip += (char)program[ip]; break;
        case OP_IF_ICMPEQ:
            if (stack[sp - 2] == stack[sp - 1]) {
                ip += (char)program[ip];
                sp -= 2;
            } else {
                ip++;
            }
            break;
        case OP_HALT: break;
        default: printf("Unknown opcode: %d\n", opcode); exit(1);
    }
}

int main() {
    while (program[ip] != OP_HALT) {
        execute(program[ip++]);
    }
    printf("Result: %d\n", locals[0]);
    return 0;
}
