fun SongDetailScreen(songId: Int, previewUrl: String) {
    val requestOptions = RequestOptions()
        .fallback(R.drawable.ic_launcher_background)
        .error(R.drawable.ic_launcher_background)

    LaunchedEffect(Unit) {
        playPreview(LocalContext.current, previewUrl)
    }

    Scaffold(
        // ... (rest of the code)
    )
}
```

