int getKeypadValue(int minVal, int maxVal) {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Enter value (");
  lcd.print(minVal);
  lcd.print("-");
  lcd.print(maxVal);
  lcd.print("):");

  int value = 0;
  bool exit = false;
  while (!exit) {
    char key = keypad.waitForKey();

