      int newVal = value * 10 + (key - '0');
      if (newVal >= minVal && newVal <= maxVal) {
        value = newVal;
        lcd.print(key);
      }
    } else if (key == '*') {
      return -1; // Cancel entry
    } else if (key == '#') {
      exit = true;
    }
  }

  return value;
