class PlayerViewModel : ViewModel() {
    val currentPlayer = mutableStateOf<SimpleExoPlayer?>(null)

    fun playSong(player: SimpleExoPlayer) {
        currentPlayer.value?.let {
            if (it != player) {
                it.pause()
            }
        }
