public static Vector2 velocityToPosition(Body body, Vector2 target, float maxSpeed) {
    float maxVelocityMagnitude = maxSpeed * PhysicsSystem.STEP_FREQUENCY;
    Vector2 currentPosition = body.getPosition();
    Vector2 displacement = target.cpy().sub(currentPosition);
    Vector2 velocity = displacement.nor().scl(maxVelocityMagnitude);
    float distance = displacement.len();

    // Calculate the time taken to reach the target at max velocity.
    // We use the quadratic formula to solve for t, given the equation
    // d = vt - 1/2 * at^2, where a is negative due to the body's linear
    // damping in Box2D.
    float a = -0.5f * body.getLinearDamping() * PhysicsSystem.STEP_FREQUENCY * PhysicsSystem.STEP_FREQUENCY;
    float b = maxVelocityMagnitude * PhysicsSystem.STEP_FREQUENCY;
    float c = -distance;
    float discriminant = b * b - 4 * a * c;
    float timeToTarget;

    if (discriminant <= 0) {
        // The target is too close to be reached at max velocity.
        // Solve linearly for a lower speed.
        timeToTarget = distance / (0.5f * PhysicsSystem.STEP_FREQUENCY * (maxVelocityMagnitude + 0));
    } else {
        // Use the smaller positive root of the quadratic formula.
        float root = (float) Math.sqrt(discriminant);
        timeToTarget = (-b - root) / (2 * a);
        if (timeToTarget <= 0) {
            // The target is too close to be reached at max velocity.
            // Solve linearly for a lower speed.
            timeToTarget = distance / (0.5f * PhysicsSystem.STEP_FREQUENCY * (maxVelocityMagnitude + 0));
        } else {
            timeToTarget = Math.min(timeToTarget, distance / maxVelocityMagnitude);
        }
    }

    Vector2 predictedPosition = currentPosition.cpy().add(velocity.cpy().scl(timeToTarget));
    float remainingDistance = target.cpy().sub(predictedPosition).len();

    if (remainingDistance > 0.1f) {
        // The predicted position is not close enough to the target.
        // Adjust velocity to decelerate smoothly.
        float brakingDistance = (maxVelocityMagnitude * maxVelocityMagnitude) /
                (2 * body.getLinearDamping() * PhysicsSystem.STEP_FREQUENCY);
        if (remainingDistance < brakingDistance) {
            // We don't have enough distance to brake to zero velocity.
            // Solve linearly for a lower speed.
            velocity.scl(remainingDistance / brakingDistance);
        } else {
            // Braking distance is enough to reduce velocity to zero.
            float idealSpeed = (float) Math.sqrt(2 * body.getLinearDamping() *
                    PhysicsSystem.STEP_FREQUENCY * remainingDistance);
            float ratio = idealSpeed / maxVelocityMagnitude;
            velocity.scl(ratio);
        }
    }

    return velocity;
}
