    val currentSong = mutableStateOf<Song?>(null)
    val isPlaying = mutableStateOf(false)

    fun playSong(song: Song, player: SimpleExoPlayer) {
        currentPlayer.value?.let {
            if (it != player) {
                it.pause()
            }
        }
        currentSong.value = song
        if (player.playbackState == ExoPlayer.STATE_ENDED) {
            player.seekToDefaultPosition()
        }
        player.play()
        isPlaying.value = true
        currentPlayer.value = player
    }

    fun pauseSong() {
        currentPlayer.value?.pause()
        isPlaying.value = false
    }

    fun resumeSong() {
        currentPlayer.value?.play()
        isPlaying.value = true
    }

    override fun onCleared() {
        super.onCleared()
        currentPlayer.value?.release()
    }
}
