```kotlin
@Composable
fun MainScreen() {
    val navController = rememberNavController()

    NavHost(navController, startDestination = "musicCategories") {
        //...

        // Add the composable for the song detail screen
        composable("songDetail/{songId}") { backStackEntry ->
            val songId = backStackEntry.arguments?.getString("songId")?.toIntOrNull()
            if (songId != null) {
                SongDetailScreen(songId, navController) // Make sure to create a composable for the SongDetailScreen
            }
        }
