#include <iostream>
#include <vector>
#include <random>
#include <iomanip>

class MarkovChain {
public:
    MarkovChain(size_t order, bool partial_links = false)
        : order_(order), partial_links_(partial_links) {
        size_t num_states = (1 << order); // 2^order
        transition_matrix_.resize(num_states, std::vector<double>(2, 0.0));
        generate_transition_matrix();
    }

    void generate_transition_matrix() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.0, 1.0);
        for (size_t state = 0; state < transition_matrix_.size(); ++state) {
            double p = dis(gen);
            transition_matrix_[state][0] = p;
            transition_matrix_[state][1] = 1.0 - p;
        }
    }

    void print_transition_matrix() {
        std::cout << std::fixed << std::setprecision(2);
        for (size_t state = 0; state < transition_matrix_.size(); ++state) {
            std::cout << "State " << state << ": "
                      << "0 -> " << transition_matrix_[state][0] << ", "
                      << "1 -> " << transition_matrix_[state][1] << std::endl;
        }
    }

    std::vector<int> generate_data(size_t length) {
        std::vector<int> data;
        data.reserve(length);
        size_t current_state = 0;
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.0, 1.0);
        for (size_t i = 0; i < length; ++i) {
            double random_value = dis(gen);
            int next_bit = random_value < transition_matrix_[current_state][0] ? 0 : 1;
            data.push_back(next_bit);
            if (partial_links_) {
                current_state = (current_state << 1) & ((1 << order_) - 1);
            } else {
                current_state = (current_state << 1 | next_bit) & ((1 << order_) - 1);
            }
        }
        return data;
    }

private:
    size_t order_;
    bool partial_links_;
    std::vector<std::vector<double>> transition_matrix_;
};

int main() {
    size_t order = 3;
    bool partial_links = true;
    MarkovChain chain(order, partial_links);

    std::cout << "Transition matrix:" << std::endl;
    chain.print_transition_matrix();

    size_t data_length = 20;
    std::vector<int> generated_data = chain.generate_data(data_length);
    std::cout << "Generated data: ";
    for(int bit: generated_data) {
        std::cout << bit;
    }
    std::cout << std::endl;

    return 0;
