Creating a REST API with Express to manage grades of students is simple with the help of Node.js.
First, make sure you have Node.js installed. Then follow the steps below to set up your project.

1. Create a new folder for your project and navigate to it using the command line:

```
mkdir student-grades-api
cd student-grades-api
```

2. Initialize a new Node.js project using npm:

```
npm init -y
```

3. Install Express and other necessary packages:

```
npm install express body-parser cors
```

4. Create a new file named app.js:

```
touch app.js
```

5. Open app.js and paste the following code to set up a basic Express server:

```javascript
const express = require("express");
const bodyParser = require("body-parser");
const cors = require("cors");

const app = express();

// Enable CORS and JSON parsing
app.use(cors());
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// In-memory database for student grades
const studentGrades = [];

// GET all student grades
app.get("/grades", (req, res) => {
  res.json(studentGrades);
});

// POST a new student grade
app.post("/grades", (req, res) => {
  const newGrade = {
    id: studentGrades.length + 1,
    name: req.body.name,
    grade: req.body.grade,
  };

  studentGrades.push(newGrade);
  res.status(201).json(newGrade);
});

// GET a specific student grade by ID
app.get("/grades/:id", (req, res) => {
  const grade = studentGrades.find((g) => g.id === parseInt(req.params.id));
  if (!grade) {
    res.status(404).send("The grade with the given ID was not found.");
  }
  res.json(grade);
});

// PUT (update) a student grade by ID
app.put("/grades/:id", (req, res) => {
  const grade = studentGrades.find((g) => g.id === parseInt(req.params.id));
  if (!grade) {
    res.status(404).send("The grade with the given ID was not found.");
  }

  grade.name = req.body.name;
  grade.grade = req.body.grade;

  res.json(grade);
});

// DELETE a student grade by ID
app.delete("/grades/:id", (req, res) => {
  const grade = studentGrades.find((g) => g.id === parseInt(req.params.id));
  if (!grade) {
    res.status(404).send("The grade with the given ID was not found.");
  }

  const index = studentGrades.indexOf(grade);
  studentGrades.splice(index, 1);

  res.json(grade);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is listening on port ${PORT}...`);
});
```

Now you have a basic REST API built with Express that can perform CRUD operations on student grades. To test the API, you can use tools like Postman, Insomnia, or simply use JavaScript fetch or Axios in your application.

Remember that this API is using an in-memory database, which means that any stored data will be lost once the server restarts. If you require persistent data storage, you may use a database server like MongoDB or PostgreSQL.

There are two issues with the code:

1. The movement velocity (vx) for the entities was not correctly set. The initialization should be done with `*` instead of using the variable itself.
2. The friction and gravity were affecting the Entity's vx value, causing the entity to slow down and eventually stop. We need to remove the friction and gravity effect on the vx value of the entity.

Here's the fixed Entity class:

```javascript
class Entity {
  constructor() {
    this.x = canvas.width;
    this.y = Math.random() * canvas.height;
    this.w = 20;
    this.h = 20;
    this.vx = -1 * (Math.random() * 3);
    this.vy = 0;
    this.jumping = false;
    this.projectiles = [];
    this.color = "blue";
  }

  jump() {
    if (!this.jumping) {
      this.vy -= 10;
      this.jumping = true;
    }
  }

  update(platforms) {
    for (let i = 0; i < platforms.length; i++) {
      platforms[i].collidesWith(this);
    }

    this.vy += 1; // Gravity
    this.x += this.vx;
    this.y += this.vy;

    if (Math.random() < 0.01) {
      this.projectiles.push(
        new Projectile(this.x, this.y, -2 - Math.random() * 6, -2 + Math.random() * 8)
      );
    }

    for (let i = 0; i < this.projectiles.length; i++) {
      this.projectiles[i].update();
      if (
        this.projectiles[i].x < 0 ||
        this.projectiles[i].y < 0 ||
        this.projectiles[i].x > canvas.width ||
        this.projectiles[i].y > canvas.height
      ) {
        this.projectiles.splice(i, 1);
        i--;
      }
    }

    if (Math.random() < 0.01) {
      this.jump();
