  // create a buffer to store the message
  byte buf[64];

  // get the message from the user input (for this example, we'll assume the message is already entered by the user)
  String message = "Hello World!";

  // convert the message to a byte buffer for encryption
  message.getBytes(buf, message.length() + 1);
  // create another buffer to store the encrypted message
  byte encrypted_buf[64];

  // encrypt the message with the AES key
  AES aes;
  aes.do_aes_encrypt(buf, message.length() + 1, encrypted_buf, aes_key, 128);

  // send the encrypted message
  LoRa.beginPacket();
  LoRa.write(encrypted_buf, message.length() + 1);
  LoRa.endPacket();
  Serial.println("Sent message: " + message);
}

