To use the Flowbite Modal in a Vue.js application, you can follow these steps:

1. Install the Flowbite Modal package via npm:

```npm install flowbite-modal```

2. Import the `Modal` component from the package and register it:

```javascript
import { Modal } from 'flowbite-modal';

export default {
  components: {
    Modal
  },
  // ... other component properties
}
```

3. Add a trigger element in your component's template that will open the modal:

```html
<button @click="showModal">Click to open modal</button>
```

4. Add the `Modal` component to your template and bind its `visible` property to the boolean value in your component that will control when the modal is displayed:

```html
<Modal :visible="modalVisible">
  <!-- Modal content goes here -->
</Modal>
```

5. Define the method `showModal` in your component to toggle the value of `modalVisible` when the trigger element is clicked:

```javascript
export default {
  data() {
    return {
      modalVisible: false
    }
  },
  methods: {
    showModal() {
      this.modalVisible = !this.modalVisible;
    }
  }
  // ... other component properties
}
```

6. Customize the content inside the `Modal` component, such as the header, body and footer, using the default slots.

```html
<Modal :visible="modalVisible">
  <template #header>
    <h2>Modal header</h2>
  </template>

  <template #body>
    <p>Modal body content goes here.</p>
  </template>

  <template #footer>
    <button @click="modalVisible = false">Close modal</button>
  </template>
</Modal>
```

That's it! You can now use the Flowbite Modal component in your Vue.js application.

package com.example.musicapp.Data.Repository

import com.example.musicapp.Data.*
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import retrofit2.http.GET
import retrofit2.http.Path

interface DeezerApiService {
    @GET("genre?output=json")  // json endpoint instead of “/”
    suspend fun getGenres(): GenreResponse

    @GET("genre/{genre_id}/artists")
    suspend fun getArtists(@Path("genre_id") genreId: Int): ArtistResponse

    @GET("artist/{artist_id}")
    suspend fun getArtistDetail(@Path("artist_id") artistId: Int): ArtistDetailResponse

    @GET("artist/{artist_id}/albums")
    suspend fun getArtistAlbums(@Path("artist_id") artistId: Int): AlbumResponse

    data class AlbumResponse(val data: List<Album>) {


        fun toAlbumList(): List<Album> {
            return data.map { albumData ->
                Album(
                    id = albumData.id,
                    title = albumData.title,
                    link = albumData.link,
                    cover = albumData.cover,
                    cover_small = albumData.cover_small,
                    cover_medium = albumData.cover_medium,
                    cover_big = albumData.cover_big,
                    cover_xl = albumData.cover_xl,
                    release_date = albumData.release_date,
                    tracklist = albumData.tracklist,
                    type = albumData.type
                )
            }
        }
    }

    @GET("album/{album_id}")
    suspend fun getAlbumDetails(@Path("album_id") albumId: Int): AlbumDetailResponse

    data class AlbumDetailResponse(
        val id: Int,
        val title: String,
        val cover_medium: String,
        val tracks: TracksResponse
    )

    data class TracksResponse(
        val data: List<Song>,
        val inherit_album_cover_medium: String // Add the inheritance field
    )

    // Create a new class for storing response fields.
    data class GenreResponse(val data: List<Category>)
    data class ArtistResponse(val data: List<Artist>)
    data class ArtistDetailResponse(val id: Int, val name: String, val picture_big: String, val albums: List<Album>?)


    companion object {
        private const val BASE_URL = "https://api.deezer.com/"

        fun create(): DeezerApiService {
            val client = OkHttpClient.Builder()
                .addInterceptor(HttpLoggingInterceptor().apply {
                    level = HttpLoggingInterceptor.Level.BODY
                })
                .build()

            return Retrofit.Builder()
                .baseUrl(BASE_URL)
                .client(client)
                .addConverterFactory(GsonConverterFactory.create())
                .build()
                .create(DeezerApiService::class.java)
        }
    }
