        client.Connect();
        client.WaitForReady(TimeSpan.FromSeconds(10));
        var screenshot = client.TakeScreenshot();
        client.Disconnect();

        string path = Path.Combine("screenshots", $"{server.IPAddress}.png");
        screenshot.Save(path);
    }

    public static void Main()
    {
