            Directory.CreateDirectory("screenshots");

        List<Thread> threads = new List<Thread>();

        foreach (RdpServer server in servers)
        {
            Proxy proxy = proxies[new Random().Next(0, proxies.Count)];
            Thread thread = new Thread(() => ConnectAndCaptureScreenshot(server, proxy, useProxy));
            threads.Add(thread);
            thread.Start();
        }

