#include <bits/stdc++.h>
using namespace std;

const int N = 100;

vector<int> g[N];
bool vis[N];

void dfs(int u) {
    vis[u] = true;
    for (int v : g[u]) {
        if (!vis[v]) {
            dfs(v);
        }
    }
}

bool is_connected(int n) {
    memset(vis, false, sizeof(vis));
    dfs(0);
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            return false;
        }
    }
    return true;
}

void connected_components(int n) {
    memset(vis, false, sizeof(vis));
    int comp = 0;
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            comp++;
            dfs(i);
            cout << "Component " << comp << ": ";
            for (int j = 0; j < n; j++) {
                if (vis[j]) {
                    cout << j << " ";
                }
            }
            cout << endl;
        }
    }
}

