I want to add functionality to load 3d models using the ASSIMP library and render them using the engine. How would I got about doing this?

To load 3D models using ASSIMP and render them using your engine, you can follow these steps:

1. Add ASSIMP dependency to your project. You can download the library from their GitHub repo, build it, and add its include and library directories to your build configuration.

2. Create a Model class to handle loading and managing 3D models.

Model.h:

```cpp
#pragma once

#include <assimp/Importer.hpp>
#include <assimp/scene.h>
#include <assimp/postprocess.h>
#include "Mesh.h"
#include <string>
#include <vector>
#include <vulkan/vulkan.h>

class Model
{
public:
    Model();
    ~Model();

    void LoadModel(const std::string& filepath, VkDevice device, VkPhysicalDevice physicalDevice, VkCommandPool commandPool, VkQueue graphicsQueue);
    void Cleanup();

    const std::vector<Mesh>& GetMeshes() const;

private:
    std::vector<Mesh> meshes;

    void LoadNode(aiNode* node, const aiScene* scene, VkDevice device, VkPhysicalDevice physicalDevice, VkCommandPool commandPool, VkQueue graphicsQueue);
    Mesh LoadMesh(aiMesh* mesh, const aiScene* scene);
};  
```

3. Define the Model class methods.

Model.cpp:

```cpp
#include "Model.h"

Model::Model()
{

}

Model::~Model()
{

}

void Model::LoadModel(const std::string& filepath, VkDevice device, VkPhysicalDevice physicalDevice, VkCommandPool commandPool, VkQueue graphicsQueue)
{
    Assimp::Importer importer;
    const aiScene* scene = importer.ReadFile(filepath, aiProcess_Triangulate | aiProcess_JoinIdenticalVertices);

    if (!scene || scene->mFlags & AI_SCENE_FLAGS_INCOMPLETE || !scene->mRootNode)
    {
        throw std::runtime_error("Failed to load model: " + std::string(importer.GetErrorString()));
    }

    LoadNode(scene->mRootNode, scene, device, physicalDevice, commandPool, graphicsQueue);
}

void Model::Cleanup()
{
    for(auto& mesh : meshes)
    {
        mesh.Cleanup();
    }
}

const std::vector<Mesh>& Model::GetMeshes() const
{
    return meshes;
}

void Model::LoadNode(aiNode* node, const aiScene* scene, VkDevice device, VkPhysicalDevice physicalDevice, VkCommandPool commandPool, VkQueue graphicsQueue)
{
    for(unsigned int i = 0; i < node->mNumMeshes; i++)
    {
        meshes.push_back(LoadMesh(scene->mMeshes[node->mMeshes[i]], scene));
        meshes.back().Initialize(device, physicalDevice, commandPool, graphicsQueue);
    }

    for(unsigned int i = 0; i < node->mNumChildren; i++)
    {
        LoadNode(node->mChildren[i], scene, device, physicalDevice, commandPool, graphicsQueue);
    }
}

Mesh Model::LoadMesh(aiMesh* mesh, const aiScene* scene)
{
    std::vector<Vertex> vertices;
    std::vector<uint32_t> indices;

    for(unsigned int i = 0; i < mesh->mNumVertices; i++)
    {
        Vertex vertex;
        vertex.position.x = mesh->mVertices[i].x;
        vertex.position.y = mesh->mVertices[i].y;
        vertex.position.z = mesh->mVertices[i].z;
        // Load vertex color, texture coordinates, normals, etc. if needed.

        vertices.push_back(vertex);
    }

    for(unsigned int i = 0; i < mesh->mNumFaces; i++)
    {
        if(mesh->mFaces[i].mNumIndices != 3)
        {
            throw std::runtime_error("Mesh face with not exactly 3 indices found. This engine only supports triangle meshes.");
        }

        indices.push_back(mesh->mFaces[i].mIndices[0]);
        indices.push_back(mesh->mFaces[i].mIndices[1]);
        indices.push_back(mesh->mFaces[i].mIndices[2]);
    }

    Mesh result;
    result.SetVertices(vertices);
    result.SetIndices(indices);

    return result;
}
```

4. Load and render the 3D model in your main loop. In your Scene or GameObject class, you can create a Model instance, load a model file, and render the individual meshes using your existing rendering code.

Example of loading the model in Scene or GameObject:

```cpp
Model model;
model.LoadModel("path/to/model.obj", device, physicalDevice, commandPool, graphicsQueue);
```

Example of rendering the model in Scene or GameObject:

```cpp
for(const Mesh& mesh : model.GetMeshes())
{
    // Render the mesh with your existing rendering code.
}
```

Make sure to call the Cleanup() method for the Model instance when you no longer need the model data.

