    for (const auto &entry : other.mMap) {
        result.mMap[entry.first] = entry.second;
    }
    return result;
}

CDictionaryIntToInt CDictionaryIntToInt::operator-(const CDictionaryIntToInt &other) const {
    CDictionaryIntToInt result;
    for (const auto &entry : mMap) {
        if (other.mMap.count(entry.first) > 0) {
            result.mMap[entry.first] = entry.second;
        }
    }
    return result;
}

CDictionaryIntToInt CDictionaryIntToInt::operator/(const CDictionaryIntToInt &other) const {
    CDictionaryIntToInt result(*this);
    for (const auto &entry : other.mMap) {
        result.mMap.erase(entry.first);
    }
    return result;
}

std::istream &operator>>(std::istream &is, CDictionaryIntToInt &dict) {
    int key, value;
    while (is >> key >> value) {
        dict.add(key, value);
    }
    return is;
}

std::ostream &operator<<(std::ostream &os, const CDictionaryIntToInt &dict) {
    for (const auto &entry : dict.mMap) {
        os << entry.first << ": " << entry.second << std::endl;
    }
    return os;
}
