export async function goTo(page, path, current = { x, y }) {
  console.log('trasa smieciu', path);
  for (let i = 0; i < path.length; i++) {
    const next = path[i];
    let direction;
    let steps = 0;

    if (next.x > current.x) {
      direction = 'KeyD';
      steps = next.x - current.x;
      current.x += steps;
    } else if (next.x < current.x) {
      direction = 'KeyA';
      steps = current.x - next.x;
      current.x -= steps;
    } else if (next.y > current.y) {
      direction = 'KeyS';
      steps = next.y - current.y;
      current.y += steps;
    } else if (next.y < current.y) {
      direction = 'KeyW';
      steps = current.y - next.y;
      current.y -= steps;
    }

    if (direction) {
      if (steps > 2) {
        await holdKey(page, direction, steps);
      } else {
        await moveHero(page, direction);
      }
    }
  }

  async function holdKey(page, direction, steps) {
    await page.focus('body');
    await page.keyboard.down(direction);
    await new Promise(resolve => setTimeout(resolve, 300 * (steps - 2)));
    await page.keyboard.up(direction);
    await new Promise(resolve => setTimeout(resolve, 200));
  }

  async function moveHero(page, direction) {
    await page.focus('body');
    await page.keyboard.down(direction);
    setTimeout(async () => {
      await page.keyboard.up(direction);
    }, 100);
    await new Promise(resolve => setTimeout(resolve, 250));
  }
}


