void my_fprintf(FILE *fp, const char *format, ...)
{
    va_list args;
    va_start(args, format);
    vfprintf(fp, format, args);
    va_end(args);
}

int main()
{
    FILE *fp = fopen("output.txt", "w");
    if (fp == NULL) {
        printf("Error opening file!\n");
        return 1;
    }

    my_fprintf(fp, "Hello, World!\n");
    fclose(fp);

    return 0;
}
