```

3. C source code for http_tunnel_custom_payload.c:
```c
#include <curl/curl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
  size_t realsize = size * nmemb;
  if (realsize > 0) {
    printf("Received data from the server: %s\n", (char *)contents);
  }
  return realsize;
}

int main() {
  CURL *curl;
  CURLcode res;
  struct curl_slist *headers = NULL;

  curl_global_init(CURL_GLOBAL_DEFAULT);
  curl = curl_easy_init();

  if (!curl) {
    fprintf(stderr, "Error initializing libcurl\n");
    return 1;
  }

  const char* tunnel_url = "https://your-server-url.example.com/tunnel";
  const char* custom_payload = "{"
                                "\"type\": \"sendMessage\","
                                "\"content\": {"
                                "\"to\": \"recipient@example.com\","
                                "\"text\": \"Hello World\""
                                "}"
                                "}";

  headers = curl_slist_append(headers, "Content-Type: application/json");

  curl_easy_setopt(curl, CURLOPT_URL, tunnel_url);
  curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
  curl_easy_setopt(curl, CURLOPT_POST, 1L);
  curl_easy_setopt(curl, CURLOPT_POSTFIELDS, custom_payload);
  curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(custom_payload));
  curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

  res = curl_easy_perform(curl);

  // Check for errors.
  if (res != CURLE_OK) {
    fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
  }

  // Clean up.
  curl_easy_cleanup(curl);
  curl_slist_free_all(headers);

  curl_global_cleanup();
  return 0;
}
