function custom_free_product_checkout( $checkout_url ) {
    $has_free_product = false;

    foreach ( WC()->cart->get_cart_contents() as $cart_item ) {
        if ( (int)$cart_item['data']->get_price() === 0 ) {
            $has_free_product = true;
