            return openApiTeamraiserInternalKeyClient.getPersonalMediaLayout(getPersonalMediaLayoutRequest, siteUrl);
        } catch (ConvioOpenApiBaseClient.ConvioOpenApiFailureException e) {
            return e.getErrorResponse();
        }
    }

    private OpenApiEntity updatePersonalPhoto(Map<String, String> reqParam, MultipartFile graphicUploadFile, MultipartFile graphicUpload2File) {
        URI siteUrl = getSiteUrl(siteId);
        UploadPersonalPhoto uploadPersonalPhotoRequest = UploadPersonalPhoto.builder()
                .frId(Integer.parseInt(frId))
                .ssoAuthToken(loadSSOUserToken(siteUrl))
                .build();
        Map<String, Consumer<String>> requestParamSetters = new HashMap<>();
        requestParamSetters.put("graphic_caption", uploadPersonalPhotoRequest::setGraphicCaption);
        requestParamSetters.put("graphic_caption2", uploadPersonalPhotoRequest::setGraphicCaption2);
        if (graphicUploadFile != null) {
            uploadPersonalPhotoRequest.setGraphicUploadFile(graphicUploadFile);
        }
        if (graphicUpload2File != null) {
            uploadPersonalPhotoRequest.setGraphicUpload2File(graphicUpload2File);
        }
        if (ConvioApiUtils.hasValue(reqParam.get("graphic_upload_upload"))) {
            uploadPersonalPhotoRequest.setGraphicUploadUpload(Boolean.parseBoolean(reqParam.get("graphic_upload_upload")));
        }
        if (ConvioApiUtils.hasValue(reqParam.get("graphic_upload2_upload"))) {
            uploadPersonalPhotoRequest.setGraphicUpload2Upload(Boolean.parseBoolean(reqParam.get("graphic_upload2_upload")));
        }
        setValues(reqParam, requestParamSetters);
        try {
            return openApiTeamraiserInternalKeyClient.uploadPersonalPhotos(uploadPersonalPhotoRequest, siteUrl);
        } catch (ConvioOpenApiBaseClient.ConvioOpenApiFailureException e) {
            return e.getErrorResponse();
        }
    }

    private OpenApiEntity updateRegistration(Map<String, String> reqParam) {
        URI siteUrl = getSiteUrl(siteId);
        UpdateRegistration updateRegistrationRequest = UpdateRegistration.builder()
                .frId(Integer.parseInt(frId))
                .consId(Integer.parseInt(consId))
                .ssoAuthToken(loadSSOUserToken(siteUrl))
                .responseFormat("json")
                .build();
        Map<String, Consumer<String>> mapToSetParameters = new HashMap<>();
        mapToSetParameters.put("checkin_status", updateRegistrationRequest::setCheckinStatus);
        mapToSetParameters.put("emergency_name", updateRegistrationRequest::setEmergencyName);
        mapToSetParameters.put("emergency_phone", updateRegistrationRequest::setEmergencyPhone);
        mapToSetParameters.put("flow_step", updateRegistrationRequest::setFlowStep);
        mapToSetParameters.put("goal", updateRegistrationRequest::setGoal);
        mapToSetParameters.put("anonymous_registration", s -> updateRegistrationRequest.setAnonymousRegistration(Boolean.parseBoolean(s)));
        setValues(reqParam, mapToSetParameters);
        try {
            return openApiTeamraiserInternalKeyClient.updateRegistration(updateRegistrationRequest, getSiteUrl(siteId));
        } catch (ConvioOpenApiBaseClient.ConvioOpenApiFailureException e) {
            return e.getErrorResponse();
        }
    }

    private String loadSSOUserToken(URI siteUrl) {
        return openApiConstituentSasClient.loadUserToken(siteId, Integer.parseInt(consId), siteUrl);
    }
