  char key = keypad.waitForKey();
  int value;

  switch (key) {
    case 'A':
      Relais_Statut[relai_choisi] = !Relais_Statut[relai_choisi];
      break;

    case 'B':
      value = getKeypadValue(0, 999, "Enter Timer:");
      if (value > -1) {
        Relais_Statut[relai_choisi] = 1;
        Relais_Timer[relai_choisi] = value;
      }
      break;

    case 'C':
          Relais_Prog[relai_choisi] = 1;
          value = getKeypadValue(0, 24, "Enter Heure PH:");
      if (value > -1) {
        Relais_ProgH[relai_choisi] = value;
        value = getKeypadValue(0, 60, "Enter Min PH:");
        if (value > -1) {
          Relais_ProgM[relai_choisi] = value;
          Relais_ProgT[relai_choisi] = getKeypadValue(1, 999, "Enter Duration:");
        }
      }
      break;

    case 'D':
      exitFlag = true;
      lcd.clear();
      lcd.noBacklight();
      break;
  }
}
}

int getKeypadValue(int minVal, int maxVal, char* infoText) {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print(infoText);
  lcd.setCursor(0, 1);
  lcd.print("A-VALIDER D-QUITTER");

  int value = 0;
  bool exitFlag = false;
  while (!exitFlag) {
    char key = keypad.waitForKey();

    if (key >= '0' && key <= '9') {
      int newVal = value * 10 + (key - '0');
      if (newVal >= minVal && newVal <= maxVal) {
        value = newVal;
        lcd.print(key);
      }
    } else if (key == 'D') {
      return -1; // Annuler l'entrée
    } else if (key == 'A') {
      exitFlag = true;
    }
  }

  return value;
}

