const messages = document.querySelector('.messages');
const typingIndicator = document.querySelector('.typing-indicator');
const userInputForm = document.querySelector('.user-input-form');
const userInput = document.querySelector('.user-input');

function addMessage(content, delay) {
    return new Promise((resolve) => {
        setTimeout(() => {
            const message = document.createElement('div');
            message.className = 'message';
            message.textContent = content;
            messages.appendChild(message);
            resolve();
        }, delay);
    });
}

function typeWriterEffect(text, delayPerChar) {
    return new Promise((resolve) => {
        typingIndicator.style.visibility = 'visible';
        let index = 0;
        function typeNextChar() {
            if (index < text.length) {
                addMessage(text.slice(0, index + 1), 0).then(() => {
                    index++;
                    setTimeout(typeNextChar, delayPerChar);
                });
            } else {
                typingIndicator.style.visibility = 'hidden';
                resolve();
            }
        }
        typeNextChar();
    });
}

userInputForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const inputText = userInput.value.trim();
    if (inputText.length > 0) {
        addMessage(inputText, 0);
        typeWriterEffect('This is a simulated reply', 100);
        userInput.value = '';
    }
});
