{
  // Example: convert the CurrentAbilityLevel into FString and store it as a tag
  FString TagString = FString::Printf(TEXT("CustomPayload.CurrentAbilityLevel_%d"), CurrentAbilityLevel);
  FGameplayTag NewTag = FGameplayTag::RequestGameplayTag(FName(*TagString));
