```cpp
void UYourGameplayAbility::OnGameplayEvent_Implementation(FGameplayEventData Payload)
{
    FGameplayTagContainer CustomTags = Payload.Tags;

    // Example: extract the CurrentAbilityLevel from the custom tags
    int CurrentAbilityLevel = -1;
    for (const FGameplayTag& Tag : CustomTags)
    {
        FString TagString = Tag.GetTagName().ToString();
        if (TagString.StartsWith("CustomPayload.CurrentAbilityLevel_"))
        {
            FString LevelString = TagString.RightChop(32);  // Remove the prefix
            CurrentAbilityLevel = FCString::Atoi(*LevelString);  // Convert string to int
            break;
        }
    }

    // Example: extract the TargetingActor's ID and find the actor in the world
    int32 TargetingActorID = -1;
    for (const FGameplayTag& Tag : CustomTags)
    {
        FString TagString = Tag.GetTagName().ToString();
        if (TagString.StartsWith("CustomPayload.TargetingActor_"))
        {
            FString IDString = TagString.RightChop(27);  // Remove the prefix
            TargetingActorID = FCString::Atoi(*IDString);  // Convert string to int
            break;
        }
    }

    if (TargetingActorID != -1)
    {
        // Find the actor by ID and cast it to your specific actor class (e.g., ARagnaAbilTargetActor_GroundTrace)
        for (TActorIterator<ARagnaAbilTargetActor_GroundTrace> ActorItr(GetWorld()); ActorItr; ++ActorItr)
        {
            if (ActorItr->GetUniqueID() == TargetingActorID)
            {
                ARagnaAbilTargetActor_GroundTrace* TargetingActor = *ActorItr;

                // Use the TargetingActor and CurrentAbilityLevel in your ability as needed
                break;
            }
        }
    }
}
```

