- duration：媒体文件时长
- width：视频宽度
- height：视频高度
- videodatarate：视频数据率
- videocodecid：视频编码格式
- audiodatarate：音频数据率
- audiosamplerate：音频采样率
- audiosamplesize：音频采样大小
- stereo：是否为立体声
- audiocodecid：音频编码格式
- filesize：媒体文件大小

```c
// 初始化RTMP连接
RTMP *rtmp = RTMP_Alloc();
RTMP_Init(rtmp);
RTMP_SetupURL(rtmp, "rtmp://example.com/live/stream");
RTMP_EnableWrite(rtmp);

// 连接RTMP服务器
if (!RTMP_Connect(rtmp, NULL) || !RTMP_ConnectStream(rtmp, 0)) {
    // 连接失败
    RTMP_Free(rtmp);
    return NULL;
}

// 发送@setDataFrame元数据
RTMPTPacket packet;
memset(&packet, 0, sizeof(RTMPTPacket));
packet.m_header.m_packetType = RTMP_PACKET_TYPE_INFO;
packet.m_header.m_nChannel = 0x03; // 控制通道
