                     duration, width, height, videodatarate, videocodecid, audiodatarate, audiosamplerate, audiosamplesize, stereo, audiocodecid, filesize);
packet.m_nBodySize = length;
RTMP_SendPacket(rtmp, &packet, 1);

// 发送onMetaData元数据
RTMPTPacket packet;
memset(&packet, 0, sizeof(RTMPTPacket));
packet.m_header.m_packetType = RTMP_PACKET_TYPE_VIDEO;
packet.m_header.m_nChannel = 0x04; // 视频通道
packet.m_header.m_nTimeStamp = 0;
