amf_object_set_number(&onMetaData, "videocodecid", videocodecid);
amf_object_set_number(&onMetaData, "audiodatarate", audiodatarate);
amf_object_set_number(&onMetaData, "audiosamplerate", audiosamplerate);
amf_object_set_number(&onMetaData, "audiosamplesize", audiosamplesize);
