```kotlin
import android.content.Context
import android.content.pm.PackageManager
import android.net.Uri
import android.util.Log
import androidx.compose.runtime.MutableState
import androidx.compose.runtime.mutableStateOf
import androidx.core.app.ActivityCompat
import androidx.core.content.ContextCompat
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import java.io.File
import java.util.concurrent.ExecutorService

class KameraViewModel : ViewModel() {

    private lateinit var context: Context
    private lateinit var outputDirectory: File
    private lateinit var cameraExecutor: ExecutorService

    var shouldShowCamera: MutableState<Boolean> = mutableStateOf(false)
    private lateinit var photoUri: Uri
    var shouldShowPhoto: MutableState<Boolean> = mutableStateOf(false)

    // Pass the context from the activity to the ViewModel, ideally using a DI framework like Dagger or Hilt
    fun initializeContext(context: Context) {
        this.context = context
    }

    fun requestCameraPermission() {
        when {
            ContextCompat.checkSelfPermission(
                context,
                android.Manifest.permission.CAMERA
            ) == PackageManager.PERMISSION_GRANTED -> {
                Log.i("ja", "Kamera zugriff bereits erlaubt")
                shouldShowCamera.value = true
            }

            ActivityCompat.shouldShowRequestPermissionRationale(
                context as MainActivity,
                android.Manifest.permission.CAMERA
            ) -> Log.i("ja", "Zeige Kamera Permission Text")

            else -> {
                viewModelScope.launch {
                    (context as MainActivity).requestCameraPermissionLauncher()
                }
            }
        }
    }

    fun handleImageCapture(uri: Uri) {
        viewModelScope.launch(Dispatchers.IO) {
            Log.i("ja", "Bild Gemacht: $uri")
            shouldShowCamera.value = false
            photoUri = uri
            shouldShowPhoto.value = true
        }
    }

    fun getOutputDirectory(): File {
        val mediaDir = context.externalMediaDirs.firstOrNull()?.let {
            File(it, context.resources.getString(R.string.app_name)).apply { mkdirs() }
        }
        return if (mediaDir != null && mediaDir.exists()) mediaDir else context.filesDir
    }

    fun shutdownCameraExecutor() {
        cameraExecutor.shutdown()
    }
}
