#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 5;
vector<int> tree[N];
int n;

vector<int> cut() {
    vector<int> deg(n + 1, 0);
    queue<int> q;
    for (int i = 1; i <= n; i++) {
        deg[i] = tree[i].size();
        if (deg[i] == 1)
            q.push(i);
    }

    vector<int> ans;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        deg[u]--;
        for (int v : tree[u]) {
            if (--deg[v] == 1) {
                q.push(v);
                ans.push_back(u); // edge number can be replaced with index
            }
        }
    }

    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int t;
    cin >> t;

    while (t--) {
        cin >> n;
        for (int i = 1; i <= n; i++) {
            tree[i].clear();
        }

        for (int i = 1; i < n; i++) {
            int u, v;
            cin >> u >> v;
            tree[u].push_back(v);
            tree[v].push_back(u);
        }

        vector<int> ans = cut();
        if (ans.empty()) {
            cout << "-1\n";
        } else {
            cout << ans.size() << '\n';
            for (int i : ans) {
                cout << i << " ";
            }
            cout << '\n';
        }
    }

    return 0;
}
