#include <bits/stdc++.h>
using namespace std;

const int MAX = 1e4 + 5;

int n, m;
vector<int> edges[MAX];
int counts_nodes[MAX];
int total_req;
int curr_req[MAX];
int cr_qt;

vector<int> used_count(MAX, 0);
vector<bool> visited(MAX);
int tries;

int dfs(int x, const int ancestor, const int sum) {
    visited[x] = true;

    int q = 0;
    for (int to : edges[x]) {
        if (!visited[to]) {
            q += dfs(to, x, sum);
        }
    }

    curr_req[x] = counts_nodes[x] - q;

    return q + curr_req[x] - sum;
}

bool dfs_solve(int x) {
    visited[x] = true;
    int can_return = tries;

    for (int to : edges[x]) {
        if (!visited[to]) {
            int temp_result = dfs_solve(to);
            can_return = min(can_return, temp_result);
        }
    }

    if (0 < can_return) {
        used_count[cr_qt]++;
        can_return--;
    }

    return can_return;
}

bool attempt(const int cnt) {
    if (cr_qt >= total_req) {
        return false;
    }

    vector<int> used_copy = used_count;
    memset(visited.data(), false, visited.size() * sizeof visited[0]);
    tries = cnt - 1;
    dfs_solve(0);

    if (used_count > used_copy) {
        cr_qt++;
        used_count = max(used_count, used_copy);
        return true;
    }

    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> m;

    for (int i = 0; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        counts_nodes[a] = counts_nodes[b] = b;
        total_req += b;
    }

    dfs(0, -1, 1);

    for (int i = 57; i >= 0; --i) {
        if (1 << i <= total_req - cr_qt) {
            while (attempt(1 << i)) {
            }
        }
    }

    cout << used_count.back() << '\n';

    return 0;
}
