using System.Linq;

public class MCTS
{
    private const double ExplorationConstant = Math.Sqrt(2);
    private readonly Random _random = new Random();

    public Node Execute(Node rootNode, int maxIterations)
    {
        for (int i = 0; i < maxIterations; i++)
        {
            Node currentNode = rootNode;
            while (currentNode.Children.Count != 0) 
            {
                currentNode = SelectBestChild(currentNode);
            }

            if (!currentNode.IsTerminal)
            {
                currentNode.Expand();
            }

            double reward = currentNode.Simulate();
            currentNode.Backpropagate(reward);
        }

        return rootNode.Children.OrderByDescending(c => c.NumberOfVisits).First();
    }

    private Node SelectBestChild(Node node)
    {
        return node.Children.OrderByDescending(c => c.GetUCTValue(ExplorationConstant)).First();
    }

}
