Here's the function to calculate the `get_page_frame_stat`:

```c
#include <linux/mm.h>		/* For struct page and zone */
#include <linux/swap.h>		/* For si_swapinfo() */
#include <linux/swapops.h>	/* For swap_count() */

static void get_page_frame_stat(struct page_info *buf)
{
	unsigned long flags;
	unsigned long valid;
	struct page *page;
	unsigned long num_physpages = 0;
	struct zone *zone;

	buf->free = 0;
	buf->locked = 0;
	buf->reserved = 0;
	buf->swapcache = 0;
	buf->referenced = 0;
	buf->slab = 0;
	buf->private = 0;
	buf->uptodate = 0;
	buf->dirty = 0;
	buf->active = 0;
	buf->writeback = 0;
	buf->mappedtodisk = 0;

	for_each_zone(zone)
	{
		spin_lock_irqsave(&zone->lru_lock, flags);
		buf->free += zone_page_state(zone, NR_FREE_PAGES);

		for (page = zone->zone_start_pfn + zone->base_pfn, valid = 0;
		     valid < zone->present_pages; ++page)
		{
			if (!pfn_valid_within(page))
				continue;

			++valid;
			++num_physpages;

			if (PageLocked(page))
				++buf->locked;
			if (PageReserved(page))
				++buf->reserved;
			if (PageSwapCache(page))
				++buf->swapcache;
			if (PageReferenced(page))
				++buf->referenced;
			if (PageSlab(page))
				++buf->slab;
			if (PagePrivate(page))
				++buf->private;
			if (PageUptodate(page))
				++buf->uptodate;
			if (PageDirty(page))
				++buf->dirty;
			if (PageActive(page))
				++buf->active;
			if (PageWriteback(page))
				++buf->writeback;
			if (PageMappedToDisk(page))
				++buf->mappedtodisk;
		}
		spin_unlock_irqrestore(&zone->lru_lock, flags);
	}

	buf->num_physpages = num_physpages;
}
```

And the modified `PageFrameStat_read` function:

```c
static ssize_t PageFramStat_read(struct file *file, char __user * out, size_t size, loff_t * off) {
