            // Retrieve the i'th media type
            pConfig->GetStreamCaps(i, &pmt, (BYTE*)&caps);

            // Ignore non-standard media types
            if (pmt->formattype != FORMAT_VideoInfo) {
                FreeMediaType(*pmt);
                continue;
            }

            // Retrieve the media type's width and height
            VIDEOINFOHEADER* pvi = (VIDEOINFOHEADER*)pmt->pbFormat;
            int nWidth = pvi->bmiHeader.biWidth;
            int nHeight = pvi->bmiHeader.biHeight;

            // Check if the media type matches the desired resolution
            if (nWidth == 640 && nHeight == 480) {
                // Select the media type
                pMediaType = pmt;
                nMediaTypeIndex = i;
                bMediaTypeFound = true;
                break;
