    vector<int> X_coords, Y_coords, Fill_vals;
    X_coords.reserve(nPixels);
    Y_coords.reserve(nPixels);
    Fill_vals.reserve(nPixels);

    for (int j = bmp.bmHeight - 1; j >= 0; j--) {
        for (int i = 0; i < bmp.bmWidth; i++) {
            COLORREF pixel = ((COLORREF*)bmp.bmBits)[j * bmp.bmWidth + i];
            if (pixel != 0xFFFFFF) { // ignore the white background color
                X_coords.push_back(i);
                Y_coords.push_back(j);
                Fill_vals.push_back(pixel);
            }
        }
    }

