    mdl.X_average_coordinates = new int[mdl.num_of_coordinates];
    mdl.Y_average_coordinates = new int[mdl.num_of_coordinates];
    mdl.X_plus_minus = new int[mdl.num_of_coordinates];
    mdl.Y_plus_minus = new int[mdl.num_of_coordinates];

    // Calculate the average X, average Y and fill value of the model
    double sumX = accumulate(X_coords.begin(), X_coords.end(), 0);
    double sumY = accumulate(Y_coords.begin(), Y_coords.end(), 0);
    double sumFill = accumulate(Fill_vals.begin(), Fill_vals.end(), 0);
    mdl.average_fill = static_cast<int>(sumFill / mdl.num_of_coordinates);

    for (int i = 0; i < mdl.num_of_coordinates; i++) {
        mdl.X_average_coordinates[i] = static_cast<int>(sumX / mdl.num_of_coordinates);
        mdl.Y_average_coordinates[i] = static_cast<int>(sumY / mdl.num_of_coordinates);
    }

    sort(X_coords.begin(), X_coords.end());
    sort(Y_coords.begin(), Y_coords.end());

    int deltaX = X_coords.back() - X_coords.front();
