#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <stdio.h>

using namespace std;

struct Server {
    int num;
    int din;
    int dout;
    int dc;

    Server() = default;
    Server(int num, int din, int dout, int dc) : num(num), din(din), dout(dout), dc(dc) {}
};

struct LogEntry {
    int time;
    int sender;
    int receiver;

    LogEntry() = default;
    LogEntry(int time, int sender, int receiver) : time(time), sender(sender), receiver(receiver) {}
};

bool operator<(const LogEntry& a, const LogEntry& b) {
    if (a.time == b.time)
        return a.receiver < b.receiver;
    return a.time < b.time;
}

int main() {
    int n, d, m;
    cin >> n >> d >> m;
    vector<Server> servers(n + 1);
    vector<vector<int>> dcs(d + 1, vector<int>(d + 1));
    vector<int> readyList;
    vector<LogEntry> log;

    for (int i = 1; i <= n; ++i) {
        int in, out, dc;
        cin >> in >> out >> dc;
        servers[i] = Server(i, in, out, dc);
    }

    for (int i = 1; i <= d; ++i) {
        for (int j = 1; j <= d; ++j) {
            cin >> dcs[i][j];
        }
    }

    readyList.push_back(1);
    vector<int> currentTime(n + 1, 0);
    while (!readyList.empty()) {
        int minTime = 1e9 + 9;
        for (const auto& serverNum : readyList) {
            minTime = min(minTime, currentTime[serverNum]);
        }
        int currentSender = 0;
        for (const auto& serverNum : readyList) {
            if (currentTime[serverNum] == minTime) {
                currentSender = serverNum;
                break;
            }
        }

        readyList.erase(find(readyList.begin(), readyList.end(), currentSender));

        int nextReceiver = 1;
        while (currentTime[nextReceiver] != 0)
            nextReceiver++;

        if (nextReceiver > n)
            break;

        int maxTime = 1e9 + 9;
        for (int curServer = 1; curServer <= n; ++curServer) {
            if (curServer != nextReceiver && currentTime[curServer] == 0) {
                int timeAtoB = max(servers[currentSender].dout, servers[curServer].din);
                timeAtoB *= m * dcs[servers[currentSender].dc][servers[curServer].dc];
                if (timeAtoB < maxTime) {
                    maxTime = timeAtoB;
                }
            }
        }

        currentTime[nextReceiver] = minTime + maxTime;
        log.emplace_back(currentTime[nextReceiver], currentSender, nextReceiver);

        if (find(readyList.begin(), readyList.end(), currentSender) == readyList.end())
            readyList.push_back(currentSender);

        if (nextReceiver != n)
            readyList.push_back(nextReceiver);
    }

    sort(log.begin(), log.end());

    for (const auto& el : log) {
        printf("Time %d: server %d received file from server %d\n", el.time, el.receiver, el.sender);
    }

    return 0;
}
