```rust
extern crate pest;
#[macro_use]
extern crate pest_derive;

use pest::Parser;
use std::error::Error;


#[derive(Parser)]
#[grammar = "expression.pest"]

pub struct ExpressionParser;


#[derive(Debug)]
enum ExprNode {
    Number(f64),
    Op(char, Box<ExprNode>, Box<ExprNode>),
    UnaryOp(char, Box<ExprNode>),
}


fn eval_expr(node: &ExprNode) -> Result<f64, Box<dyn Error>> {
    match *node {
        ExprNode::Number(val) => Ok(val),
        ExprNode::Op(op, ref left, ref right) => {
            let left_val = eval_expr(left)?;
            let right_val = eval_expr(right)?;
            match op {
                '+' => Ok(left_val + right_val),
                '-' => Ok(left_val - right_val),
                '*' => Ok(left_val * right_val),
                '/' => Ok(left_val / right_val),
                '^' => Ok(left_val.powf(right_val)),
                _ => Err(format!("Unsupported operator: {}", op).into()),
            }
        }
        ExprNode::UnaryOp(op, ref expr) => {
            let val = eval_expr(expr)?;
            match op {
                '√' => {
                    if val < 0.0 {
                        Err(format!("Cannot take square root of a negative number: {}", val).into())
                    } else {
                        Ok(val.sqrt())
                    }
                }
                _ => Err(format!("Unsupported unary operator: {}", op).into()),
            }
        }
    }
}


fn main() {
    let expr = "√(2 - 3) + (4 + 1)";
    let parse_tree = ExpressionParser::parse(Rule::expression, expr).unwrap();

    let mut ast_stack: Vec<ExprNode> = Vec::new();

    for token in parse_tree.flatten() {
        match token.as_rule() {
            Rule::number => {
                let number = token.as_str().parse::<f64>().unwrap();
                ast_stack.push(ExprNode::Number(number));
            }
            Rule::binary_op | Rule::unary_op => {
                let op = token.as_str().chars().next().unwrap();
                if token.as_rule() == Rule::binary_op {
                    let right = ast_stack.pop().unwrap();
                    let left = ast_stack.pop().unwrap();
                    ast_stack.push(ExprNode::Op(op, Box::new(left), Box::new(right)));
                } else {
                    let expr = ast_stack.pop().unwrap();
                    ast_stack.push(ExprNode::UnaryOp(op, Box::new(expr)));
                }
            }
            Rule::EOI | Rule::WHITESPACE | Rule::expression | Rule::term | Rule::factor | Rule::unary_expr => {}
            _ => unreachable!(),
        }
    }

    let ast = ast_stack.pop().unwrap();
    let result = eval_expr(&ast).unwrap();
    println!("{} = {}", expr, result);
}
```

Please note that the `expression.pest` file should contain the following grammar:

```
expression = _{ term ~ (binary_op ~ term)* }
term       = _{ unary_expr ~ (binary_op ~ unary_expr)* }
unary_expr = _{ (unary_op ~ factor) | factor }
factor     =  _{ "(" ~ expression ~ ")" | number }

number     = @{ ("+" | "-")? ~ ("0".."9")+ ("." ("0".."9")+)? }

binary_op  = _{ add_sub | mul_div | pow }
add_sub    =   { "+" | "-" }
mul_div    =   { "*" | "/" }
pow        =   { "^" }

unary_op   =   _{ sqrt }
sqrt       =   { "√" }

WHITESPACE = _{ (" " | "\t" | "\r" | "\n")+ }
EOI        = _{ ![_] }
```

