import java.util.Iterator;
import java.util.List;

class Parser {
    private Iterator<Token> tokenIter;
    private Token currentToken;

    public Parser(List<Token> tokens) {
        tokenIter = tokens.iterator();
        advance();
    }

    private void advance() {
        if (tokenIter.hasNext()) {
            currentToken = tokenIter.next();
            if (currentToken.type == Token.TokenType.WHITESPACE || currentToken.type == Token.TokenType.COMMENT) {
                advance();
            }
        } else {
            currentToken = null;
        }
    }

    private void expect(Token.TokenType type) {
        if (currentToken == null || currentToken.type != type) {
            throw new RuntimeException("Unexpected token: " + currentToken);
        }
        advance();
    }

    public void parse() {
        parseProgram();
    }

    private void parseProgram() {
        expect(Token.TokenType.KEYWORD);

        parseVarDescription();

