        while (currentToken != null && !"end".equals(currentToken.value)) {
            parseStatement();
            if (";".equals(currentToken.value)) {
                advance();
            }
        }

        expect(Token.TokenType.KEYWORD);
    }

    private void parseVarDescription() {
        expect(Token.TokenType.KEYWORD);

        while (currentToken != null && currentToken.type == Token.TokenType.IDENTIFIER) {
            parseIdentifier();
            if (",".equals(currentToken.value)) {
                advance();
            }
        }

        expect(Token.TokenType.SYMBOL);
    }

    private void parseIdentifier() {
        expect(Token.TokenType.IDENTIFIER);
    }

    private void parseStatement() {
        String keyword = currentToken.value;
        advance();

        if ("read".equals(keyword) || "write".equals(keyword)) {
            expect(Token.TokenType.SYMBOL);
            parseIdentifier();
            while (",".equals(currentToken.value)) {
                advance();
                parseIdentifier();
            }
            expect(Token.TokenType.SYMBOL);
        } else if ("if".equals(keyword)) {
            expect(Token.TokenType.SYMBOL);
            parseExpression();
            expect(Token.TokenType.SYMBOL);
            parseStatement();

            if ("else".equals(currentToken.value)) {
                advance();
                parseStatement();
            }
        } else if ("for".equals(keyword) || "do".equals(keyword) || "while".equals(keyword)) {
            parseLoop();
        } else {
            parseAssignment();
        }
    }

    private void parseExpression() {
        // Для простоты пропустим детали обработки выражений
        advance();
    }

    private void parseLoop() {
        expect(Token.TokenType.SYMBOL);
        parseExpression();
        expect(Token.TokenType.SYMBOL);
        parseStatement();
    }

    private void parseAssignment() {
        expect(Token.TokenType.KEYWORD);
        parseExpression();
    }
}

