import java.util.ArrayList;
import java.util.List;

class Token {
enum TokenType { KEYWORD, IDENTIFIER, NUMBER, SYMBOL, COMMENT, WHITESPACE }

public TokenType type;
public String value;

public Token(TokenType type, String value) {
this.type = type;
this.value = value;
}

@Override
public String toString() {
return String.format(“%s: %s”, type, value);
}
}

public class Lexer {
private static final String[] KEYWORDS = {
“program”, “var”, “begin”, “end”,
“int”, “float”, “bool”,
“if”, “else”, “for”, “do”, “while”, “loop”,
“read”, “write”
};

private static boolean isKeyword(String lexeme) {
for (String keyword : KEYWORDS) {
if (keyword.equals(lexeme)) {
return true;
}
}
return false;
}

private static boolean isIdentifierChar(char ch) {
return Character.isLetter(ch) || Character.isDigit(ch);
}

public static List<Token> tokenize(String source) {
List<Token> tokens = new ArrayList<>();
int pos = 0;
while (pos < source.length()) {
char ch = source.charAt(pos);
if (Character.isWhitespace(ch)) {
pos++;
} else if (isIdentifierChar(ch)) {
int begin = pos;
while (pos < source.length() && isIdentifierChar(source.charAt(pos))) {
pos++;
}
String lexeme = source.substring(begin, pos);
if (isKeyword(lexeme)) {
tokens.add(new Token(Token.TokenType.KEYWORD, lexeme));
} else {
tokens.add(new Token(Token.TokenType.IDENTIFIER, lexeme));
}
} else if (Character.isDigit(ch)) {
int begin = pos;
while (pos < source.length() && (Character.isDigit(source.charAt(pos)) ||
source.charAt(pos) == ‘.’)) {
pos++;
}
String lexeme = source.substring(begin, pos);
tokens.add(new Token(Token.TokenType.NUMBER, lexeme));
} else if (ch == ‘/’ && pos + 1 < source.length() && source.charAt(pos + 1) == ‘') {
int begin = pos;
pos += 2;
while (pos + 1 < source.length() && (source.charAt(pos) != '’ || source.charAt(pos + 1) != ‘/’)) {
pos++;
}
if (pos + 1 < source.length()) {
pos += 2;
}
String lexeme = source.substring(begin, pos);
tokens.add(new Token(Token.TokenType.COMMENT, lexeme));
} else {
tokens.add(new Token(Token.TokenType.SYMBOL, String.valueOf(ch)));
pos++;
}
}
return tokens;
}

public static void main(String[] args) {
String source = “/* Test program */\n” +
“program var int a, b;\n” +
“begin\n” +
" read(a, b);\n" +
" if (a > b) then write(a) else write(b);\n" +
“end”;
List<Token> tokens = tokenize(source);
for (Token token : tokens) {
System.out.println(token);
}
}
}

