```java
import java.util.Iterator;
import java.util.List;

class Parser {
    private Iterator<Token> tokenIter;
    private Token currentToken;

    public Parser(List<Token> tokens) {
        tokenIter = tokens.iterator();
        advance();
    }

    private void advance() {
        if (tokenIter.hasNext()) {
            currentToken = tokenIter.next();
            if (currentToken.type == Token.TokenType.WHITESPACE || currentToken.type == Token.TokenType.COMMENT) {
                advance();
            }
        } else {
            currentToken = null;
        }
    }

    private void expect(Token.TokenType type, String value) {
        if (currentToken == null || currentToken.type != type || !currentToken.value.equals(value)) {
            throw new RuntimeException("Unexpected token: " + currentToken);
        }
        advance();
    }

    public void parse() {
        parseProgram();
    }

    private void parseProgram() {
        expect(Token.TokenType.KEYWORD, "program");
        expect(Token.TokenType.KEYWORD, "var");

        parseDescription();

        expect(Token.TokenType.KEYWORD, "begin");

        while (currentToken != null && !"end".equals(currentToken.value)) {
            parseStatement();

            if (";".equals(currentToken.value)) {
                advance();
            }
        }

        expect(Token.TokenType.KEYWORD, "end");
    }

    private void parseDescription() {
        parseType();
        parseIdentifier();

        while (currentToken != null && ",".equals(currentToken.value)) {
            advance();
            parseIdentifier();
        }
    }

    private void parseType() {
        if (currentToken.type != Token.TokenType.KEYWORD || (!"int".equals(currentToken.value) && !"float".equals(currentToken.value) && !"bool".equals(currentToken.value))) {
            throw new RuntimeException("Unexpected token (expected type keyword): " + currentToken);
        }
        advance();
    }

    private void parseIdentifier() {
        expect(Token.TokenType.IDENTIFIER, currentToken.value);
    }

    private void parseStatement() {
        switch (currentToken.value) {
            case "if":
                parseIfStatement();
                break;
            case "for":
                parseForStatement();
                break;
            case "do":
                parseDoWhileStatement();
                break;
            case "read":
            case "write":
                parseReadWriteStatement();
                break;
            default:
                parseAssignment();
        }
    }

    private void parseIfStatement() {
        advance();
        expect(Token.TokenType.SYMBOL, "(");
        parseExpression();
        expect(Token.TokenType.SYMBOL, ")");
        parseStatement();

        if ("else".equals(currentToken.value)) {
            advance();
            parseStatement();
        }
    }

    private void parseForStatement() {
        advance();
        expect(Token.TokenType.SYMBOL, "(");

        if (!";".equals(currentToken.value)) {
            parseExpression();
        }
        expect(Token.TokenType.SYMBOL, ";");

        if (!";".equals(currentToken.value)) {
            parseExpression();
        }
        expect(Token.TokenType.SYMBOL, ";");

        if (!")".equals(currentToken.value)) {
            parseExpression();
        }
        expect(Token.TokenType.SYMBOL, ")");

        parseStatement();
    }

    private void parseDoWhileStatement() {
        advance();
        expect(Token.TokenType.KEYWORD, "while");
        parseExpression();
        parseStatement();
        expect(Token.TokenType.KEYWORD, "loop");
    }

    private void parseReadWriteStatement() {
        String keyword = currentToken.value;
        advance();
        expect(Token.TokenType.SYMBOL, "(");
        parseIdentifier();

        while (",".equals(currentToken.value)) {
            advance();
            parseIdentifier();
        }

        expect(Token.TokenType.SYMBOL, ")");
    }

    private void parseAssignment() {
        parseIdentifier();
        expect(Token.TokenType.KEYWORD, "ass");
        parseExpression();
    }

    private void parseExpression() {
        advance(); // Опустим детали обработки выражений для упрощения кода
    }
}

public class Main {
    public static void main(String[] args) {
        String source = "/* Test program */\n" +
                "program var int a, b;\n" +
                "begin\n" +
                "  read(a, b);\n" +
                "  if (a > b) then write(a) else write(b);\n" +
                "end";
        List<Token> tokens = Lexer.tokenize(source);

        Parser parser = new Parser(tokens);
        parser.parse();

        System.out.println("Parsed successfully");
    }
}
