        bool spawn_near_s = (rand() % 100) < 30;
        if (spawn_near_s && !neighbors.empty()) {
            int idx = rand() % neighbors.size();
            t_row = neighbors[idx].first;
            t_col = neighbors[idx].second;
        }
        else {
            t_row = rand() % n;
            t_col = rand() % m;
        }
    } while (grid[t_row][t_col] != '.');

    grid[t_row][t_col] = 'T';

    for (int i = 0; i < num_obstacles; i++) {
