В целом, алгоритм для генерации сетки с S и T такой:

1. Сначала выбирают случайную клетку под S.
2. Затем выбирают случайную пустую клетку под T, находящуюся радиусе не менее 2 клеток от S. Если подходящих клеток нет, повторяются шаги 1 и 2, пока не находится соответствующая клетка.

Также можно добавить проверку, чтобы S и T не находились рядом при генерации остальных точек на сетке.

Вот код, который реализует этот алгоритм:

```c++
vector<vector<char>> generateGrid(int n, int m)
{
    vector<vector<char>> grid(n, vector<char>(m, '.'));

    int num_cells = n *m;
    int num_obstacles = num_cells / 4;

    int s_row, s_col, t_row, t_col;
    do {
        // Choose a random cell for S
        s_row = rand() % n;
        s_col = rand() % m;

        bool found_t = false;
        while (!found_t) {
            // Choose a random cell for T within a certain radius of S
            t_row = rand() % n;
            t_col = rand() % m;

            if (grid[t_row][t_col] != '.') {
                // If the cell is not empty, skip
                continue;
            }

            // Check if the T cell is far enough from S
            if (abs(t_row - s_row) + abs(t_col - s_col) < 4) {
                continue;
            }

            // Check if S and T are adjacent
            if (abs(t_row - s_row) <= 1 && abs(t_col - s_col) <= 1) {
                // 30% chance to keep S and T together
                if (rand() % 100 < 30) {
                    found_t = true;
                }
            } else {
                found_t = true;
            }
        }

        // Mark S and T cells
        grid[s_row][s_col] = 'S';
        grid[t_row][t_col] = 'T';

    } while (false);

    // Add other S and T cells
    int num_s_t = rand() % (num_cells - num_obstacles - 2) + 2;
    for (int i = 2; i < num_s_t; i++) {
        int row, col;
        do {
            row = rand() % n;
            col = rand() % m;
        } while (grid[row][col] != '.' || abs(row - s_row) + abs(col - s_col) < 4 ||
                 abs(row - t_row) + abs(col - t_col) < 4);

        if (i % 2 == 0) {
            grid[row][col] = 'S';
        } else {
            grid[row][col] = 'T';
        }
    }

    // Add obstacles
    for (int i = 0; i < num_obstacles; i++) {
        int row, col;
        do {
            row = rand() % n;
            col = rand() % m;
        } while (grid[row][col] != '.' && (row != s_row || col != s_col) && (row != t_row || col != t_col));

        grid[row][col] = '#';
    }

    return grid;
}
```

