2. Update the `script.js` file to include a new function `addRowWithSelect()` and modify the `addRow()` function:

```javascript
// Function to create a select element with options
function createSelect() {
    const select = document.createElement('select');
    const options = ['Option 1', 'Option 2', 'Option 3'];

    options.forEach(optionText => {
      const option = document.createElement('option');
      option.text = optionText;
      option.value = optionText;
      select.add(option);
    });

    return select;
}

// Function to make a table cell editable with a select element
function makeCellEditableWithSelect(cell) {
    cell.onclick = function () {
        const select = createSelect();

        select.onchange = function () {
            cell.innerHTML = this.value;
            makeCellEditableWithSelect(cell);
        };

        this.innerHTML = '';
        this.appendChild(select);
    };
}

// Function to add a table row
function addRow() {
    const table = document.getElementById('myTable');
    const row = table.insertRow(-1);

    // Adding three cells to the row
    for (let i = 0; i < 3; i++) {
        let cell = row.insertCell(i);
        cell.innerHTML = 'Editable Cell';

        // Custom cell configuration
        cell.style.backgroundColor = i === 0 ? 'green' : (i === 1 ? 'blue' : 'red');

        makeCellEditable(cell);
    }
}

// Function to add a table row with a select element
function addRowWithSelect() {
    const table = document.getElementById('myTable');
    const row = table.insertRow(-1);

    // Adding three cells to the row
    for (let i = 0; i < 3; i++) {
        let cell = row.insertCell(i);
        cell.innerHTML = 'Editable Cell with Select';

        // Custom cell configuration
        cell.style.backgroundColor = i === 0 ? 'green' : (i === 1 ? 'blue' : 'red');

        makeCellEditableWithSelect(cell);
    }
}

// Function to remove a table row
function removeRow() {
    const table = document.getElementById('myTable');
    const rowCount = table.rows.length;

    if (rowCount > 0) {
        table.deleteRow(rowCount - 1);
    }
}
```

Now, you have two functions for adding rows: `addRow()` creates a row with editable cells containing text inputs, while `addRowWithSelect()` adds a row with editable cells containing dropdown `select` elements.

