        }
    }

    applyOperation := func(op Token, args ...float64) (float64, error) {
        switch op.Type {
        case Plus:
            return args[0] + args[1], nil
        case Minus:
            return args[0] - args[1], nil
        case Multiply:
            return args[0] * args[1], nil
        case Divide:
            return args[0] / args[1], nil
        case Power:
            return math.Pow(args[0], args[1]), nil
        case Sqrt:
            return math.Sqrt(args[0]), nil
        case Root:
            return math.Pow(args[1], 1.0 / args[0]), nil
        case Sin:
            return math.Sin(DegressToRadian(args[0])), nil
        case Cos:
            return math.Cos(DegressToRadian(args[0])), nil
        case Tan:
            return math.Tan(DegressToRadian(args[0])), nil
        case Cot:
            return 1 / math.Tan(DegressToRadian(args[0])), nil
        default:
            return 0, fmt.Errorf("Неизвестная операция: %v", op.Value)
        }
    }

    var numStack []float64
    var opStack []Token

    handleOperation := func() error {
        op := opStack[len(opStack)-1]
        opStack = opStack[:len(opStack)-1]

        var args []float64
        if op.Type == Sqrt || op.Type == Sin || op.Type == Cos || op.Type == Tan || op.Type == Cot {
            args = []float64{numStack[len(numStack)-1]}
            numStack = numStack[:len(numStack)-1]
        } else if op.Type == Root {
            args = []float64{numStack[len(numStack)-2], numStack[len(numStack)-1]}
            numStack = numStack[:len(numStack)-2]
        } else {
            args = []float64{numStack[len(numStack)-2], numStack[len(numStack)-1]}
            numStack = numStack[:len(numStack)-2]
        }

        res, err := applyOperation(op, args...)
        if err != nil {
            return err
        }

        numStack = append(numStack, res)
        return nil
    }

    for _, token := range tokens {
        switch token.Type {
        case Number:
            val, err := strconv.ParseFloat(token.Value, 64)
            if err != nil {
                return 0, err
            }
            numStack = append(numStack, val)
        case Variable:
            val, ok := vars[token.Value]
            if !ok {
                return 0, fmt.Errorf("Отсутствует значение для переменной: %v", token.Value)
            }
            numStack = append(numStack, val)
        case Plus, Minus, Multiply, Divide, Power, Sqrt, Sin, Cos, Tan, Cot, Root:
            for len(opStack) > 0 && precedence(token.Type) <= precedence(opStack[len(opStack)-1].Type) {
                if err := handleOperation(); err != nil {
                    return 0, err
                }
            }
            opStack = append(opStack, token)
        case LeftParen:
            opStack = append(opStack, token)
        case RightParen:
            for len(opStack) > 0 && opStack[len(opStack)-1].Type != LeftParen {
                if err := handleOperation(); err != nil {
                    return 0, err
                }
            }
            if len(opStack) > 0 && opStack[len(opStack)-1].Type == LeftParen {
                opStack = opStack[:len(opStack)-1]
            }
        }
    }

    for len(opStack) > 0 {
        if err := handleOperation(); err != nil {
            return 0, err
        }
    }

    if len(numStack) != 1 {
        return 0, fmt.Errorf("Неверное количество аргументов")
    }

    return numStack[0], nil
}
