Для переписывания интерпретатора можно предложить следующий шаблон:

1. Лексер: сканирует выражение и создает список токенов.
2. Парсер: просматривает список токенов, созданный лексером, и создает абстрактное синтаксическое дерево (AST).
3. Вычислитель: вычисляет результат, обходя AST.

Определим типы для наших узлов AST:

```go
type Node interface {
	Eval() (float64, error)
}

type NumberNode struct {
	Value float64
}

type VariableNode struct {
	Name string
}

type UnaryOpNode struct {
	Op    TokenType
	Child Node
}

type BinaryOpNode struct {
	Op  TokenType
	LHS Node
	RHS Node
}

type FuncCallNode struct {
	FuncName string
	Args     []Node
}
```

Этот код добавляет интерфейс `Eval` в узлы синтаксического дерева, чтобы вычислитель мог использовать этот интерфейс для вычисления результата. Здесь также определяются несколько структур для представления разных видов узлов, таких как `NumberNode`, `VariableNode`, `UnaryOpNode`, `BinaryOpNode` и `FuncCallNode`, которые соответствуют различным операциям и значениям вашего выражения.

Далее, давайте реализуем некоторые методы для наших узлов:

```go
func (n *NumberNode) Eval() (float64, error) {
	return n.Value, nil
}

func (n *VariableNode) Eval(variables map[string]float64) (float64, error) {
	value, ok := variables[n.Name]
	if !ok {
		return 0, fmt.Errorf("Неизвестное значение переменной: %v", n.Name)
	}
	return value, nil
}

func (n *UnaryOpNode) Eval(variables map[string]float64) (float64, error) {
	childValue, err := n.Child.Eval(variables)
	if err != nil {
		return 0, err
	}

	switch n.Op {
	case Plus:
		return childValue, nil
	case Minus:
		return -childValue, nil
	default:
		return 0, fmt.Errorf("Неизвестная унарная операция: %v", n.Op)
	}
}

func (n *BinaryOpNode) Eval(variables map[string]float64) (float64, error) {
	lhs, err := n.LHS.Eval(variables)
	if err != nil {
		return 0, err
	}

	rhs, err := n.RHS.Eval(variables)
	if err != nil {
		return 0, err
	}

	switch n.Op {
	case Plus:
		return lhs + rhs, nil
	case Minus:
		return lhs - rhs, nil
	case Multiply:
		return lhs * rhs, nil
	case Divide:
		return lhs / rhs, nil
	case Power:
		return math.Pow(lhs, rhs), nil
	default:
		return 0, fmt.Errorf("Неизвестная бинарная операция: %v", n.Op)
	}
}

func (n *FuncCallNode) Eval(variables map[string]float64) (float64, error) {
	args := make([]float64, len(n.Args))
	for i, arg := range n.Args {
		result, err := arg.Eval(variables)
		if err != nil {
			return 0, err
		}
		args[i] = result
	}

	switch n.FuncName {
	case "sin":
		return math.Sin(args[0]), nil
	case "cos":
		return math.Cos(args[0]), nil
	case "tan":
		return math.Tan(args[0]), nil
	case "cot":
		return 1 / math.Tan(args[0]), nil
	case "sqrt":
		return math.Sqrt(args[0]), nil
	case "root":
		return math.Pow(args[1], 1.0/args[0]), nil
	default:
		return 0, fmt.Errorf("Неизвестная функция: %v", n.FuncName)
	}
}
