func eval(root Node, variableMaps ...map[string]float64) (float64, error) {
	variables := make(map[string]float64)
	for _, variableMap := range variableMaps {
		for key, value := range variableMap {
			variables[key] = value
		}
	}
	return root.Eval(variables)
}
