Here is a JavaScript code to calculate Fibonacci numbers up to one million:

```javascript
function calculateFibonacci(limit) {
  const fibonacciNumbers = [0, 1];

  while (fibonacciNumbers[fibonacciNumbers.length - 1] < limit) {
    const nextNumber =
      fibonacciNumbers[fibonacciNumbers.length - 1] +
      fibonacciNumbers[fibonacciNumbers.length - 2];

    if (nextNumber > limit) {
      break;
    }

    fibonacciNumbers.push(nextNumber);
  }

  return fibonacciNumbers;
}

const limit = 1000000;
