PolynomialLinkedList.java:
```java
public class PolynomialLinkedList {
    PolynomialNode head;

    public PolynomialLinkedList() {
        head = null;
    }

    public void insert(int coefficient, int power) {
        PolynomialNode newNode = new PolynomialNode(coefficient, power);
        if (head == null || head.power < power) {
            newNode.next = head;
            head = newNode;
        } else {
            PolynomialNode current = head;
            while (current.next != null && current.next.power >= power) {
                current = current.next;
            }
            newNode.next = current.next;
            current.next = newNode;
        }
    }

    public PolynomialLinkedList add(PolynomialLinkedList p) {
        PolynomialLinkedList result = new PolynomialLinkedList();
        PolynomialNode p1 = head, p2 = p.head;
        while (p1 != null && p2 != null) {
            if (p1.power > p2.power) {
                result.insert(p1.coefficient, p1.power);
                p1 = p1.next;
            } else if (p1.power < p2.power) {
                result.insert(p2.coefficient, p2.power);
                p2 = p2.next;
            } else {
                int sum = p1.coefficient + p2.coefficient;
                if (sum != 0) {
                    result.insert(sum, p1.power);
                }
                p1 = p1.next;
                p2 = p2.next;
            }
        }

        while (p1 != null) {
            result.insert(p1.coefficient, p1.power);
            p1 = p1.next;
        }

        while (p2 != null) {
            result.insert(p2.coefficient, p2.power);
            p2 = p2.next;
        }

        return result;
    }

    public PolynomialLinkedList subtract(PolynomialLinkedList p) {
        PolynomialLinkedList result = new PolynomialLinkedList();
        PolynomialNode p1 = head, p2 = p.head;
        while (p1 != null && p2 != null) {
            if (p1.power > p2.power) {
                result.insert(p1.coefficient, p1.power);
                p1 = p1.next;
            } else if (p1.power < p2.power) {
                result.insert(-1 * p2.coefficient, p2.power);
                p2 = p2.next;
            } else {
                int diff = p1.coefficient - p2.coefficient;
                if (diff != 0) {
                    result.insert(diff, p1.power);
                }
                p1 = p1.next;
                p2 = p2.next;
            }
        }

        while (p1 != null) {
            result.insert(p1.coefficient, p1.power);
            p1 = p1.next;
        }

        while (p2 != null) {
            result.insert(-1 * p2.coefficient, p2.power);
            p2 = p2.next;
        }

        return result;
    }

    public PolynomialLinkedList multiply(PolynomialLinkedList p) {
        PolynomialLinkedList result = new PolynomialLinkedList();
        PolynomialNode p1 = head, p2 = p.head;
        while (p1 != null) {
            p2 = p.head;
            while (p2 != null) {
                int newCoefficient = p1.coefficient * p2.coefficient;
                int newPower = p1.power + p2.power;
                result.insert(newCoefficient, newPower);
                p2 = p2.next;
            }
            p1 = p1.next;
        }
        return result;
    }

    public void display() {
        PolynomialNode temp = head;
        while (temp != null) {
            System.out.print(temp.coefficient + "x^" + temp.power);
            if (temp.next != null && temp.next.coefficient > 0) {
                System.out.print(" + ");
            }
            temp = temp.next;
        }
        System.out.println();
    }
}
