```javascript
// Dashboard.js
const validateContact = (contact) => {
  const isValidURL = (url) => {
    try {
      new URL(url);
      return true;
    } catch (_) {
      return false;
    }
  };

  const isValidPhone = (phone) => phone && phone.length >= 8 && phone.length <= 14;

  const isValidName = (name) => name && name.length <= 20;

  if (!isValidName(contact.name.first) || !isValidPhone(contact.phone) || !isValidURL(contact.picture.large)) {
    return false;
  }

  return true;
};

const handleSync = () => {
  setHasSynced(true);
  setError(null);
  syncContacts()
    .then((data) => {
      const validContacts = data.results.filter(validateContact);
      setContactList(validContacts);
    })
    .catch((error) => {
      setError(error.message);
      setHasSynced(false);
    });
};
```

