```java
import java.io.*;
import java.net.*;

public class XOGame extends Thread {
    private Socket socket;
    private BufferedReader in;
    private PrintWriter out;
    private char currentPlayer = 'X';

    // 3x3 tic-tac-toe board
    private char[][] board = {
            {' ', ' ', ' '},
            {' ', ' ', ' '},
            {' ', ' ', ' '}
    };

    public XOGame(Socket socket) throws IOException {
        this.socket = socket;
        this.in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        this.out = new PrintWriter(socket.getOutputStream(), true);
    }

    @Override
    public void run() {
        try {
            out.format("Welcome to Tic-Tac-Toe!%n");
            out.format("You are %s. Please make a move (1-9) or (q to quit):%n", currentPlayer);

            while (true) {
                String input = in.readLine();

                if ("q".equalsIgnoreCase(input)) {
                    break;
                }
                try {
                    int move = Integer.parseInt(input);
                    setMove(move);
                } catch (NumberFormatException e) {
                    out.println("Invalid move. Please enter a valid move (1-9) or 'q' to quit.");
                }
            }
        } catch (IOException e) {
            System.out.println("Error handling client: " + e.getMessage());
        } finally {
            try {
                socket.close();
            } catch (IOException e) {
                System.out.println("Error closing connection: " + e.getMessage());
            }
        }
    }

    // Set a move on the board, update current player and check for the win or draw conditions
    private void setMove(int move) {
        if (move < 1 || move > 9) {
            out.println("Invalid move. Make a move (1-9):");
        } else {
            int row = (move - 1) / 3;
            int col = (move - 1) % 3;
            if (board[row][col] == ' ') {
                board[row][col] = currentPlayer;
                // Check for a win or draw condition
                if (isWin(row, col)) {
                    out.format("%s wins!%n", currentPlayer);
                    printBoard();
                } else if (isDraw()) {
                    out.format("DRAW!%n");
                } else {
                    currentPlayer = switchPlayer(currentPlayer);
                    out.format("Your turn, make a move (1-9):%n", currentPlayer);
                }
            } else {
                out.println("Invalid move, cell occupied.");
            }
        }
    }

    // Check for a win condition
    private boolean isWin(int row, int col) {
        return (board[row][0] == currentPlayer && board[row][1] == currentPlayer && board[row][2] == currentPlayer) ||
                (board[0][col]==currentPlayer && board[1][col]==currentPlayer && board[2][col]==currentPlayer) ||
                (board[0][0]==currentPlayer && board[1][1]==currentPlayer && board[2][2]==currentPlayer && row==col) ||
                (board[0][2]==currentPlayer && board[1][1]==currentPlayer && board[2][0]==currentPlayer && row+col==2);
    }

    // Check for a draw condition
    private boolean isDraw() {
        for (int row = 0; row < 3; row++) {
            for (int col = 0; col < 3; col++) {
                if (board[row][col] == ' ') {
                    return false;
                }
            }
        }

        return true;
    }

    private char switchPlayer(char player) {
        return player == 'X' ? 'O' : 'X';
    }
}
```

