public class LoadBalancingInterceptor implements Interceptor {
    private AtomicLong next = new AtomicLong();

    @Override
    public Response intercept(Chain chain) throws IOException {
        Request original = chain.request();
        HttpUrl originalHttpUrl = original.url();

        // Replace with your instances / endpoints list
        List<String> instances = Arrays.asList("http://instance1:port", "http://instance2:port");

        // Using round robin to choose an instance
        int index = (int) (next.getAndIncrement() % instances.size());
        String selectedInstance = instances.get(index);

        // Creating the new URL with the chosen instance
        HttpUrl newUrl = HttpUrl.parse(selectedInstance).newBuilder()
                .encodedPath(originalHttpUrl.encodedPath())
                .query(originalHttpUrl.query())
                .build();

        // Creating a new request using the new URL
        Request newRequest = original.newBuilder().url(newUrl).build();

        // Proceed with the new request
        return chain.proceed(newRequest);
    }
}
