    LinkedList createLinkedList(String polynomial) {
        LinkedList list = new LinkedList();
        String[] terms = polynomial.split("\\+");

        for (String term : terms) {
            String[] coefPower = term.split("x\\^");
            int coef = Integer.parseInt(coefPower[0].trim());
            int power = Integer.parseInt(coefPower[1].trim());
            list.insert(coef, power);
        }

        return list;
    }

    LinkedList add(LinkedList p1, LinkedList p2) {
        LinkedList result = new LinkedList();

        Node temp1 = p1.head;
        Node temp2 = p2.head;

        while (temp1 != null && temp2 != null) {
            if (temp1.power > temp2.power) {
                result.insert(temp1.coefficient, temp1.power);
                temp1 = temp1.next;
            } else if (temp1.power < temp2.power) {
                result.insert(temp2.coefficient, temp2.power);
                temp2 = temp2.next;
            } else {
                int sum = temp1.coefficient + temp2.coefficient;
                if (sum != 0) {
                    result.insert(sum, temp1.power);
                }
                temp1 = temp1.next;
                temp2 = temp2.next;
            }
        }

        while (temp1 != null) {
            result.insert(temp1.coefficient, temp1.power);
            temp1 = temp1.next;
        }

        while (temp2 != null) {
            result.insert(temp2.coefficient, temp2.power);
            temp2 = temp2.next;
        }

        return result;
    }

    LinkedList subtract(LinkedList p1, LinkedList p2) {
        LinkedList result = new LinkedList();

        Node temp1 = p1.head;
        Node temp2 = p2.head;

        while (temp1 != null && temp2 != null) {
            if (temp1.power > temp2.power) {
                result.insert(temp1.coefficient, temp1.power);
                temp1 = temp1.next;
            } else if (temp1.power < temp2.power) {
                result.insert(-temp2.coefficient, temp2.power);
                temp2 = temp2.next;
            } else {
                int diff = temp1.coefficient - temp2.coefficient;
                if (diff != 0) {
                    result.insert(diff, temp1.power);
                }
                temp1 = temp1.next;
                temp2 = temp2.next;
            }
        }

        while (temp1 != null) {
            result.insert(temp1.coefficient, temp1.power);
            temp1 = temp1.next;
        }

        while (temp2 != null) {
            result.insert(-temp2.coefficient, temp2.power);
            temp2 = temp2.next;
        }

        return result;
    }

    LinkedList multiply(LinkedList p1, LinkedList p2) {
        LinkedList result = new LinkedList();

        Node temp1 = p1.head;
        Node temp2;

        while (temp1 != null) {
            temp2 = p2.head;

            while (temp2 != null) {
                int coef = temp1.coefficient * temp2.coefficient;
                int power = temp1.power + temp2.power;

                result.insert(coef, power);
                temp2 = temp2.next;
            }

            temp1 = temp1.next;
        }

        return result;
    }
}

class LinkedList {
    Node head;

    void insert(int coefficient, int power) {
        Node newNode = new Node(coefficient, power);

        if (head == null) {
            head = newNode;
            return;
        }

        Node current = head;
        Node previous = null;

        while (current != null && current.power > power) {
            previous = current;
            current = current.next;
        }

        if (current != null && current.power == power) {
            current.coefficient += coefficient;
            return;
        }

        if (previous == null) {
            newNode.next = head;
            head = newNode;
        } else {
            newNode.next = current;
            previous.next = newNode;
        }
    }

    void print() {
        Node temp = head;

        while (temp != null) {
            System.out.print(temp.coefficient + "x^" + temp.power);

            if (temp.next != null) {
                System.out.print(" + ");
            }

            temp = temp.next;
        }

        System.out.println();
    }
}

class Node {
    int coefficient;
    int power;
    Node next;

    Node(int coefficient, int power) {
        this.coefficient = coefficient;
        this.power = power;
    }
}
