void sort_print_high_mileage(car *cars, int n, int mileage_limit) {
car *high_mileage_cars = nullptr;
int count = 0;

for (int i = 0; i < n; i++) {
if (cars[i].mileage > mileage_limit) {
count++;
car *temp = new car[count];
if (high_mileage_cars != nullptr) {
memcpy(temp, high_mileage_cars, (count - 1) * sizeof(car));
delete[] high_mileage_cars;
}
temp[count - 1] = cars[i];
high_mileage_cars = temp;
}
}

for (int i = 0; i < count - 1; i++) {
for (int j = 0; j < count - i - 1; j++) {
if (strcmp(high_mileage_cars[j].owner.surname, high_mileage_cars[j + 1].owner.surname) > 0) {
car temp = high_mileage_cars[j];
high_mileage_cars[j] = high_mileage_cars[j + 1];
high_mileage_cars[j + 1] = temp;
}
}
}

cout << "Owners with mileage greater than the specified limit (sorted by alphabet): " << endl;
for (int i = 0; i < count; i++) {
cout << high_mileage_cars[i].brand << " | " << high_mileage_cars[i].owner.name << " | " << high_mileage_cars[i].owner.surname << " | " << high_mileage_cars[i].owner.patronymic
<< " | " << high_mileage_cars[i].engine_power << " | " << high_mileage_cars[i].mileage << " | " << high_mileage_cars[i].last_service.day << " " << high_mileage_cars[i].last_service.month << " " << high_mileage_cars[i].last_service.year << endl;
}
cout << endl;

if (high_mileage_cars != nullptr) {
delete[] high_mileage_cars;
}
}

