统一肤色的方法有很多种，这里介绍一种基于直方图规范化的方法。我们将使用 OpenCV（在 Node.js 中为 'opencv4nodejs' 包）实现这个功能。

```javascript
const cv = require('opencv4nodejs');

function equalizeHistogram(image) {
  // 转换到 YCrCb 色彩空间
  const ycrcb = image.cvtColor(cv.COLOR_BGR2YCrCb);

  // 分离 Y 通道
  const channels = ycrcb.split();
  const yChannel = channels[0];

  // 均衡化 Y 通道的直方图
  const equalizedYChannel = yChannel.equalizeHist();

  // 用处理后的 Y 通道替换原来的通道
  channels[0] = equalizedYChannel;

  // 合并通道
  const equalizedYCrCb = new cv.Mat(channels);

  // 将图像转换回 BGR 色彩空间
  const equalizedBGR = equalizedYCrCb.cvtColor(cv.COLOR_YCrCb2BGR);

  return equalizedBGR;
}

// 读取图像
const inputImage = cv.imread('input.jpg');

// 应用肤色统一处理
const outputImage = equalizeHistogram(inputImage);

// 保存处理后的图像
cv.imwrite('output.jpg', outputImage);
```

