    let in_img_lab = new cv.Mat();

    cv.cvtColor(ref_img, ref_img_lab, cv.COLOR_BGR2Lab);
    cv.cvtColor(in_img, in_img_lab, cv.COLOR_BGR2Lab);

    let in_avg = new cv.Mat.ones(in_img.rows, in_img.cols, cv.CV_32FC3);
    let in_std = new cv.Mat.ones(in_img.rows, in_img.cols, cv.CV_32FC3);
    let ref_avg = new cv.Mat.ones(in_img.rows, in_img.cols, cv.CV_32FC3);
    let ref_std = new cv.Mat.ones(in_img.rows, in_img.cols, cv.CV_32FC3);

    let mask_all = new cv.Mat.zeros(in_img.rows, in_img.cols, cv.CV_32FC3);

    for (let i = 0; i < in_mask_lists.length; i++) {
        let in_mask = in_mask_lists[i];
        let ref_mask = ref_mask_lists[i];

        if (in_mask !== null && ref_mask !== null) {
