            cv.meanStdDev(in_img_lab, in_avg_tmp, in_std_tmp, in_mask);

            cv.copyTo(in_avg, in_avg_tmp.reshape(1,1,3), in_mask);
            cv.copyTo(in_std, in_std_tmp.reshape(1,1,3), in_mask);

            let ref_avg_tmp = new cv.Mat();
            let ref_std_tmp = new cv.Mat();

            cv.meanStdDev(ref_img_lab, ref_avg_tmp, ref_std_tmp, ref_mask);

            cv.copyTo(ref_avg, ref_avg_tmp.reshape(1,1,3), in_mask);
            cv.copyTo(ref_std, ref_std_tmp.reshape(1,1,3), in_mask);

            for (let row = 0; row < in_mask.rows; row++) {
                for (let col = 0; col < in_mask.cols; col++) {
                    if (in_mask.ucharPtr(row, col)[0] !== 0) {
                        mask_all.ucharPtr(row, col)[0] = 1;
                    }
                }
            }
        }
    }

    for (let row = 0; row < in_std.rows; row++) {
        for (let col = 0; col < in_std.cols; col++) {
            if (in_std.floatPtr(row, col)[0] === 0) {
                in_std.floatPtr(row, col)[0] = 1;
            }
        }
    }

    let transfered_lab = new cv.Mat();
    cv.subtract(in_img_lab, in_avg, transfered_lab);
    cv.divide(transfered_lab, in_std, transfered_lab);
    cv.multiply(transfered_lab, ref_std, transfered_lab);
    cv.add(transfered_lab, ref_avg, transfered_lab);

    cv.threshold(transfered_lab, transfered_lab, 0, 255, cv.THRESH_TOZERO);
    cv.threshold(transfered_lab, transfered_lab, 255, 255, cv.THRESH_TRUNC);

    let out_img = new cv.Mat();

    cv.cvtColor(transfered_lab, out_img, cv.COLOR_Lab2BGR);

    if (in_mask_lists[0] !== null && ref_mask_lists[0] !== null) {
        for (let row = 0; row < mask_all.rows; row++) {
            for (let col = 0; col < mask_all.cols; col++) {
                if (mask_all.floatPtr(row, col)[0] === 0) {
                    for (let c = 0; c < 3; c++) {
                        out_img.ucharPtr(row, col)[c] = in_img.ucharPtr(row, col)[c];
                    }
                }
            }
        }
    }

    return out_img;
}
```

