Here is the JavaScript implementation of the Reinhard algorithm using the OpenCV.js library:

```javascript
async function reinhard_tonemapping(src) {
    // Initialize the constants for the algorithm
    const scaleFactor = 1 / 255;
    const key = 0.18; // Key value (controls brightness)
    const corrFactor = 0.36; // Correction factor (controls contrast)
    const white = 256;

    // Calculate log average luminance
    const logSum = (src.rows * src.cols) * Math.log(Number.MIN_VALUE + key);
    let Lw = new cv.Mat();
    cv.cvtColor(src, Lw, cv.COLOR_BGR2GRAY);
    Lw.convertTo(Lw, cv.CV_32F, scaleFactor);
    let logLw = new cv.Mat();
    cv.log(Lw, logLw);
    let logAvg = (cv.sumElems(logLw).val[0] / (src.rows * src.cols)) * key;

    // Calculate luminance scaling factor
    const a = logAvg / (1.0 + Math.pow(corrFactor, 8));

    // Compute the Reinhard algorithm
    logLw.convertTo(Lw, cv.CV_32F, a);
    let Ld = new cv.Mat();
    cv.add(Lw, 1.0, Ld);
    cv.divide(Lw, Ld, Ld);

    let out_img = new cv.Mat();
    cv.cvtColor(src, out_img, cv.COLOR_BGR2YCrCb);
    let channels = new cv.MatVector(); 
    cv.split(out_img, channels);
    channels.set(0, Ld);
    cv.merge(channels, out_img);

    let output = new cv.Mat();
    out_img.convertTo(output, cv.CV_8UC3);
    cv.cvtColor(output, output, cv.COLOR_YCrCb2BGR);

    // Clean up memory
    Lw.delete();
    logLw.delete();
    Ld.delete();
    out_img.delete();
    channels.delete();
    src.delete();

    return output;
}
```

Please note that you need to include the [OpenCV.js library](https://docs.opencv.org/master/d5/d10/tutorial_js_root.html) in your project to work with this code. To use this function, just pass the input image as an OpenCV.js Mat object:

```javascript
let input = new cv.Mat();
// Load input image into input Mat object
let output = reinhard_tonemapping(input);
```

