```javascript
function equalize_skin_color(src) {
    const adjust_saturation = (img, value) => {
        let hsvImg = new cv.Mat();
        cv.cvtColor(img, hsvImg, cv.COLOR_BGR2HSV);
        let channels = new cv.MatVector();
        cv.split(hsvImg, channels);
        let s = channels.get(1);
        let c = value / 100;
        s.convertTo(s, -1, c);
        channels.set(1, s);
        let output = new cv.Mat();
        cv.merge(channels, output);
        cv.cvtColor(output, output, cv.COLOR_HSV2BGR);
        return output;
    };

    const average_skin_color = (img, mask) => {
        let b = img.channels[0];
        let g = img.channels[1];
        let r = img.channels[2];

        let mask_pixels = [];
        let total_pixels = mask.cols * mask.rows;
        for (let i = 0; i < total_pixels; i++) {
            if (mask.data[i] !== 0) {
                mask_pixels.push(i);
            }
        }

        let r_acc = 0, g_acc = 0, b_acc = 0;
        for (let i = 0; i < mask_pixels.length; i++) {
            r_acc += r.data[mask_pixels[i]];
            g_acc += g.data[mask_pixels[i]];
            b_acc += b.data[mask_pixels[i]];
        }

        let r_avg = r_acc / mask_pixels.length;
        let g_avg = g_acc / mask_pixels.length;
        let b_avg = b_acc / mask_pixels.length;

        return [r_avg, g_avg, b_avg];
    };

    const adjust_to_average = (img, targetAvg) => {
        let avg = average_skin_color(img);

        let ratio_r = targetAvg[0] / avg[0];
        let ratio_g = targetAvg[1] / avg[1];
        let ratio_b = targetAvg[2] / avg[2];

        let r = img.channels[0];
        let g = img.channels[1];
        let b = img.channels[2];

        for (let idx = 0; idx < img.total(); idx++) {
            r.data[idx] = Math.min(255, r.data[idx] * ratio_r);
            g.data[idx] = Math.min(255, g.data[idx] * ratio_g);
            b.data[idx] = Math.min(255, b.data[idx] * ratio_b);
        }

        return img;
    };

    let input = src.clone();

    // 1. Increase saturation for better skin color detection
    let saturated_img = adjust_saturation(input, 30);

    // 2. Convert image to YCrCb color space
    let ycrcb = new cv.Mat();
    cv.cvtColor(saturated_img, ycrcb, cv.COLOR_BGR2YCrCb);

    // 3. Threshold the image using the Cr channel to create a skin mask
    let minCr = new cv.Scalar(132, 127, 77);
    let maxCr = new cv.Scalar(173, 127, 127);
    let skin_mask = new cv.Mat();
    cv.inRange(ycrcb, minCr, maxCr, skin_mask);

    // 4. Blur the skin mask
    let blurred_mask = new cv.Mat();
    let ksize = new cv.Size(3, 3);
    cv.medianBlur(skin_mask, blurred_mask, 7);

    // 5. Get the average skin color (using the mask)
    let avg_skin_color = average_skin_color(input, blurred_mask);

    // 6. Adjust input image colors to match the average skin color
    let equalized_img = adjust_to_average(input, avg_skin_color);

    return equalized_img;
}
```

通过这个函数，你可以调整图像的肤色，使其看起来更加统一。要使用函数，仅需将输入图像作为OpenCV.js Mat对象传递：
