        if (locale.toLocaleLowerCase() === 'en') {
            await this.switchENLocale();
        } else {
            await this.switchRULocale();
        }
        await this.fillLogin(login)
            .fillPassword(password)
            .clickLoginButton();
        return this;
    }
}

export default LoginPage;
