        cin >> name >> baseSalary >> numProducts;
    }

    float getSalary() {
        return baseSalary + numProducts * 5;
    }
};

class Officer : public Employee {
private:
    int numDays;
public:
    void input() {
        cin >> name >> numDays;
    }

    float getSalary() {
        return numDays * 100;
    }
};

class Manager : public Employee {
private:
    int totalProducts = 0;
    int totalDays = 0;

public:
    void input() {
        cin >> name;
    }

    void getInfo(vector<Employee*> employees) {
        for (const auto& employee : employees) {
            if (auto worker = dynamic_cast<Worker*>(employee)) {
                totalProducts += worker->getSalary();
            } else if (auto officer = dynamic_cast<Officer*>(employee)) {
                totalDays += officer->getSalary();
            }
        }
    }

    float getSalary() {
        return 100 + (totalProducts * 2) + (totalDays * 40);
    }
};

