    cin >> n;

    vector<Employee*> employees;
    Manager* boss = nullptr;

    for (int i = 0; i < n; ++i) {
        int type;
        cin >> type;
        Employee* employee;

        if (type == 1) {
            employee = new Worker();
        } else if (type == 2) {
            employee = new Officer();
        } else {
