using namespace std;

const float PI = 3.14;

class Bottle {
public:
    virtual float getArea() = 0;
    virtual float getGroundWater() = 0;
};

class Cylinder : public Bottle {
private:
    float height;
    float radius;

public:
    Cylinder(float height, float radius) : height(height), radius(radius) {}

    float getArea() {
        return 2 * PI * radius * height;
    }

    float getGroundWater() {
        return PI * radius * radius * height;
    }
};

class Rectangular : public Bottle {
private:
    float height;
    float width;
    float length;

public:
    Rectangular(float height, float length, float width) : height(height), length(length), width(width) {}

    float getArea() {
        return 2 * (length * width + length * height + width * height);
    }

    float getGroundWater() {
        return height * width * length;
    }
};

class Cube : public Bottle {
private:
    float edgeLength;

public:
    Cube(float edgeLength) : edgeLength(edgeLength) {}

    float getArea() {
        return 6 * edgeLength * edgeLength;
    }

    float getGroundWater() {
        return edgeLength * edgeLength * edgeLength;
    }
};

int main() {
    int n;
    cin >> n;

    vector<Bottle*> bottles;

    for (int i = 0; i < n; ++i) {
        int type;
        cin >> type;
        Bottle* bottle;

        if (type == 1) {
            float height, radius;
            cin >> height >> radius;
            bottle = new Cylinder(height, radius);
        } else if (type == 2) {
            float width, height, length;
            cin >> height >> length >> width;
            bottle = new Rectangular(height, length, width);
        } else {
            float edgeLength;
            cin >> edgeLength;
            bottle = new Cube(edgeLength);
        }

        bottles.push_back(bottle);
    }

    float totalArea = 0;
    float totalGroundWater = 0;

    for (const auto& bottle : bottles) {
        totalArea += bottle->getArea();
        totalGroundWater += bottle->getGroundWater();
    }

    cout << "Dien tich chai vo: " << totalArea << endl;
    cout << "Luong nuoc tren mat dat: " << totalGroundWater << endl;

    return 0;
}
