```cpp
// Define pins for ultrasonic sensor and LED
const int trigPin = 9;
const int echoPin = 10;
const int ledPin = 13;

// Set the motion detection distance threshold (in cm)
const int distanceThreshold = 20;

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  pinMode(ledPin, OUTPUT);

  // Begin serial communication for debugging
  Serial.begin(9600);
}

void loop() {
  // Send a pulse to the ultrasonic sensor
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read the echo time and convert it to distance
  long duration = pulseIn(echoPin, HIGH);
  float distance = duration * 0.0344 / 2;

  // Check if the distance falls below the threshold
  if (distance < distanceThreshold) {
    // Turn on the LED if motion is detected
    digitalWrite(ledPin, HIGH);
    Serial.println("Motion detected!");
  } else {
    // Turn off LED if no motion detected
    digitalWrite(ledPin, LOW);
  }

  // Print distance value for debugging
  Serial.print("Distance: ");
  Serial.println(distance);

  // Wait a short moment before taking another reading
  delay(100);
}
```

