```java
public class Node {
    int key;
    String value;
    Node leftChild;
    Node rightChild;

    public Node(int key, String value) {
        this.key = key;
        this.value = value;
    }
}

public class BinarySearchTree {
    Node root;

    public void put(int key, String value) {
        Node newNode = new Node(key, value);

        if(root == null) {
            root = newNode;
        } else {
            Node currentNode = root;

            while(true) {
                if(key < currentNode.key) {
                    if(currentNode.leftChild == null) {
                        currentNode.leftChild = newNode;
                        return;
                    }
                    currentNode = currentNode.leftChild;
                } else if(key > currentNode.key) {
                    if(currentNode.rightChild == null) {
                        currentNode.rightChild = newNode;
                        return;
                    }
                    currentNode = currentNode.rightChild;
                } else {
                    currentNode.value = value;
                    return;
                }
            }
        }
    }

    public String get(int key) {
        Node currentNode = root;

        while(currentNode != null) {
            if(key == currentNode.key) {
                return currentNode.value;
            } else if(key < currentNode.key) {
                currentNode = currentNode.leftChild;
            } else {
                currentNode = currentNode.rightChild;
            }
        }

        return null;
    }

    public boolean containsKey(int key) {
        Node currentNode = root;

        while(currentNode != null) {
            if(key == currentNode.key) {
                return true;
            } else if(key < currentNode.key) {
                currentNode = currentNode.leftChild;
            } else {
                currentNode = currentNode.rightChild;
            }
        }

        return false;
    }

    public void remove(int key) {
        root = remove(root, key);
    }

    private Node remove(Node currentNode, int key) {
        if(currentNode == null) {
            return null;
        }

        if(key == currentNode.key) {
            if(currentNode.leftChild == null && currentNode.rightChild == null) {
                return null;
            }

            if(currentNode.leftChild == null) {
                return currentNode.rightChild;
            }

            if(currentNode.rightChild == null) {
                return currentNode.leftChild;
            }

            Node tempNode = getMinNode(currentNode.rightChild);
            currentNode.key = tempNode.key;
            currentNode.value = tempNode.value;
            currentNode.rightChild = remove(currentNode.rightChild, tempNode.key);
            return currentNode;
        } else if(key < currentNode.key) {
            currentNode.leftChild = remove(currentNode.leftChild, key);
            return currentNode;
        } else {
            currentNode.rightChild = remove(currentNode.rightChild, key);
            return currentNode;
        }
    }

    private Node getMinNode(Node currentNode) {
        while(currentNode.leftChild != null) {
            currentNode = currentNode.leftChild;
        }
        return currentNode;
    }
}

```

