```java
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

public class Graph {
    private Map<Integer, List<Integer>> adjacencyList = new HashMap<>();

    public void addVertex(int vertex) {
        adjacencyList.putIfAbsent(vertex, new LinkedList<>());
    }

    public void addEdge(int vertex1, int vertex2) {
        adjacencyList.get(vertex1).add(vertex2);
        adjacencyList.get(vertex2).add(vertex1);
    }

    public void removeVertex(int vertex) {
        adjacencyList.values().stream().forEach(e -> e.remove(Integer.valueOf(vertex)));
        adjacencyList.remove(vertex);
    }

    public void removeEdge(int vertex1, int vertex2) {
        List<Integer> edgesOfVertex1 = adjacencyList.get(vertex1);
        List<Integer> edgesOfVertex2 = adjacencyList.get(vertex2);
        if(edgesOfVertex1 != null) {
            edgesOfVertex1.remove(Integer.valueOf(vertex2));
        }
        if(edgesOfVertex2 != null) {
            edgesOfVertex2.remove(Integer.valueOf(vertex1));
        }
    }

    public List<Integer> getAdjacentVertices(int vertex) {
        return adjacencyList.get(vertex);
    }

    public boolean hasVertex(int vertex) {
        return adjacencyList.containsKey(vertex);
    }

    public boolean hasEdge(int vertex1, int vertex2) {
        List<Integer> edgesOfVertex1 = adjacencyList.get(vertex1);
        List<Integer> edgesOfVertex2 = adjacencyList.get(vertex2);
        if(edgesOfVertex1 == null || edgesOfVertex2 == null) {
            return false;
        }
        if(edgesOfVertex1.contains(vertex2) && edgesOfVertex2.contains(vertex1)) {
            return true;
        }
        return false;
    }

    public int size() {
        return adjacencyList.size();
    }
}
