                $unique_ids[] = $optionId;
            }

            $option = $this->dom->createElement('option');

            $optionId = $this->dom->createElement('id', $optionId);
            $option->appendChild($optionId);
            $addedNames = $this->createAndAddBilingualSettings($option, $optionData, 'name');

            if ($addedNames < 1) {
                $this->addCardElementError($elementData, "Option " . ($optionIndex + 1) . " hat keinen Namen");
            }
            $options->appendChild($option);
        }

        $element->appendChild($options);
    }

    /**
     * 
     * @return bool true, wenn das Element hinzugefügt wurde
     */
    private function createAndAddComponentEntity(DOMElement $element, array $elementData): bool {
        if (!in_array($elementData['type'], CARD_COMPONENTS_ENTITY)) {
            return false;
        }

        $entityValue = trim($elementData['entity']);

        if ($entityValue === '') {
            $this->addCardElementError($elementData, "geben Sie bitte eine Entität ein");
        }

        if (!preg_match('/^[a-z]+(_[a-z]+)*$/', $entityValue)) {
            $this->addCardElementError($elementData, "Die Entität ist nicht in Snake Case");
            return false;
        }

        $componentEntity = $this->dom->createElement('entity', $entityValue);
        $element->appendChild($componentEntity);

        return true;
    }

    private function createAndAddComponentSnippet(DOMElement $element, array $elementData): void {
        if ($elementData['type'] !== 'sw-snippet-field') {
            return;
        }

        $snippetValue = trim($elementData['snippet']);

        if ($snippetValue === '') {
            $this->addCardElementError($elementData, "geben Sie bitte ein Snippet ein");
        }

        $componentSnippet = $this->dom->createElement('snippet', $snippetValue);
        $element->appendChild($componentSnippet);

    }
}

