        if (SUCCEEDED(hr))
        {
            // Query IShellLink for the SHELL_LINK_DATA_LIST structure.
            IShellLinkDataList* pLinkDataList = NULL;
            hr = pShellLink->QueryInterface(IID_IShellLinkDataList, (void**)&pLinkDataList);
            if (SUCCEEDED(hr))
            {
                // Get the SHELL_LINK_DATA structure.
                const DWORD dwSig = pLinkDataList->GetFlags();
                if (dwSig & SLDF_HAS_ID_LIST)
                {
                    // Resolve the link when it has an ID list.
                    WCHAR wszResolvedPath[MAX_PATH] = {0};
                    hr = pShellLink->Resolve(NULL, SLR_NO_UI);
                    if (SUCCEEDED(hr))
                    {
                        hr = pShellLink->GetPath(wszResolvedPath, MAX_PATH, NULL, SLGP_RAWPATH);
                    }
                    if (SUCCEEDED(hr))
                    {
                        // Get the attributes of the resolved path.
                        DWORD dwAttr = GetFileAttributes(wszResolvedPath);
                        if (dwAttr == INVALID_FILE_ATTRIBUTES)
                        {
                            // Error occurred.
                        }
                        else
                        {
                            if (dwAttr & FILE_ATTRIBUTE_DIRECTORY)
                            {
                                // The link points to a directory.
                            }
                            else
                            {
                                // The link points to a file.
                            }
                        }
                    }
                }
                else
                {
                    // Get the SHELL_LINK_DATA structure.
                    SHELL_LINK_DATA sld = {0};
                    hr = pLinkDataList->CopyDataBlock(SHELL_LINK_DATA_SIG, (LPVOID)&sld);

                    if (SUCCEEDED(hr))
                    {
                        // Get the attributes of the target path.
                        DWORD dwAttr = GetFileAttributes(sld.szTarget);
                        if (dwAttr == INVALID_FILE_ATTRIBUTES)
                        {
