        boolean carryOn = true;

        while (carryOn) {
            runOneRound();
            if (!gc.getPlayerQuitStatus()) {
                char r = this.view.getPlayerNextGame();
                if (r == 'n') {
                    carryOn = false;
                }
            } else {
                carryOn = false;
            }
        }
        this.view.displayPlayerNameAndLeftOverChips(this.player);
        this.view.displayExitGame();
