function processColumns() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getActiveSheet();
  var listSheet = ss.getSheetByName("List");
  var listData = listSheet.getRange("A:C").getValues();

  var columns = ['C', 'H', 'M', 'R'];
  var lastRow = sheet.getLastRow();

  columns.forEach(function(column) {
    for (var i = 1; i <= lastRow; i++) {
      var cell = sheet.getRange(column + i);
      var currentValue = cell.getValue();
      var nextCell = sheet.getRange(column + (i+1));
      var nextCellValue = nextCell.getValue();

      if (currentValue == '' || nextCellValue != '') {
        continue;
      }

      var matchFound = false;

      listData.forEach(function(row) {
        if (row[0] == currentValue) {
          matchFound = true;
          cell.setValue(row[1]);
          cell.setRichText(cell.getRichTextValue().withLink(row[2]));
          nextCell.setValue(row[2]);
          return;
        }
      });

      if (!matchFound) {
        continue;
      }
    }
  });
}
