2. Add startAt and limit clauses to the query to paginate the result.
3. Return the total count and pagination data.
4. Update the function where it's called, passing the `pageSize` and `pageIndex`.

Here's the updated function with pagination support:

```javascript
export const getTwoQueryDocByCollectionAndDate = async (
  collectionName,
  conditionField,
  operator,
  param,
  conditionField1,
  operator1,
  param1,
  fechaInicio,
  fechaFinal,
  pageSize, // Add pageSize parameter
  pageIndex // Add pageIndex parameter
) => {
  const collectionRef = collection(FirebaseDB, collectionName);

  const dateStart = fechaInicio.setHours(0, 0, 0, 0);
  const dateEnd = fechaFinal.setHours(0, 0, 0, 0);

  // Get the total count of the data
  const countQueryData = query(
    collectionRef,
    where(conditionField, operator, param),
    where(conditionField1, operator1, param1),
    where("created_at", ">=", new Date(dateStart)),
    where("created_at", "<=", new Date(dateEnd))
  );

  const countQuerySnapshot = await getDocs(countQueryData);
  const totalCount = countQuerySnapshot.size;

  // Get the paginated data
  const data = [];
  const queryData = query(
    collectionRef,
    where(conditionField, operator, param),
    where(conditionField1, operator1, param1),
    where("created_at", ">=", new Date(dateStart)),
    where("created_at", "<=", new Date(dateEnd)),
    orderBy("created_at", "desc"),
    startAt(pageIndex * pageSize),
    limit(pageSize)
  );

