    {
        this.owner_id = owner_id;
    }
}
```

3. Create an `InventoriesManager` Singleton script that maintains a dictionary of NPC inventories.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class InventoriesManager : MonoBehaviour
{
    public static InventoriesManager Instance;

    public Dictionary<string, Inventory> Inventories;

    private void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            Inventories = new Dictionary<string, Inventory>();
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }

    public void AssignInventory(NPC npc)
    {
        if (!Inventories.ContainsKey(npc.npc_id))
        {
            Inventories[npc.npc_id] = new Inventory(npc.npc_id);
        }
    }

    public Inventory GetInventory(string npc_id)
    {
{
        return Inventories[npc_id];
    }
}
```

4. In your main game logic or NPC logic, call `InventoryManager.Instance.AssignInventory(this);` to assign an inventory to each NPC.

