It seems like you want to have a simple program that rolls a dice when the user types "Roll". You have two methods (`Rolling()` and `RollDice()`) that basically do the same thing. I will simplify the code by using just one method.

Here's the corrected code:

```csharp
using System;

namespace Prog
{
    class GuessGame
    {
        static void Main(string[] args)
        {
            RollDice();
        }

        static void RollDice()
        {
            while (true)
            {
                Console.WriteLine("Type \"Roll\" to roll the dice or \"Exit\" to exit the game.");
                string userInput = Console.ReadLine();

                if (userInput.Equals("Roll", StringComparison.OrdinalIgnoreCase))
                {
                    Random r = new Random();
                    int res = r.Next(1, 46); // Changed the range to include 1 and exclude 46
                    Console.WriteLine("You rolled: " + res);
                }
                else if (userInput.Equals("Exit", StringComparison.OrdinalIgnoreCase))
                {
                    break;
                }
                else
                {
                    Console.WriteLine("Invalid input. Please try again.");
                }
            }
        }
    }
}
```

