Here's a simple annuity calculator with the given user inputs:

```js
function calculateAnnuity(params) {
  const {
    startingPrincipal,
    annualAddition,
    monthlyAddition,
    addTo,
    annualInterestRate,
    years,
  } = params;

  let months = years * 12;
  let endBalance = startingPrincipal;
  let totalPrincipal = startingPrincipal;
  let totalInterest = 0;

  const monthlyInterestRate = Math.pow(1 + annualInterestRate / 100, 1 / 12) - 1;

  for (let i = 1; i <= months; i++) {
    if (addTo === "Beginning") {
      endBalance *= 1 + monthlyInterestRate;
    }

    const principal = annualAddition / 12 + monthlyAddition;
    endBalance += principal;
    totalPrincipal += principal;

    if (addTo === "End") {
      endBalance *= 1 + monthlyInterestRate;
    }
  }

  totalInterest = endBalance - totalPrincipal;

  return {
    endBalance: endBalance.toFixed(2),
    totalPrincipal: totalPrincipal.toFixed(2),
    totalInterest: totalInterest.toFixed(2),
  };
}

// Example usage:
const params = {
  startingPrincipal: 10000,
  annualAddition: 2000,
  monthlyAddition: 0,
  addTo: "End",
  annualInterestRate: 5,
  years: 10,
};

const result = calculateAnnuity(params);
console.log(result);
```

