import React, { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { updateFilter } from "../../../store/pageFilterSlice";
import styles from "./FilterCheckbox.module.scss";

const FilterCheckbox = ({ data, apiKey }) => {
  // Destructure data object
  const { name, value, items } = data;

  // Access filtersByApiKey from Redux store
  const filtersByApiKey = useSelector(
    (state) => state.pageFilter.filtersByApiKey
  );

  // Use useState to manage checked state
  const [isChecked, setIsChecked] = useState(() => {
    const filters = filtersByApiKey[apiKey] || [];
    return filters.includes(value);
  });

  // Access dispatch function from Redux
  const dispatch = useDispatch();

  // Event handler for checkbox change
  const handleChange = () => {
    setIsChecked(!isChecked);

    if (!isChecked) {
      // If the checkbox is being checked
      if (items && items.length > 0) {
        for (const item of items) {
          dispatch(updateFilter({ value: item.value, apiKey }));
        }
      } else {
        dispatch(updateFilter({ value, apiKey }));
      }
    } else {
      // If the checkbox is being unchecked

      if (items && items.length > 0) {
        for (const item of items) {
          dispatch(updateFilter({ value: item.value, apiKey, remove: true }));
        }
      } else {
        dispatch(updateFilter({ value, apiKey }));
      }
    }
  };

  return (
    <div className={styles.checkbox}>
      <label className={styles.label}>
        <input
          className={styles.input}
          type="checkbox"
          id={value}
          name={value}
          checked={isChecked}
          onChange={handleChange}
        />
        <span
          className={`${styles.checkmark} ${isChecked ? styles.checked : ""}`}
        ></span>
        <span className={styles.title}>{name}</span>
      </label>

      {items && items.length > 0 && isChecked && (
        <div className={styles.subFilters}>
          {items.map((item) => (
            <FilterCheckbox key={item.value} data={item} apiKey={apiKey} />
          ))}
        </div>
      )}
    </div>
  );
};

export default FilterCheckbox;

