2. Load the localized strings in Swift by using a custom function:

```swift
import Foundation

enum Frequency: String {
    case weekly = "weekly"
    case biweekly = "biweekly"
}

func localizedString(_ key: String, comment: String = "") -> String {
    return NSLocalizedString(key, comment: comment)
}

func localizedFrequency(_ frequency: Frequency) -> String {
    return localizedString(frequency.rawValue)
}
