2. Create the `updateCoinsData` callback function:
```javascript
const updateCoinsData = useCallback((symbol, coinData) => {
  setCoinsData((prevCoinsData) => {
    const newCoinsData = [...prevCoinsData];
    const existingIndex = newCoinsData.findIndex((data) => data.symbol === symbol);

    if (existingIndex !== -1) {
      newCoinsData[existingIndex] = {symbol, ...coinData};
    } else {
      newCoinsData.push({symbol, ...coinData});
    }

    return newCoinsData;
  });
}, []);
```

3. Pass the `updateCoinsData` callback to the `ScreenerSymbol` component.
