const ScreenerSymbol = ({symbol, activeSymbol, setActiveSymbol, connectedSymbols, setConnectedSymbols, symbolsFilters, handleCoinData}: ScreenerSymbolProps) => {

  const coin = useSelector((state: AppState) => state.binancePrice.futures24h[symbol.toUpperCase()]);
