Creating a full authentication and authorization model can be quite complex and would require a lot of code. However, I can provide you with a basic outline using JavaScript and some popular libraries like Express, Passport, and JWT. Here is an outline of the model with some example code snippets:

1. **Backend setup using Express and MongoDB:** Set up a basic server using Express and connect it to a MongoDB database.

```javascript
const express = require('express');
const mongoose = require('mongoose');
const app = express();

mongoose.connect('mongodb://127.0.0.1:27017/authentication-db', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

const db = mongoose.connection;
db.on('error', console.error.bind(console, 'connection error:'));
db.once('open', function () {
  console.log('Connected to the database!');
});

app.listen(3000, () => {
  console.log('Server is running on http://localhost:3000');
});
```

2. **Create a User schema for MongoDB:**

```javascript
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');

const UserSchema = new mongoose.Schema({
    username: { type: String, required: true, unique: true },
    password: { type: String, required: true }
});

UserSchema.pre('save', async function (next) {
    const user = this;

    if (!user.isModified('password')) return next();

    const salt = await bcrypt.genSalt(10);
    const hash = await bcrypt.hash(user.password, salt);

    user.password = hash;
    next();
});

UserSchema.methods.comparePassword = function (candidatePassword, callback) {
    bcrypt.compare(candidatePassword, this.password, (err, isMatch) => {
        if (err) return callback(err);
        callback(null, isMatch);
    });
}

module.exports = mongoose.model('User', UserSchema);
```

3. **Implement Passport for authentication:** Use Passport with the passport-local strategy to authenticate users.

```javascript
const passport = require('passport');
const LocalStrategy = require('passport-local').Strategy;
const User = require('./models/User');

passport.use(new LocalStrategy((username, password, done) => {
  User.findOne({ username }, (err, user) => {
    if (err) return done(err);
    if (!user) return done(null, false, { message: 'Incorrect username.' });

    user.comparePassword(password, (err, isMatch) => {
      if (err) return done(err);
      if (isMatch) return done(null, user);
      return done(null, false, { message: 'Incorrect password.' });
    });
  });
}));

passport.serializeUser((user, done) => {
  done(null, user.id);
});

passport.deserializeUser((id, done) => {
  User.findById(id, (err, user) => {
    done(err, user);
  });
});

module.exports = passport;
```

4. **Create JWT for authorization:** Use JWT to provide a token-based authorization after successful authentication.

```javascript
const jwt = require('jsonwebtoken');

function generateToken(user) {
  const payload = {
    id: user._id,
    username: user.username
  };
  const options = {
    expiresIn: '2h'
  };
  const secret = process.env.JWT_SECRET;

  return jwt.sign(payload, secret, options);
}
```

5. **Implement routes for registration, login, and protected resources:** Use Express routes to provide end-points for user registration, login, and accessing protected resources.

```javascript
const express = require('express');
const passport = require('./passport-config');
const jwt = require('jsonwebtoken');
const User = require('./models/User');
const authenticate = require('./middlewares/authenticate');
const generateToken = require('./generateToken');
const router = express.Router();

router.post('/register', (req, res) => {
  const { username, password } = req.body;
  const newUser = new User({ username, password });

  newUser.save((err, user) => {
    if (err) return res.status(500).json({ message: 'Error registering user' });

    res.status(200).json({ message: 'User registered successfully' });
  });
});

router.post('/login', passport.authenticate('local'), (req, res) => {
  const token = generateToken(req.user);
  res.json({ message: 'Login successful', token });
});

router.get('/protected', authenticate, (req, res) => {
  res.json({ message: 'Welcome to the protected resource!' });
});

module.exports = router;
```

6. **Implement "authenticate" middleware to protect resources:** Use a custom middleware that verifies the JWT token before allowing access to protected routes.

```javascript
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  try {
    const token = req.headers.authorization.split(' ')[1];
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    req.user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ message: 'Unauthorized access' });
  }
}

module.exports = authenticate;
```

Please note that this is a very basic example and there are many improvements that can be made (using environment variables, using HTTPS, more secure storage of JWT tokens, handling errors, etc.). However, this should help you set up a simple authentication and authorization system in your web application. Don't forget to install the required packages using `npm install express mongoose bcrypt passport passport-local jsonwebtoken dotenv`. And also, create a `.env` file with your JWT secret: `JWT_SECRET=mysecret`.

