```javascript
function averageHsl(hsl1, hsl2) {
  const h = (hsl1[0] + hsl2[0]) / 2;
  const s = (hsl1[1] + hsl2[1]) / 2;
  const l = (hsl1[2] + hsl2[2]) / 2;
  return [h, s, l];
}

const averageSunTempHSL = averageHsl(centerTempHSL, photosphereTempHSL);

