void Task::start(const int ssrc) {
    std::unique_lock<std::mutex> lock(m_mutex);
    auto thread_iter = m_threads.find(ssrc);
    if (thread_iter == m_threads.end()) {
        m_threads[ssrc] = std::thread(&Task::worker, this, ssrc);
        m_threads[ssrc].detach();
        lock.unlock();
        add(ssrc);
    }
}

