        std::unique_lock<std::mutex> lock(m_stream_mutex);
        // ... remove from stream threads
    }
    {
        std::unique_lock<std::mutex> lock(m_ssrc_mutex);
        // ... remove from ssrc threads
    }
}

void Task::stop(const int ssrc) {
    std::unique_lock<std::mutex> lock(m_mutex);
    auto thread_iter = m_threads.find(ssrc);
    if (thread_iter != m_threads.end()) {
