```javascript
import { startOfDay, endOfDay, addDays } from "date-fns";
import { nextMonday } from "date-fns/esm";
import { addBusinessDays } from "date-fns/esm";

export const getFutureDates = () => {
  const now = new Date();
  const today = startOfDay(now);

  const getNextBusinessMonday = (date, weeksAhead = 1) =>
    startOfDay(addDays(nextMonday(date), 7 * weeksAhead));

  const getNextBusinessFriday = (date, weeksAhead = 1) =>
    endOfDay(addBusinessDays(date, 5 * weeksAhead));

  const twoMondaysFromNow = getNextBusinessMonday(now, 1);
  const fourMondaysFromNow = getNextBusinessMonday(now, 3);

  const twoFridaysFromTwoMondays = getNextBusinessFriday(twoMondaysFromNow, 1);
  const twoFridaysFromFourMondays = getNextBusinessFriday(
    fourMondaysFromNow,
    1
  );

  const twoFridaysFromToday = getNextBusinessFriday(today, 1);

  return {
    today,
    twoMondaysFromNow,
    fourMondaysFromNow,
    twoFridaysFromTwoMondays,
    twoFridaysFromFourMondays,
    twoFridaysFromToday,
  };
};
```

I created `getNextBusinessMonday` and `getNextBusinessFriday` helper functions to make the code more readable and reusable. These functions accept a `weeksAhead` parameter (with a default value of 1) which allows you to easily change the weeks in advance you want to calculate. If you need even more specific date calculations, feel free to modify these helper functions.

