Here's a Java code to store the amount of halftone differences between MIDI-file notes in a Hashtable, where the key is the note number and the value is the note difference number, for only the first track:

```java
import javax.sound.midi.*;

public class MidiNoteDifference {
    public static void main(String[] args) {
        try {
            // Load the MIDI sequence from a file
            Sequence sequence = MidiSystem.getSequence(new java.io.File("input.mid"));

            // Get the first track from the sequence
            Track track = sequence.getTracks()[0];

            // Create a Hashtable to store note differences
            Hashtable<Integer, Integer> noteDiffTable = new Hashtable<Integer, Integer>();

            // Iterate over all the MIDI events in the track
            for (int i = 0; i < track.size(); i++) {
                MidiEvent event = track.get(i);
                MidiMessage message = event.getMessage();

                // Check if the event is a note on message
                if (message instanceof ShortMessage && ((ShortMessage) message).getCommand() == ShortMessage.NOTE_ON) {
                    int noteNumber = ((ShortMessage) message).getData1();

                    // Check if the note is already in the Hashtable
                    if (noteDiffTable.containsKey(noteNumber)) {
                        int prevNoteNumber = noteDiffTable.get(noteNumber);
                        int noteDiff = noteNumber - prevNoteNumber;

                        // Store the note difference in the Hashtable
                        noteDiffTable.put(noteNumber, noteDiff);
                    } else {
                        noteDiffTable.put(noteNumber, noteNumber);
                    }
                }
            }

            // Print the Hashtable
            System.out.println(noteDiffTable);

        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }
}
```

