```kotlin
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.text.KeyboardActions
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material.OutlinedTextField
import androidx.compose.material.Text
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.input.ImeAction
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp

@Composable
fun CurrencyTextField(
    modifier: Modifier = Modifier,
    onCurrencyChange: (String) -> Unit,
    onFocusChanged: (Boolean) -> Unit
) {
    var currencyText by remember { mutableStateOf("") }
    var isFocused by remember { mutableStateOf(false) }
    var isTextBlack by remember { mutableStateOf(false) }

    val textFieldValue = if (isFocused || isTextBlack) {
        currencyText
    } else {
        "0"
    }

    val textColor = if (isTextBlack || isFocused) {
        Color.Black
    } else {
        Color.Gray
    }

    OutlinedTextField(
        value = textFieldValue,
        onValueChange = { newValue ->
            currencyText = newValue
            onCurrencyChange(newValue)
            isTextBlack = newValue.isNotEmpty()
        },
        singleLine = true,
        keyboardOptions = KeyboardOptions(
            keyboardType = KeyboardType.Number,
            imeAction = ImeAction.Done
        ),
        keyboardActions = KeyboardActions(onDone = {
            isFocused = false
            onFocusChanged(isFocused)
        }),
        modifier = modifier.padding(8.dp),
        textAlign = TextAlign.Center,
        cursorColor = textColor,
        textStyle = androidx.compose.ui.text.TextStyle(
