    Stack() { top = 0; }
    int empty() {
        if (top == 0) {
            cout << "stack is empty." << endl;
            return 1;
        }
        return 0;
    }
    int full() {
        if (top == MAX_SIZE) {
            cout << "stack is full." << endl;
            return 1;
        }
        return 0;
    }
    ~Stack() {}
    void push(T dd);
    T pop();
};

template<class T>
void Stack<T>::push(T dd) {
    if(top==MAX_SIZE ) {
        cout<<"stack is full."<<endl;
        return;
    }
    stck[top]=dd;
    top++;
}

template<class T>
T Stack<T>::pop() {
    top--;
    if(top==-1) {
        cout<<"stack is empty."<<endl;
        return -1;
    }
    return stck[top];
}

