It is possible to implement Slowly Changing Dimension of Type 2 (SCD Type 2) in Spark without using User Defined Functions (UDF) and with parametrizable fields and hashing. Below is an example code to achieve this using a basic dataset as an example.

```java
import org.apache.spark.sql.Dataset;
import org.apache.spark.sql.Row;
import org.apache.spark.sql.SparkSession;
import org.apache.spark.sql.functions;
import static org.apache.spark.sql.functions.*;

public class SCDType2Example {

    public static void main(String[] args) {

        SparkSession spark = SparkSession
                .builder()
                .appName("SCD Type 2 Example")
                .master("local")
                .getOrCreate();

        Dataset<Row> oldData = spark.read().parquet("path/to/oldData");
        Dataset<Row> newData = spark.read().parquet("path/to/newData");

        String primaryKey = "id";
        String[] nonKeyColumns = {"name", "age", "city"}; // Parametrizable columns
        String hashColumn = "hash";

        // Calculate hash value for both old and new data
        oldData = createHash(oldData, nonKeyColumns, hashColumn);
        newData = createHash(newData, nonKeyColumns, hashColumn);

        // Identify unchanged rows
        Dataset<Row> unchangedData = oldData.join(newData, oldData.col(primaryKey)
                .equalTo(newData.col(primaryKey)))
                .where(oldData.col(hashColumn).equalTo(newData.col(hashColumn)))
                .select(oldData.columns());

        // Identify changed rows from old data to close
        Dataset<Row> changedOldData = oldData.join(newData, oldData.col(primaryKey)
                .equalTo(newData.col(primaryKey)))
                .where(oldData.col(hashColumn).notEqual(newData.col(hashColumn)))
                .select(oldData.columns())
                .withColumn("end_date", current_date())
                .withColumn("current_flag", lit(false));

        // Identify changed rows from new data to insert
        Dataset<Row> changedNewData = newData.join(oldData, newData.col(primaryKey)
                .equalTo(oldData.col(primaryKey)))
                .where(newData.col(hashColumn).notEqual(oldData.col(hashColumn)))
                .select(newData.columns())
                .withColumn("start_date", current_date())
                .withColumn("end_date", lit(null).cast("date"))
                .withColumn("current_flag", lit(true));

        // Identify new rows to insert
        Dataset<Row> newRows = newData.join(oldData, newData.col(primaryKey)
                .equalTo(oldData.col(primaryKey)), "leftanti")
                .withColumn("start_date", current_date())
                .withColumn("end_date", lit(null).cast("date"))
                .withColumn("current_flag", lit(true));

        // Combine unchanged, changed old, changed new, and new rows
        Dataset<Row> result = unchangedData
                .union(changedOldData)
                .union(changedNewData)
                .union(newRows);

        result.write().parquet("path/to/output");
    }

    private static Dataset<Row> createHash(Dataset<Row> data, String[] nonKeyColumns, String hashColumn) {
        Dataset<Row> result = data;

        StringBuilder concatString = new StringBuilder();
        for (String column : nonKeyColumns) {
            concatString.append("cast(").append(column).append(" as string),");
        }

        String concatColumns = concatString.toString();
        if (concatColumns.endsWith(",")) {
            concatColumns = concatColumns.substring(0, concatColumns.length() - 1);
        }

        return result.withColumn(hashColumn, sha2(functions.concat_ws("",
                functions.expr(concatColumns)), 256));
    }
}
```

This code reads old data and new data from parquet files, calculates the hash, processes the SCD Type 2 logic, and writes the output to another parquet file. The fields are parametrizable using the 'primaryKey' and 'nonKeyColumns' variables.

