```java
import org.apache.spark.sql.Dataset;
import org.apache.spark.sql.Row;
import org.apache.spark.sql.SparkSession;
import org.apache.spark.sql.functions;
import org.apache.spark.sql.types.DataTypes;
import org.apache.spark.sql.types.StructType;
import static org.apache.spark.sql.functions.*;

import java.util.Arrays;
import java.util.List;

public class SCDType2 {
    public static void main(String[] args) {
        SparkSession spark = SparkSession
                .builder()
                .appName("Java SCD Type 2")
                .config("spark.some.config.option", "some-value")
                .getOrCreate();

        // Read the new data
        Dataset<Row> newData = spark.read().format("csv").option("header", "true").load("new-data.csv");

        // Read the existing data
        Dataset<Row> existingData = spark.read().format("csv").option("header", "true").load("existing-data.csv");

        // Define primary keys and value fields
        List<String> primaryKeys = Arrays.asList("primaryKey1", "primaryKey2", "primaryKey3", "primaryKey4", "primaryKey5");
        List<String> valueFields = Arrays.asList("valueField1", "valueField2", "valueField3", "valueField4", "valueField5",
                                                 "valueField6", "valueField7", "valueField8", "valueField9", "valueField10");

        // Check schema compatibility
        StructType newSchema = newData.schema();
        StructType existingSchema = existingData.schema();

        if (!newSchema.equals(existingSchema)) {
            throw new RuntimeException("New data and existing data have different schemas.");
        }

        // Generate a hash for primary and value fields
        newData = newData.withColumn("primary_key_hash", sha2(concat_ws("", functions
                .array(removeNulls(primaryKeys).toArray(new String[0]))), 256));
        newData = newData.withColumn("value_hash", sha2(concat_ws("", functions
                .array(removeNulls(valueFields).toArray(new String[0]))), 256));

        existingData = existingData.withColumn("primary_key_hash", sha2(concat_ws("", functions
                .array(removeNulls(primaryKeys).toArray(new String[0]))), 256));
        existingData = existingData.withColumn("_value_hash", sha2(concat_ws("", functions
                .array(removeNulls(valueFields).toArray(new String[0]))), 256));

        // Merge the new and existing data
        Dataset<Row> mergeData = newData.union(existingData);

        // Close expired records
        mergeData.createOrReplaceTempView("merge_data");
        Dataset<Row> closedRecords = spark.sql(
                "SELECT *, " +
                        "CASE " +
                        "  WHEN _value_hash != value_hash THEN 1 " +
                        "  ELSE 0 " +
                        "END AS row_closed" +
                        "FROM merge_data");

        // Apply SCD Type 2
        Dataset<Row> result = closedRecords
                .withColumn("_row_number", row_number()
                        .over(Window.partitionBy("primary_key_hash")
                                .orderBy(desc("row_closed"), desc("timestamp"))))
                .filter(col("_row_number").equalTo(1))
                .drop("value_hash", "primary_key_hash", "_value_hash", "_row_number", "row_closed");

        result.write().mode("overwrite").parquet("output-data");
    }

    private static Dataset<Row> removeNulls(List<String> fields) {
        return functions.array(fields.stream().map(field -> functions.col(field).cast(DataTypes.StringType))
                .toArray(Column[]::new));
    }
}
``` 

This code will start by reading new and existing data from CSV files, then define primary keys and value fields. It checks the schema compatibility and generates a hash for primary and value fields. The new and existing data are merged, and SCD Type 2 is applied after that. Finally, the result is written to a Parquet file.

```java
import org.apache.spark.sql.*;
import static org.apache.spark.sql.functions.*;
import org.apache.spark.sql.types.*;
import org.apache.spark.sql.types.Metadata;
import java.util.*;

public class SCDType2 {

    public static void main(String[] args) {
        SparkSession spark = SparkSession
            .builder()
            .appName("SCD Type 2 Example")
            .getOrCreate();

        Dataset<Row> sourceDF = createSourceDF(spark);
        Dataset<Row> targetDF = createTargetDF(spark);
        Dataset<Row> scdDF = createSCDDF(sourceDF, targetDF);

        scdDF.show();

        spark.stop();
    }

    public static Dataset<Row> createSourceDF(SparkSession spark) {
        StructType schema = new StructType()
            .add("id", "int", false, Metadata.empty())
            .add("name", "string", false, Metadata.empty())
            .add("location", "string", false, Metadata.empty())
            .add("version", "int", false, Metadata.empty())
            .add("hash", "string", false, Metadata.empty());

        List<Row> sourceData = Arrays.asList(
            RowFactory.create(1, "John Doe", "New York", 1, "ABC"),
            RowFactory.create(2, "Jane Doe", "Los Angeles", 1, "DEF"),
            RowFactory.create(3, "Jim Smith", "San Francisco", 1, "GHI")
        );

        return spark.createDataFrame(sourceData, schema);
    }

    public static Dataset<Row> createTargetDF(SparkSession spark) {
        StructType schema = new StructType()
            .add("id", "int", false, Metadata.empty())
            .add("name", "string", false, Metadata.empty())
            .add("location", "string", false, Metadata.empty())
            .add("version", "int", false, Metadata.empty())
            .add("hash", "string", false, Metadata.empty());

        List<Row> targetData = Arrays.asList(
            RowFactory.create(1, "John Doe", "New York", 1, "ABC"),
            RowFactory.create(2, "Jane Doe", "Los Angeles", 1, "XYZ"),
            RowFactory.create(4, "Emma Brown", "Seattle", 1, "PQR")
        );

        return spark.createDataFrame(targetData, schema);
    }

    public static Dataset<Row> createSCDDF(Dataset<Row> sourceDF, Dataset<Row> targetDF) {
        // Join source and target dataframes on key column(s)
        final Dataset<Row> joinDF = sourceDF
            .join(targetDF, sourceDF.col("id").equalTo(targetDF.col("id")), "fullouter")
            .withColumn("record_type", expr("case when target.id is null then 'new' else 'existing' end"))
            .withColumn("is_changed", expr("case when source.hash <> target.hash then true else false end"));

        // Filter data based on the join result
        final Dataset<Row> newRecordsDF = joinDF.filter(col("record_type").equalTo("new")).select(sourceDF.columns());
        final Dataset<Row> unchangedRecordsDF = joinDF.filter(col("record_type").equalTo("existing")).filter(col("is_changed").equalTo(false)).select(targetDF.columns());
        final Dataset<Row> changedRecordsDF = joinDF.filter(col("record_type").equalTo("existing")).filter(col("is_changed").equalTo(true)).select(targetDF.columns());

        // Increment version and mark old records as inactive
        final Dataset<Row> updatedChangedRecordsDF = changedRecordsDF.withColumn("version", col("version").plus(1)).withColumn("is_active", lit(1));
        final Dataset<Row> inactiveChangedRecordsDF = changedRecordsDF.withColumn("is_active", lit(0));

        // Union all SCD Type 2 records
        final Dataset<Row> scdDF = unchangedRecordsDF
            .union(newRecordsDF)
            .union(inactiveChangedRecordsDF)
            .union(updatedChangedRecordsDF);

        return scdDF;
    }
}
