        newData.cache();

        // Identify unchanged rows
        Dataset<Row> unchangedData = oldData.join(newData, oldData.col(primaryKey)
                .equalTo(newData.col(primaryKey)))
                .where(oldData.col(hashColumn).equalTo(newData.col(hashColumn)))
                .select(oldData.columns());

        // Identify changed rows from old data to close
        Dataset<Row> changedOldData = oldData.join(newData, oldData.col(primaryKey)
                .equalTo(newData.col(primaryKey)))
                .where(oldData.col(hashColumn).notEqual(newData.col(hashColumn)))
                .select(oldData.columns())
                .withColumn("end_date", current_date())
                .withColumn("current_flag", lit(false));

        // Identify changed rows from new data to insert
        Dataset<Row> changedNewData = newData.join(oldData, newData.col(primaryKey)
                .equalTo(oldData.col(primaryKey)))
                .where(newData.col(hashColumn).notEqual(oldData.col(hashColumn)))
                .select(newData.columns())
                .withColumn("start_date", current_date())
                .withColumn("end_date", lit(null).cast("date"))
                .withColumn("current_flag", lit(true));

        // Identify new rows to insert
