                .equalTo(oldData.col(primaryKey)), "leftanti")
                .withColumn("start_date", current_date())
                .withColumn("end_date", lit(null).cast("date"))
                .withColumn("current_flag", lit(true));

        // Combine unchanged, changed old, changed new, and new rows
        Dataset<Row> result = unchangedData
                .union(changedOldData)
                .union(changedNewData)
                .union(newRows);

        // Use partitionBy and bucketing
        result.write()
                .partitionBy("end_date")
                .bucketBy(200, primaryKey)
                .sortBy(primaryKey)
                .parquet("path/to/output");

    }

    private static Dataset<Row> createHash(Dataset<Row> data, String[] nonKeyColumns, String hashColumn) {
