  };

  handleRemoveProduct = (productId) => {
    this.props.removeProduct(productId);
  };

  render() {
    return (
      <div className='products-list'>
        {this.props.products.map((product, id) => (
          <Card key={product.id} className='product-card' style={{ width: '18rem' }}>
            <Card.Img variant='top' src={product.thumbnail} />
            <Card.Body>
                <Card.Title>{product.title}</Card.Title>
                <Card.Text>{product.description}</Card.Text>
                <Card.Text>{product.price}$</Card.Text>
                <Card.Text>{product.discountPercentage}%</Card.Text>
                <Card.Text>{product.rating}</Card.Text>
                <Card.Text>{product.stock}</Card.Text>
                <Card.Text>{product.brand}</Card.Text>
                <Card.Text>{product.category}</Card.Text>
                <Button variant='primary' onClick={() => this.handleAddProduct(product)}>Buy Now</Button>
                <Button variant='secondary' onClick={() => this.handleRemoveProduct(product.id)}>Remove</Button>
            </Card.Body>
          </Card>
        ))}
      </div>
    );
  }
}

const mapStateToProps = (state) => {
  return {
    products: state.products
  };
};

export default connect(mapStateToProps, { addProduct, removeProduct })(ProductsList);
