public class Traversal {

    public static boolean DFS(ArrayList<Integer>[] adjList, 
                              Integer startNode, Integer destinationNode) {
        boolean[] visited = new boolean[adjList.length];
        return DFSUtil(adjList, startNode, destinationNode, visited);
    }

    private static boolean DFSUtil(ArrayList<Integer>[] adjList,
                           Integer currentNode, Integer destinationNode, boolean[] visited) {
        visited[currentNode] = true;

        if (currentNode.equals(destinationNode)) {
            return true;
        }

        for (Integer adjNode : adjList[currentNode]) {
            if (!visited[adjNode]) {
                if (DFSUtil(adjList, adjNode, destinationNode, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    public static ArrayList<Integer> BFS(ArrayList<Integer>[] adjList, Integer startNode) {
        boolean[] visited = new boolean[adjList.length];
        visited[startNode] = true;

        ArrayList<Integer> q = new ArrayList<>();
        ArrayList<Integer> visitedNodes = new ArrayList<>();
        q.add(startNode);
        visitedNodes.add(startNode);

        while (!q.isEmpty()) {
            Integer currentNode = q.remove(0);
            for (Integer adjNode : adjList[currentNode]) {
                if (!visited[adjNode]) {
                    visited[adjNode] = true;
                    q.add(adjNode);
                    visitedNodes.add(adjNode);
                }
            }
        }
        return visitedNodes;
    }
}
