1. Лексер (с добавлением обработки переменных, корня и степени):

```javascript
function lexer(expression) {
    let tokens = [];
    let curr = 0;

    while (curr < expression.length) {
        let char = expression[curr];

        if (/\d/.test(char)) {
            let value = '';

            while (/\d/.test(char) && curr < expression.length) {
                value += char;
                char = expression[++curr];
            }

            tokens.push({ type: 'number', value: parseInt(value) });
            continue;
        }

        if (/\w/.test(char)) {
            let value = '';

            while (/\w/.test(char) && curr < expression.length) {
                value += char;
                char = expression[++curr];
            }

            tokens.push({ type: 'identifier', value: value });
            continue;
        }

        if (char === '+') {
            tokens.push({ type: 'plus' });
            curr++;
            continue;
        }

        if (char === '-') {
            tokens.push({ type: 'minus' });
            curr++;
            continue;
        }

        if (char === '*') {
            tokens.push({ type: 'multiply' });
            curr++;
            continue;
        }

        if (char === '/') {
            tokens.push({ type: 'divide' });
            curr++;
            continue;
        }

        if (char === '^') {
            tokens.push({ type: 'power' });
            curr++;
            continue;
        }

        if (char === '=') {
            tokens.push({ type: 'assign' });
            curr++;
            continue;
        }

        if (char === '√') {
            tokens.push({ type: 'sqrt' });
            curr++;
            continue;
        }

        // skip whitespaces
        if (/\s/.test(char)) {
            curr++;
            continue;
        }

        throw new Error(`Unrecognized token: ${char}`);
    }

    return tokens;
}
```

2. Парсер (с добавлением обработки переменных, корня и степени):

```javascript
function parser(tokens) {
    let index = 0;

    function walk() {
        let token = tokens[index++];

        if (token.type === 'number') {
            return {
                type: 'NumberLiteral',
                value: token.value,
            };
        }

        if (token.type === 'identifier') {
            let variable = {
                type: 'Variable',
                name: token.value,
            };

            if (tokens.length > index && tokens[index].type === 'assign') {
                index++; // skip '='
                variable.assignValue = walk();
            }

            return variable;
        }

        if (token.type === 'sqrt') {
            const node = {
                type: 'UnaryExpression',
                operator: 'sqrt',
                argument: walk(),
            };

            return node;
        }

        if (['plus', 'minus', 'multiply', 'divide', 'power'].includes(token.type)) {
            const node = {
                type: 'BinaryExpression',
                operator: token.type,
                left: walk(),
                right: walk(),
            };
            return node;
        }

        throw new Error('Unrecognized token and syntax error');
    }

    let ast = {
        type: 'Program',
        body: [],
    };

    while (index < tokens.length) {
        ast.body.push(walk());
    }

    return ast;
}
```

3. Анализатор AST и интерпретатор (с добавлением обработки переменных, корня и степени):

```javascript
function interpreter(ast) {
    let env = {};

    function walk(node) {
        switch (node.type) {
            case 'NumberLiteral':
                return node.value;
            case 'Variable':
                if (node.assignValue) {
                    env[node.name] = walk(node.assignValue);
                }

                return env[node.name];
            case 'UnaryExpression':
                let argument = walk(node.argument);

                switch (node.operator) {
                    case 'sqrt':
                        return Math.sqrt(argument);
                }
                break;
            case 'BinaryExpression':
                let left = walk(node.left);
                let right = walk(node.right);

                switch (node.operator) {
                    case 'plus':
                        return left + right;
                    case 'minus':
                        return left - right;
                    case 'multiply':
                        return left * right;
                    case 'divide':
                        return left / right;
                    case 'power':
                        return Math.pow(left, right);
                }

                break;

            default:
                throw new Error('Unrecognized AST node');
        }
    }

    let result = walk(ast.body[0]);
    return result;
}
```

