```javascript
const expression = 'x = 3 + 5 * 2 - 4 / 2; y = x^2; z = √(y^2)';
const tokens = lexer(expression);
const ast = parser(tokens);
const result = interpreter(ast);
console.log(expression, '=', result); // z = 18
```

