```kotlin
import android.content.Context
import android.os.Handler
import android.util.AttributeSet
import androidx.appcompat.widget.AppCompatImageView

abstract class BaseImageIteratorView : AppCompatImageView {

    private val handler = Handler()
    private val images = mutableListOf<Int>()
    private var currentIndex = 0

    constructor(context: Context) : super(context) {
        setup()
    }

    constructor(context: Context, attrs: AttributeSet) : super(context, attrs) {
        setup()
    }

    constructor(context: Context, attrs: AttributeSet, defStyleAttr: Int) : super(context, attrs, defStyleAttr) {
        setup()
    }

    private fun setup() {
        images.addAll(provideImages())
        startIteratingImages()
    }

    private fun startIteratingImages() {
        setImageResource(images[currentIndex])
        handler.postDelayed({
            currentIndex = (currentIndex + 1) % images.size
            startIteratingImages()
        }, getDelayMillis())
    }

    abstract fun provideImages(): List<Int>

    abstract fun getDelayMillis(): Long
}

class CustomImageIteratorView : BaseImageIteratorView {

    constructor(context: Context) : super(context)

    constructor(context: Context, attrs: AttributeSet) : super(context, attrs)

    constructor(context: Context, attrs: AttributeSet, defStyleAttr: Int) : super(context, attrs, defStyleAttr)

    override fun provideImages(): List<Int> {
        return listOf(
            R.drawable.image_1,
            R.drawable.image_2,
            R.drawable.image_3
        )
    }

    override fun getDelayMillis(): Long {
        return 3000L
    }
}
```

In this example, the class `CustomImageIteratorView` inherits from the abstract base class `BaseImageIteratorView` and overrides the `provideImages` and `getDelayMillis` methods to specify the image list and the delay between image updates. The base class handles image iteration every `getDelayMillis` milliseconds.

