```java
import javax.swing.*;
import java.awt.*;

public class PianoKeyboard extends JFrame {
    private static final int WHITE_KEY_WIDTH = 20;
    private static final int WHITE_KEY_HEIGHT = 100;
    private static final int BLACK_KEY_WIDTH = 14;
    private static final int BLACK_KEY_HEIGHT = 60;

    public PianoKeyboard() {
        setTitle("88 Key Piano");
        setSize(WHITE_KEY_WIDTH * 52, WHITE_KEY_HEIGHT + 25);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        JPanel panel = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                super.paintComponent(g);
                int currentPos = 0;
                int octave = 7; 

                for (int i = 1; i <= 88; i++) {
                    if (isWhiteKey(i)) {
                        g.setColor(Color.WHITE);
                        g.fillRect(currentPos, 0, WHITE_KEY_WIDTH, WHITE_KEY_HEIGHT);
                        g.setColor(Color.BLACK);
                        g.drawRect(currentPos, 0, WHITE_KEY_WIDTH, WHITE_KEY_HEIGHT);
                        currentPos += WHITE_KEY_WIDTH;
                    } else {
                        g.setColor(Color.BLACK);
                        g.fillRect(currentPos - BLACK_KEY_WIDTH / 2, 0, BLACK_KEY_WIDTH, BLACK_KEY_HEIGHT);
                    }
                }
            }
        };

        getContentPane().add(panel);
    }

    private boolean isWhiteKey(int keyNumber) {
        int[] whiteKeyIndices = {1, 2, 4, 5, 6};
        int whiteKeyCount = 7;
        int group = keyNumber % whiteKeyCount;

        for (int idx : whiteKeyIndices) {
            if (group == idx) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame pianoKeyboard = new PianoKeyboard();
            pianoKeyboard.setVisible(true);
        });
    }
}
