private List<double[]> processYSeries(double[] ySeries) {
    List<double[]> segments = new ArrayList<>();

    int gap = 0;
    List<Double> currentSegment = new ArrayList<>();

    for (int i = 0; i < ySeries.length; i++) {
        if (Double.isNaN(ySeries[i])) {
            gap++;
            if (gap > 100) {
                if (!currentSegment.isEmpty()) {
                    segments.add(toArray(currentSegment));
                    currentSegment = new ArrayList<>();
                }
            }
        } else {
            if (gap > 0 && gap <= 100) {
                for (int j = 0; j < gap; j++) {
                    currentSegment.add(Double.NaN);
                }
            }
            currentSegment.add(ySeries[i]);
            gap = 0;
        }
    }

    if (!currentSegment.isEmpty()) {
        segments.add(toArray(currentSegment));
    }

    return segments;
}

private double[] toArray(List<Double> list) {
    double[] array = new double[list.size()];
    for (int i = 0; i < list.size(); i++) {
        array[i] = list.get(i);
    }
    return array;
}
