```csharp
public static Mat RemoveLineFromImage(Mat inputImage, int minLineLength = 50, int maxLineGap = 20)
{
    // Convert the input image to grayscale
    Mat grayImage = new Mat();
    CvInvoke.CvtColor(inputImage, grayImage, ColorConversion.Bgr2Gray);

    // Apply edge detection using the Canny algorithm
    Mat edges = new Mat();
    CvInvoke.Canny(grayImage, edges, 50, 150);

    // Find lines in the image using the HoughLinesP method
    VectorOfPointF lines = new VectorOfPointF();
    CvInvoke.HoughLinesP(edges, lines, 1, Math.PI / 180, 100, minLineLength, maxLineGap);

    // Create a mask to remove the detected lines
    Mat mask = Mat.Ones(inputImage.Rows, inputImage.Cols, DepthType.Cv8U, 3);

    for (int i = 0; i < lines.Size; i++)
    {
        PointF p1 = new PointF(lines[i].X, lines[i].Y);
        PointF p2 = new PointF(lines[i].Z, lines[i].W);
        CvInvoke.Line(mask, Point.Round(p1), Point.Round(p2), new MCvScalar(0, 0, 0), 2);
    }

    // Create the output image by applying the mask
    Mat outputImage = new Mat();
    CvInvoke.Subtract(inputImage, mask, outputImage);
    return outputImage;
}
```

