    Mat inputImage = CvInvoke.Imread("input.jpg");

    // Remove the line from the image
    Mat outputImage = RemoveLineFromImage(inputImage);

    // Save the output image
    CvInvoke.Imwrite("output.jpg", outputImage);
}
