```csharp
public static Mat BitmapToMat(Bitmap bitmap)
{
    // Initialize an empty Mat object of the same size as the input Bitmap
    Mat mat = new Mat(bitmap.Height, bitmap.Width, DepthType.Cv8U, 3);

    // Convert the Bitmap to a GDI+ image
    System.Drawing.Imaging.BitmapData bmpData = bitmap.LockBits(new Rectangle(0, 0, bitmap.Width, bitmap.Height),
        System.Drawing.Imaging.ImageLockMode.ReadOnly, bitmap.PixelFormat);

    // Copy data from the GDI+ image to the Mat object
    CvInvoke.cvCopy(IntPtr.Zero, bmpData.Scan0, mat.Ptr, IntPtr.Zero);

    // Unlock the Bitmap
    bitmap.UnlockBits(bmpData);

    return mat;
}
