import time
import random
import math

A = 907898232
B = 317181867


def elliptic_curve(x, y, p):
    return (y ** 2) % p == (x ** 3 + (A % p) * x + (B % p)) % p


def print_curve(p):
    print(f"y^2 = x^3 + {A % p} * x + {B % p} [p = {p}]")


def euclidean_algo(a, b):
    s, old_s = 0, 1
    t, old_t = 1, 0
    r, old_r = b, a

    while r != 0:
        quotient = old_r // r
        old_r, r = r, old_r - quotient * r
        old_s, s = s, old_s - quotient * s
        old_t, t = t, old_t - quotient * t

    return old_r, old_s, old_t


def inverse(n, p):
    gcd, x, y = euclidean_algo(n, p)
    assert (n * x + p * y) % p == gcd

    if gcd != 1:
        return -1
    else:
        return x % p


def add_points(p1, p2, p):
    if p1 == (0, 0):
        return p2
    elif p2 == (0, 0):
        return p1
    elif p1[0] == p2[0] and p1[1] != p2[1]:
        return (0, 0)

    if p1 == p2:
        s = ((3 * p1[0] ** 2 + (A % p)) * inverse(2 * p1[1], p)) % p
    else:
        s = ((p1[1] - p2[1]) * inverse(p1[0] - p2[0], p)) % p
    x = (s ** 2 - 2 * p1[0]) % p
    y = (p1[1] + s * (x - p1[0])) % p
    return (x, -y % p)


def order_point(point, p):
    i = 1
    check = add_points(point, point, p)
    while check != (0, 0):
        check = add_points(check, point, p)
        i += 1
    return i


def is_prime_number(number):
    if number < 2:
        return False
    if number == 2:
        return True
    if number % 2 == 0:
        return False

    for i in range(3, int(math.sqrt(number)) + 1, 2):
        if number % i == 0:
            return False

    return True


def get_next_prime_number(start):
    number = start
    while not is_prime_number(number):
        number += 1
    return number


