You can use the C# Bitmap class in conjunction with some simple image processing techniques to remove the horizontal line from each image. Here's a method that does that:

```csharp
using System.Drawing;
using System.Drawing.Imaging;

public static void RemoveHorizontalLine(string inputImagePath, string outputImagePath)
{
    Bitmap inputImage = new Bitmap(inputImagePath);

    Color blackColor = Color.FromArgb(0, 0, 0);
    Color whiteColor = Color.FromArgb(255, 255, 255);

    int tolerance = 10;

    for (int y = 0; y < inputImage.Height; y++)
    {
        for (int x = 1; x < inputImage.Width - 1; x++)
        {
            Color currentPixel = inputImage.GetPixel(x, y);

            if (IsSimilarColor(currentPixel, blackColor, tolerance))
            {
                Color leftPixel = inputImage.GetPixel(x - 1, y);
                Color rightPixel = inputImage.GetPixel(x + 1, y);

                if (IsSimilarColor(leftPixel, whiteColor, tolerance) && IsSimilarColor(rightPixel, whiteColor, tolerance))
                {
                    inputImage.SetPixel(x, y, whiteColor);
                }
            }
        }
    }

    inputImage.Save(outputImagePath, ImageFormat.Png);
}

public static bool IsSimilarColor(Color a, Color b, int tolerance)
{
    int rDiff = Math.Abs(a.R - b.R);
    int gDiff = Math.Abs(a.G - b.G);
    int bDiff = Math.Abs(a.B - b.B);

    return rDiff <= tolerance && gDiff <= tolerance && bDiff <= tolerance;
}
```

