Then, you can use the AForge's Blob Processing and Filters features to remove the horizontal line from your images. Create a method like this:

```csharp
using AForge.Imaging;
using AForge.Imaging.Filters;
using System.Drawing;
using System.Drawing.Imaging;

public static void RemoveHorizontalLine(string inputImagePath, string outputImagePath)
{
    // Load input image
    Bitmap inputImage = new Bitmap(inputImagePath);

    // Create grayscale filter
    Grayscale grayscaleFilter = new Grayscale(0.2125, 0.7154, 0.0721);
    Bitmap grayscaleImage = grayscaleFilter.Apply(inputImage);

    // Create threshold filter
    Threshold thresholdFilter = new Threshold(128); // You can adjust the threshold level
    thresholdFilter.ApplyInPlace(grayscaleImage);

    // Create blob counter
    BlobCounter blobCounter = new BlobCounter();
    blobCounter.MinWidth = inputImage.Width / 2;
    blobCounter.FilterBlobs = true;

    // Find the blobs in the threshold image
    blobCounter.ProcessImage(grayscaleImage);
    Blob[] blobs = blobCounter.GetObjectsInformation();

    // Remove horizontal line by painting it white
    using (Graphics g = Graphics.FromImage(inputImage))
    {
        foreach (Blob blob in blobs)
        {
            if (blob.Rectangle.Width > inputImage.Width / 2 && blob.Rectangle.Height < inputImage.Height / 10)
            {
                g.FillRectangle(Brushes.White, blob.Rectangle);
            }
        }
    }

    // Save output image
    inputImage.Save(outputImagePath, ImageFormat.Png);
}
```

To use this method, call it with the paths of the input images and desired output paths:

```csharp
string inputPath = "path/to/your/input/image.png";
string outputPath = "path/to/your/output/image.png";
RemoveHorizontalLine(inputPath, outputPath);
```

This method will remove horizontal lines that are more than half the image's width in size, and less than 10% of the image's height in thickness. You may need to adjust the parameters to better suit your specific images.

