        File directory = new File("/path/to/directory"); // Change this to your directory path
        ObjectMapper mapper = new ObjectMapper(); // create a Jackson object mapper

        for (File file : directory.listFiles()) {
            if (file.isFile() && file.getName().endsWith(".json")) {
                try {
                    List<String> lines = Files.readAllLines(file.toPath()); // read all lines in the file
                    StringBuffer sb = new StringBuffer(); 
                    for (String line : lines) { // concatenate all lines into a single string
                        sb.append(line);
                    }
                    String jsonStr = sb.toString();

                    // map the JSON string to a Java object
                    Object obj = mapper.readValue(jsonStr, Object.class);
