#include <arpa/inet.h>
#include <ctype.h>
#include <errno.h>
#include <netdb.h>
#include <netinet/in.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

#define FYI 0x01
#define MYM 0x02
#define END 0x03
#define TXT 0x04
#define MOV 0x05
#define LFT 0x06
#define BUF_SIZE 512
#define MAX_PLAYERS 2

typedef struct
{
    int x;
    int y;
} Move;

typedef struct
{
    int sockfd;
    char board[3][3];
    int player;
    Move last_move;
} Player;

int check_win(char board[3][3])
{
    for (int i = 0; i < 3; i++)
    {
        if (board[i][0] != 0 && board[i][0] == board[i][1] && board[i][0] == board[i][2])
            return board[i][0];
        if (board[0][i] != 0 && board[0][i] == board[1][i] && board[0][i] == board[2][i])
            return board[0][i];
    }
    if (board[0][0] != 0 && board[0][0] == board[1][1] && board[0][0] == board[2][2])
        return board[0][0];
    if (board[0][2] != 0 && board[0][2] == board[1][1] && board[0][2] == board[2][0])
        return board[0][2];
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 2)
    {
        fprintf(stderr, "Usage: %s <port>\n", argv[0]);
        return 1;
    }

    int sockfd, newsockfd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t clilen;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0)
    {
        perror("Error opening socket");
        return 1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    int port_number = atoi(argv[1]);
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(port_number);

    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0)
    {
        perror("Error binding");
        return 1;
    }

    listen(sockfd, 5);
    clilen = sizeof(cli_addr);

    Player players[MAX_PLAYERS];
    int player_count = 0;
    char buffer[BUF_SIZE];

    while (player_count < MAX_PLAYERS)
    {
        newsockfd = accept(sockfd, (struct sockaddr *)&cli_addr, &clilen);
        if (newsockfd < 0)
        {
            perror("Error accepting");
            continue;
        }
        players[player_count].sockfd = newsockfd;
        memset(players[player_count].board, 0, sizeof(players[player_count].board));
        players[player_count].player = player_count + 1;
        player_count++;
    }

    close(sockfd);

    int game_over = 0;
    int currentPlayer = 0;
    int total_moves = 0;
    while (!game_over)
    {
        Player *current = &players[currentPlayer];

        memset(buffer, 0, BUF_SIZE);
        buffer[0] = FYI;
        buffer[1] = total_moves;
        for (int i = 0; i < player_count; i++)
        {
            buffer[2 + i * 3] = players[i].player;
            buffer[3 + i * 3] = players[i].last_move.x;
            buffer[4 + i * 3] = players[i].last_move.y;
        }

        for (int i = 0; i < player_count; i++)
        {
            if (i == currentPlayer)
            {
                buffer[0] = MYM;
            }
            else
            {
                buffer[0] = FYI;
            }
            if (write(players[i].sockfd, buffer, BUF_SIZE) < 0)
            {
                perror("Error writing to socket");
            }
        }

        int n = read(current->sockfd, buffer, BUF_SIZE);
        if (n < 0)
        {
            perror("Error reading from socket");
            game_over = 1;
        }

        if (buffer[0] == MOV)
        {
            int x = buffer[1];
            int y = buffer[2];
            current->board[y][x] = current->player;
            current->last_move.x = x;
            current->last_move.y = y;
            total_moves++;

            int winner = check_win(current->board);
            if (winner > 0 || total_moves == 9)
            {
                game_over = 1;
                memset(buffer, 0, BUF_SIZE);
                buffer[0] = END;
                buffer[1] = winner;

                for (int i = 0; i < player_count; i++)
                {
                    if (write(players[i].sockfd, buffer, BUF_SIZE) < 0)
                    {
                        perror("Error writing to socket");
                    }
                }
            }
            else
            {
                currentPlayer = (currentPlayer + 1) % player_count;
            }
        }
        else if (buffer[0] == LFT)
        {
            game_over = 1;
            memset(buffer, 0, BUF_SIZE);
            sprintf(buffer + 1, "Player %d left the game.", current->player);
            buffer[0] = TXT;

            for (int i = 0; i < player_count; i++)
            {
                if (i != currentPlayer)
                {
                    if (write(players[i].sockfd, buffer, BUF_SIZE) < 0)
                    {
                        perror("Error writing to socket");
                    }
                }
            }
        }
        else
        {
            perror("Invalid message received");
            game_over = 1;
        }
    }

    for (int i = 0; i < player_count; i++)
    {
        close(players[i].sockfd);
    }

    return 0;
}

