Для получения информации о текущем авторизованном пользователе в GIO можно использовать класс GUnixCredentialsMessage. Пример кода для получения PID текущего процесса и информации о его учётных данных:

```c
#include <gio/gunixcredentialsmessage.h>

gboolean get_credentials() {
    GUnixCredentialsMessage *msg;
    guchar *data;
    gsize len;
    GPid pid;
    gint64 uid, gid;
    gchar *username;

    pid = getpid();
    msg = g_unix_credentials_message_new(pid, getppid(), NULL);
    if (msg == NULL) {
        g_warning("Failed to create credentials message");
        return FALSE;
    }

    data = g_unix_credentials_message_serialize(msg, &len);
    if (data == NULL) {
        g_warning("Failed to serialize credentials message");
        g_object_unref(msg);
        return FALSE;
    }

    if (!g_unix_credentials_message_parse(data, len, &pid, &uid, &gid, &username)) {
        g_warning("Failed to parse credentials message");
        g_object_unref(msg);
        g_free(data);
        return FALSE;
    }

    g_print("PID: %d\n", pid);
    g_print("UID: %ld\n", uid);
    g_print("GID: %ld\n", gid);
    g_print("Username: %s\n", username);

    g_object_unref(msg);
    g_free(data);

    return TRUE;
}
```

Для получения информации о другом процессе или сокете можно использовать функции GSocket и GPermission. Например, для получения информации о владельце сокета:

```c
#include <gio/gunixsocketaddress.h>

gboolean get_socket_info(const gchar *path) {
    GSocketClient *client;
    GSocketConnection *conn;
    GSocketAddress *sockaddr;
    GPermission *permission;
    GPid pid;
    uid_t uid;
    gchar *username, *groupname;

    sockaddr = g_unix_socket_address_new(path);
    if (sockaddr == NULL) {
        g_warning("Failed to create socket address");
        return FALSE;
    }

    client = g_socket_client_new();
    conn = g_socket_client_connect(client, sockaddr, NULL, NULL);
    if (conn == NULL) {
        g_warning("Failed to connect to socket");
        g_object_unref(sockaddr);
        g_object_unref(client);
        return FALSE;
    }

    permission = g_socket_connection_get_permission(conn);
    if (permission == NULL) {
        g_warning("Failed to get permission for socket");
        g_object_unref(conn);
        g_object_unref(sockaddr);
        g_object_unref(client);
        return FALSE;
    }

    pid = g_permission_get_process_id(permission);
    uid = g_permission_get_user(permission);
    username = g_permission_get_user_name(permission);
    groupname = g_permission_get_group_name(permission);

    g_print("PID: %d\n", pid);
    g_print("UID: %ld\n", uid);
    g_print("Username: %s\n", username);
    g_print("Groupname: %s\n", groupname);

    g_free(username);
    g_free(groupname);
    g_object_unref(permission);
    g_object_unref(conn);
    g_object_unref(sockaddr);
    g_object_unref(client);

    return TRUE;
}
