#include <gio/gio.h>
#include <unistd.h>

static void dump_bus_creds(GUnixCredentialsMessage *creds) {
    GPid pid;
    guchar *uid_data, *gid_data, *pid_data;
    gsize uid_len, gid_len, pid_len;
    gchar *username, *groupname;

    pid_data = g_unix_credentials_message_get_credentials(creds, G_CREDENTIALS_PID, &pid_len);
    if (pid_data != NULL) {
        memcpy(&pid, pid_data, sizeof(pid));
        g_print("PID: %d\n", pid);
        g_free(pid_data);
    }

    uid_data = g_unix_credentials_message_get_credentials(creds, G_CREDENTIALS_UID, &uid_len);
    if (uid_data != NULL) {
        username = g_strdup(g_find_program_owner(uid_data));
        if (username != NULL)
            g_print("Username: %s\n", username);
        g_free(username);
        g_free(uid_data);
    }

    gid_data = g_unix_credentials_message_get_credentials(creds, G_CREDENTIALS_GID, &gid_len);
    if (gid_data != NULL) {
        groupname = g_strdup(g_find_program_group(gid_data));
        if (groupname != NULL)
            g_print("Groupname: %s\n", groupname);
        g_free(groupname);
        g_free(gid_data);
    }
}

