                return -1;
            }
            creds = g_unix_credentials_message_new(0, 0, NULL);
            success = g_unix_credentials_message_set_credentials(creds, G_CREDENTIALS_PID, &pid, sizeof(pid)) &&
                      g_unix_credentials_message_set_credentials(creds, G_CREDENTIALS_UID,
                          (guchar *) &g_permission_get_uid(permission), sizeof(uid_t)) &&
                      g_unix_credentials_message_set_credentials(creds, G_CREDENTIALS_GID,
                          (guchar *) &g_permission_get_gid(permission), sizeof(gid_t));
            g_object_unref(permission);
            g_object_unref(conn);
            if (!success) {
                g_warning("Failed to set credentials for process %s", argv[1]);
                g_object_unref(creds);
                return -1;
            }
        } else {
            creds = g_unix_credentials_message_new(pid, 0, NULL);
            if (creds == NULL) {
                g_warning("Failed to create credentials message");
                return -1;
            }
        }
    } else {
        conn = g_bus_get_sync(G_BUS_TYPE_SESSION, NULL, NULL);
        if (conn == NULL) {
            g_warning("Failed to connect to session bus");
            return -1;
        }
        sockaddr = g_socket_connection_get_local_address(G_SOCKET_CONNECTION(conn), NULL);
        if (sockaddr != NULL) {
            path = g_unix_socket_address_get_path((GUnixSocketAddress *) sockaddr);
            g_print("Socket path: %s\n", path);
            g_object_unref(sockaddr);
        }
        creds = g_unix_credentials_message_new(0, 0, NULL);
        if (creds == NULL) {
            g_warning("Failed to create credentials message");
            g_object_unref(conn);
            return -1;
        }
        permission = g_dbus_connection_get_peer_credentials(conn);
        if (permission == NULL) {
            g_warning("Failed to get credentials for current process");
            g_object_unref(conn);
            g_object_unref(creds);
            return -1;
        }
        success = g_unix_credentials_message_set_credentials(creds, G_CREDENTIALS_PID, &pid, sizeof(pid)) &&
                  g_unix_credentials_message_set_credentials(creds, G_CREDENTIALS_UID,
                      (guchar *) &g_permission_get_uid(permission), sizeof(uid_t)) &&
                  g_unix_credentials_message_set_credentials(creds, G_CREDENTIALS_GID,
                      (guchar *) &g_permission_get_gid(permission), sizeof(gid_t));
        g_object_unref(permission);
        g_object_unref(conn);
        if (!success) {
            g_warning("Failed to set credentials for current process");
            g_object_unref(creds);
            return -1;
        }
    }

    dump_bus_creds(creds);
    g_object_unref(creds);
    g_free(path);
    return 0;
}
```

Как видно из примера, в GIO есть функции для получения учётных данных процессов и сокетов. Для этого используются классы GUnixCredentialsMessage, GPermission, GSocketAddress и GSocketConnection.

Да, конечно, если вам нужно получить GCredentials вместо строки, вы можете изменить функцию `dump_bus_creds` следующим образом:

```c
static void dump_bus_creds(GUnixCredentialsMessage *creds) {
    GPid pid;
    GCredentials *credentials;
    gchar *username, *groupname;

    credentials = g_unix_credentials_message_get_credentials(creds, G_CREDENTIALS_PID);
    if (credentials != NULL) {
        g_credential_get(credentials, GCRED_PID, &pid, -1);
        g_print("PID: %d\n", pid);
        g_object_unref(credentials);
    }

    credentials = g_unix_credentials_message_get_credentials(creds, G_CREDENTIALS_UID);
    if (credentials != NULL) {
        g_credential_get(credentials, GCRED_USERNAME, &username, -1);
        if (username != NULL)
            g_print("Username: %s\n", username);
        g_free(username);
        g_object_unref(credentials);
    }

    credentials = g_unix_credentials_message_get_credentials(creds, G_CREDENTIALS_GID);
    if (credentials != NULL) {
        g_credential_get(credentials, GCRED_GROUPNAME, &groupname, -1);
        if (groupname != NULL)
            g_print("Groupname: %s\n", groupname);
        g_free(groupname);
        g_object_unref(credentials);
    }
}
```

В этом примере для получения логина пользователя и имени группы используется параметр `GCRED_USERNAME` и `GCRED_GROUPNAME` функции `g_credential_get`. Если GCredentials не содержит необходимой информации, то указанный указатель будет равен `NULL`.

