    await botClient.SendTextMessageAsync(message.Chat.Id, "Loop stopped.");
}

// Register your handlers for the bot prefixes
botClient.OnMessage += async (sender, e) =>
{
    if (e.Message.Text.StartsWith("/startloop"))
    {
        if (cancellationTokenSource != null && !cancellationTokenSource.IsCancellationRequested)
        {
            await botClient.SendTextMessageAsync(e.Message.Chat.Id, "Loop is already running.");
            return;
        }

        string[] parts = e.Message.Text.Split(' ');
        string times = parts[1];
        string seconds = parts[2];

        cancellationTokenSource = new CancellationTokenSource();
        loopTask = StartLoop(e.Message, times, seconds, cancellationTokenSource.Token);

        await botClient.SendTextMessageAsync(e.Message.Chat.Id, "Loop started.");
    }
    else if (e.Message.Text.StartsWith("/stoploop"))
    {
        await StopLoop(e.Message);
    }
};
```

In this implementation, the `StartLoop` method now takes a `CancellationToken` that is used to stop the loop when the `/stoploop` command is issued. The loop is wrapped in a `Task` object using the `Task.Run` method, allowing it to run asynchronously.

The `cancellationTokenSource` and `loopTask` are used to track the state of the loop, and the `StopLoop` method checks if the loop is running and cancels it using the `CancellationToken`. The `loopTask` is awaited to ensure that the loop completes before continuing.

Note that the `cancellationTokenSource` object needs to be disposed after the loop is stopped by calling `cancellationTokenSource.Dispose()`. 

And finally, note that the `OnMessage` event handlers for the prefixes call the `StartLoop` and `StopLoop` methods as needed.

