    {
        UpdateReloadTimer();
        UpdateHealthBarAndText();

        if (_isPlayerControlled)
        {
            PerformMovement();
            PerformAimingAndShooting();
            UpdateShotDelayTimer();
        }
    }

    private void InitializePlayer()
    {
        _currentHealth = MaxHealth;
        _currentBullets = MaxBullets;
    }

    private void UpdateReloadTimer()
    {
        if (_currentBullets < MaxBullets)
        {
            _reloadTimer += Time.deltaTime;

            if (_reloadTimer >= ReloadTime)
            {
                _reloadTimer = 0f;
                _currentBullets++;
                UpdateBulletsText();
            }
        }
    }

    private void UpdateHealthBarAndText()
    {
        _healthBar.UpdateHealthBar(MaxHealth, _currentHealth);
        _healthText.text = _currentHealth.ToString();
    }

    private void PerformMovement()
    {
        _movementInput.x = Input.GetAxisRaw("Horizontal");
        _movementInput.y = Input.GetAxisRaw("Vertical");
        _movementInput.Normalize();

        _currentSpeed = MovementSpeed * _movementInput.magnitude;
        Vector3 movement = new Vector3(_movementInput.x, _movementInput.y, 0f) * _currentSpeed * Time.deltaTime;

        transform.position += movement;
    }

