    {
        UpdateAimDirectionBasedOnControlMode();

        if (_isAiming)
        {
            UpdateSightLine();
            TryFireBullet();
        }
        else
        {
            DestroySightLine();
        }
    }

    private void UpdateShotDelayTimer()
    {
        if (!_canShoot && _hasFiredRecently)
        {
            _shotTimer -= Time.deltaTime;

            if (_shotTimer <= 0f)
            {
                _canShoot = true;
                _hasFiredRecently = false;
            }
        }
    }

    private void UpdateAimDirectionBasedOnControlMode()
    {
        switch (CurrentControlMode)
        {
            case ControlMode.Mouse:
                if (Input.GetMouseButtonDown(0)) StartAiming();
                else if (Input.GetMouseButtonUp(0)) StopAiming();
                break;
            case ControlMode.Joystick:
                if (Mathf.Abs(_variableJoystick.Horizontal) > 0.1f || Mathf.Abs(_variableJoystick.Vertical) > 0.1f)
                {
                    if (!_isAiming) StartAiming();
                }
                else
