        float vertical = 0f;

        if (_shootingAgent.TryGetComponent<BehaviorParameters>(out var behaviorParameters))
        {
            var continuousActions = behaviorParameters.BrainParameters.VectorActionSize;
            var actions = _shootingAgent.GetAction();

            if (actions.ContinuousActions.Length > 0) horizontal = actions.ContinuousActions[0];
            if (actions.ContinuousActions.Length > 1) vertical = actions.ContinuousActions[1];
        }

        if (Mathf.Abs(horizontal) > 0.1f || Mathf.Abs(vertical) > 0.1f)
        {
            if (!_isAiming) StartAiming();
        }
        else
        {
            if (_isAiming) StopAiming();
        }
    }

