    }

    private void StopAiming()
    {
        DestroySightLine();
        TryFireBullet();

        _isAiming = false;
    }

    private void CreateSightLine()
    {
        _sightLine = new GameObject("SightLine");

        LineRenderer lineRenderer = _sightLine.AddComponent<LineRenderer>();
        lineRenderer.positionCount = 2;
        lineRenderer.startWidth = BulletWidth;
        lineRenderer.endWidth = BulletWidth;
        lineRenderer.material = CreateLineMaterial();
        lineRenderer.sortingLayerName = "Background";
        lineRenderer.sortingOrder = -1;
    }

    private Material CreateLineMaterial()
    {
        Material lineMaterial = new Material(Shader.Find("Sprites/Default"));
        lineMaterial.color = Color.white;

        return lineMaterial;
    }

    private void SetInitialSightLinePositions()
    {
        LineRenderer lineRenderer = _sightLine.GetComponent<LineRenderer>();
        lineRenderer.SetPosition(0, transform.position);
        lineRenderer.SetPosition(1, transform.position);
    }

    private void UpdateSightLine()
    {
        _lineEndPosition = (Vector2)transform.position + _aimDirection * _currentDistance;
        GetComponent<LineRenderer>().SetPosition(0, transform.position);
        GetComponent<LineRenderer>().SetPosition(1, _lineEndPosition);
    }

    private void DestroySightLine()
    {
        if (_sightLine == null) return;

        Destroy(_sightLine);
        _sightLine = null;
    }

    private void TryFireBullet()
    {
        if (!_canShoot || _currentBullets <= 0) return;

        if (_shotTimer <= 0f)
        {
            FireBullet();

            _currentBullets--;
            UpdateBulletsText();

            _canShoot = false;
            _shotTimer = ShotDelay;
        }
    }

    private void FireBullet()
    {
