2. Create an ES6 class to manage the sidebar navigation and load the data dynamically:

```javascript
// script.js
class Sidebar {
  constructor(data, containerId) {
    this.data = data;
    this.container = document.getElementById(containerId);
    this.buildNavigation(this.data, this.container);
  }

  buildNavigation(data, parentElement) {
    const ul = document.createElement('ul');

    data.forEach(item => {
      const li = document.createElement('li');
      li.classList.add('nav-item');

      const a = document.createElement('a');
      a.href = item.url || '#';
      a.textContent = item.title;

      li.addEventListener('click', event => {
        event.stopPropagation();

        if (item.children && item.children.length) {
          li.classList.toggle('active');
          const subNav = li.querySelector('ul');

          if (subNav) {
            subNav.style.display = li.classList.contains('active') ? 'block' : 'none';
          }
        } else if (typeof this.onNavigationItemClick === 'function') {
          this.onNavigationItemClick(event, item);
        }
      });

      li.appendChild(a);

      if (item.children && item.children.length) {
        this.buildNavigation(item.children, li);
      }

      ul.appendChild(li);
    });

    parentElement.appendChild(ul);
  }
}
