const Intervals = (str, val) => {
  const singleEquals = str.match(/^=(\d+)$/);
  const bothInclusive = str.match(/^\[(\d+),(\d+)\]$/);
  const leftInclusive = str.match(/^\[(\d+)$/);
  const rightInclusive = str.match(/^(\d+)\]$/);
  const leftExclusiveRightInclusive = str.match(/^\((\d+),(\d+)\]$/);
  const rightExclusiveLeftInclusive = str.match(/^\[(\d+),(\d+)\)$/);
  const leftExclusive = str.match(/^\((\d+)$/);
  const rightExclusive = str.match(/^(\d+)\)$/);

  if (singleEquals) {
    return val === parseInt(singleEquals[1]);
  } else if (bothInclusive) {
    return val >= parseInt(bothInclusive[1]) && val <= parseInt(bothInclusive[2]);
  } else if (leftInclusive) {
    return val >= parseInt(leftInclusive[1]);
  } else if (rightInclusive) {
    return val < parseInt(rightInclusive[1]);
  } else if (leftExclusiveRightInclusive) {
    return val > parseInt(leftExclusiveRightInclusive[1]) && val <= parseInt(leftExclusiveRightInclusive[2]);
  } else if (rightExclusiveLeftInclusive) {
    return val >= parseInt(rightExclusiveLeftInclusive[1]) && val < parseInt(rightExclusiveLeftInclusive[2]);
  } else if (leftExclusive) {
    return val > parseInt(leftExclusive[1]);
  } else if (rightExclusive) {
    return val < parseInt(rightExclusive[1]);
  }

  return false;
};
