cards.add(card);

int c = 5;
for (int n = 2; n <= 10; n++) {
Card oCard = new Card(suit, “” + n, n,c+i);
cards.add(oCard);
c+=4;
}

Card jackCard = new Card(suit, “Jack”, 10,41+i);
cards.add(jackCard);

Card queenCard = new Card(suit, “Queen”, 10,45+i);
cards.add(queenCard);

Card kingCard = new Card(suit, “King”, 10,49+i);
cards.add(kingCard);
}
}

