            descriptionTextView.text = data.description

            // Add the TextViews to the TableRow
            tableRow.addView(nameTextView)
            tableRow.addView(descriptionTextView)

            // Add the TableRow to the TableLayout
            tableLayout.addView(tableRow)
        }
    }

    private fun getDataFromDatabase(): List<Data> {
        // Retrieve the data from the database as a list of objects and return it
    }
}
```

This code will dynamically create a table in your Activity and populate it with data from the database. You can customize it further by adding styles to the TextViews, or by using custom layouts for the TableRow.

To make each item in the table clickable, you can add an `OnClickListener` to the `TableRow`. In the `OnClickListener`, you can retrieve the data associated with the clicked row and pass it to the next Activity using an Intent. Here's how you can modify the code to achieve this:

1. In the `for` loop where you create and add each `TableRow`, add an `OnClickListener` to the TableRow.
2. In the `OnClickListener`, retrieve the data associated with the clicked row and pass it to the next Activity using an Intent. You can set the data as extras in the Intent.
3. Start the new activity using the Intent.

Here's some example code to help you get started:

```kotlin
class TableActivity : AppCompatActivity() {

    private lateinit var tableLayout: TableLayout

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_table)

        // Get reference to the TableLayout
        tableLayout = findViewById(R.id.table_layout)

        // Retrieve data from the database as a list of objects
        val dataList = getDataFromDatabase()

        // Create TableRow dynamically and add it to the TableLayout for each object
        for (data in dataList) {
            val tableRow = TableRow(this)

            // Set OnClickListener for TableRow
            tableRow.setOnClickListener {
                // Create Intent for next Activity
                val intent = Intent(this, NextActivity::class.java)

                // Add data as extras to Intent
                intent.putExtra("name", data.name)
                intent.putExtra("description", data.description)

                // Start next Activity using Intent
                startActivity(intent)
            }

            // Create two TextViews for displaying name and description
