            val descriptionTextView = TextView(this)

            // Set text of each TextView to corresponding data
            nameTextView.text = data.name
            descriptionTextView.text = data.description

            // Add TextViews to TableRow
            tableRow.addView(nameTextView)
            tableRow.addView(descriptionTextView)

            // Add TableRow to TableLayout
            tableLayout.addView(tableRow)
        }
    }

    private fun getDataFromDatabase(): List<Data> {
        // Retrieve the data from the database as a list of objects and return it
    }
}
```

In this code, the `OnClickListener` for each `TableRow` creates an `Intent` for the next Activity, adds the data associated with the clicked row as extras to the Intent, and starts the next Activity using the Intent. You can retrieve the data in the next Activity using the `getIntent()` method and extract the extras from the Intent using the `getExtras()` method.

