Sure! Here's a C++ implementation of a priority queue using a binary heap for the CS106B course.

```cpp
#include <iostream>
#include <vector>
#include <stdexcept>

class PriorityQueue {
public:
    // Constructor
    PriorityQueue() {}

    // Add an element to the priority queue
    void enqueue(int value) {
        data.push_back(value);
        int childIndex = data.size() - 1;
        int parentIndex = (childIndex - 1) / 2;

        // Bubble up the value to its correct position
        while (childIndex > 0 && data[parentIndex] > data[childIndex]) {
            swap(parentIndex, childIndex);
            childIndex = parentIndex;
            parentIndex = (parentIndex - 1) / 2;
        }
    }

    // Remove and return the highest priority element from the priority queue
    int dequeue() {
        if (isEmpty()) {
            throw std::runtime_error("The priority queue is empty.");
        }

        int result = data[0];
        int lastIndex = data.size() - 1;
        swap(0, lastIndex);
        data.pop_back();

        int parentIndex = 0;

        // Bubble down the value to its correct position
        while (parentIndex < data.size()) {
            int leftChildIndex = 2 * parentIndex + 1;
            int rightChildIndex = 2 * parentIndex + 2;
            int minIndex = parentIndex;

            if (leftChildIndex < data.size() && data[leftChildIndex] < data[minIndex]) {
                minIndex = leftChildIndex;
            }

            if (rightChildIndex < data.size() && data[rightChildIndex] < data[minIndex]) {
                minIndex = rightChildIndex;
            }

            if (minIndex == parentIndex) {
                break;
            }

            swap(parentIndex, minIndex);
            parentIndex = minIndex;
        }

        return result;
    }

    // Check if the priority queue is empty
    bool isEmpty() const {
        return data.empty();
    }

private:
    // Swap two elements in the data vector
    void swap(int indexA, int indexB) {
        int temp = data[indexA];
        data[indexA] = data[indexB];
        data[indexB] = temp;
    }

    std::vector<int> data;
};

int main() {
    PriorityQueue pq;
    pq.enqueue(5);
    pq.enqueue(3);
    pq.enqueue(7);
    pq.enqueue(1);

    while (!pq.isEmpty()) {
        std::cout << "Dequeued: " << pq.dequeue() << std::endl;
    }

    return 0;
}
```

This implementation uses a `std::vector` to store the binary heap data. The `enqueue()` function adds an element to the priority queue and ensures that the binary heap property is preserved. The `dequeue()` function removes and returns the highest priority element (the smallest element) in the priority queue and maintains the binary heap property. The `isEmpty()` function checks if the priority queue is empty. The `swap()` private function is a helper function to swap two elements in the data vector.

Here's an Arduino code for your task, which reads the input signal from an analog input pin and controls a MOSFET to turn on or off a lamp based on the signal level. The code also calculates the frequency and amplitude of the input signal and updates an LCD display every 5 seconds. Note that calculating the frequency might not be very accurate but should give you a rough estimation.

```cpp
#include <LiquidCrystal.h>

// Constants
const int analogPin = A0;
const int mosfetPin = 9;
const int sampleWindow = 100; // Sample window in milliseconds
const int displayUpdateInterval = 5000; // Update LCD every 5 seconds

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

void setup() {
  pinMode(analogPin, INPUT);
  pinMode(mosfetPin, OUTPUT);

  lcd.begin(16, 2);
  lcd.setCursor(0, 0);
  lcd.print("Voltage: ");
  lcd.setCursor(0, 1);
  lcd.print("Freq: ");
}

void loop() {
  float Vmin = 1023.0, Vmax = 0.0;
  unsigned long pulseCount = 0;
  unsigned long startTime = millis();
  unsigned long nextDisplayUpdate = startTime + displayUpdateInterval;

  while (millis() - startTime < sampleWindow) {
    int reading = analogRead(analogPin);
    float voltage = reading * (5.0 / 1023.0);

    if (voltage >= (Vmax + Vmin) / 2) {
      digitalWrite(mosfetPin, HIGH);
      if (reading > Vmax) {
        Vmax = reading;
      }
    } else {
      digitalWrite(mosfetPin, LOW);
      if (reading < Vmin) {
        Vmin = reading;
      }
    }

    if(wasLow && voltage >= (Vmax + Vmin) / 2) {
      pulseCount++;
      wasLow = false;
    }
    if(voltage < (Vmax + Vmin) / 2) {
      wasLow = true;
    }
  }

  float frequency = pulseCount / (sampleWindow / 1000.0); // Calculate frequency in Hz

  if (millis() >= nextDisplayUpdate) {
    nextDisplayUpdate += displayUpdateInterval;
    lcd.setCursor(8, 0);
    lcd.print((Vmax + Vmin) / 2 * (5.0 / 1023.0), 2);
    lcd.print("   ");
    lcd.setCursor(5, 1);
    lcd.print(frequency, 1);
    lcd.print("  ");
  }

  digitalWrite(mosfetPin, LOW); // Turn off lamp
}
```

To construct the circuit in Proteus:

1. Place an Arduino Uno in the schematic.
2. Connect a variable input signal (sine, square, or triangle wave) to the A0 analog pin.
3. Add a 12V battery. Connect its positive terminal to the drain of an IRF740 MOSFET.
4. Connect the source of the MOSFET to the lamp, and the other end of the lamp to the ground.
5. Add a 10k ohm resistor between the gate of the MOSFET and the Arduino's digital output pin (D9 in this case).
6. Connect an LM016L LCD display to the Arduino. Use the connections defined in the code: RS (pin 12), E (pin 11), D4 (pin 5), D5 (pin 4), D6 (pin 3), and D7 (pin 2).
7. Connect the LCD's RW pin to ground, Vss to ground, and Vdd to 5V.
8. Add a 10k ohm potentiometer between 5V and ground, and connect the potentiometer's wiper (middle pin) to the V0 pin of the LCD to control the contrast.
9. For power supply, connect the Arduino's VIN pin to the 12V battery and place a common ground.

You should now have the required circuit. The input signal to the A0 pin can be changed to see the LCD update its values and control the lamp accordingly. The oscilloscope can be connected to the input signal and mosfetPin to observe the input and output signal.

