const { Pool, Route, Trade, TokenAmount, CurrencyAmount, Percent } = require('@uniswap/v3-sdk');
require('dotenv').config();

const INFURA_URL_TESTNET = 'https://mainnet.infura.io/v3/2d5bc62bb8d748cebfc64763e719cb4f';
const provider = new ethers.providers.JsonRpcProvider(INFURA_URL_TESTNET);

const name0 = 'Wrapped Ether';
const symbol0 = 'WETH';
const decimals0 = 18;
const address0 = '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2';

const name1 = 'Uniswap Token';
const symbol1 = 'UNI';
const decimals1 = 18;
const address1 = '0x1f9840a85d5aF5bf1D1762F925BDADdC4201F984';

const WALLET_ADDRESS = '0xf119B844b909d432d1EFEF94E1A0c600e5649134';
const WALLET_SECRET = '980ded7f6eedbcd45bde35672e3d8f6d14c277a0ab857ef7c237c729f25f6115';
const swapRouterAddress = '0xE592427A0AEce92De3Edee1F18E0157C05861564';

async function main(token0, token1, inputAmount = '0.001') {
  try {
    const poolAddress = await getPoolAddress(token0, token1, 3000); // This is the correct fee for this example
    const poolContract = new ethers.Contract(poolAddress, IUniswapV3PoolABI, provider);

    const immutables = await getPoolImmutables(poolContract);
    const state = await getPoolState(poolContract);

    const wallet = new ethers.Wallet(WALLET_SECRET);
    const connectedWallet = wallet.connect(provider);

    const swapRouterContract = new ethers.Contract(swapRouterAddress, SwapRouterABI, provider);

    const tokenA = new TokenAmount(token0, decimals0);
    const tokenB = new TokenAmount(token1, decimals1);

    const ratioAB = ethers.FixedNumber.from(inputAmount).divUnsafe(ethers.FixedNumber.from(1));
    const pool = new Pool(tokenA, tokenB, immutables.fee, state.sqrtPriceX96.toString(), 0, ratioAB.toString());

    const route = new Route([pool], tokenA);
    const trade = new Trade(route, CurrencyAmount.fromRawAmount(tokenA, inputAmount), Trade.Execution.EXACT_INPUT);

    const amountIn = ethers.utils.parseUnits(inputAmount.toString(), 18);
    const approvalAmount = (amountIn * 100000).toString();
    const tokenContract0 = new ethers.Contract(token0, ERC20ABI, provider);
    const approvalResponse = await tokenContract0.connect(connectedWallet).approve(swapRouterAddress, approvalAmount);
    console.log('Token Approval Response:', approvalResponse);

    const minAcceptableAmount = trade.outputAmount.multiply(new Percent(1 - 0.01));
    const params = {
      tokenIn: token0,
      tokenOut: token1,
      fee: immutables.fee,
      recipient: WALLET_ADDRESS,
      deadline: Math.floor(Date.now() / 1000) + 60 * 10,
      amountIn: amountIn,
      amountOutMinimum: minAcceptableAmount,
      sqrtPriceLimitX96: 0,
    };

    const transaction = await swapRouterContract.connect(connectedWallet).exactInputSingle(params, {
      gasLimit: ethers.utils.hexlify(1000000),
    });

    console.log('Transaction Response:', transaction);
  } catch (error) {
    console.error('Error:', error);
  }
}
