        std::vector<uint32_t> entitiesInRadius;

        for (const auto& pair : entityPositions_) {
            if (glm::distance(pair.second, center) <= radius) {
                entitiesInRadius.push_back(pair.first);
            }
        }

        return entitiesInRadius;
