    std::vector<uint32_t> GetEntitiesInFrustum(const glm::mat4& frustumMatrix) {
        // Assuming a left-handed coordinate system
        const std::array<glm::vec4, 6> frustumPlanes = {
            glm::row(frustumMatrix, 3) + glm::row(frustumMatrix, 0),
            glm::row(frustumMatrix, 3) - glm::row(frustumMatrix, 0),
            glm::row(frustumMatrix, 3) + glm::row(frustumMatrix, 1),
            glm::row(frustumMatrix, 3) - glm::row(frustumMatrix, 1),
            glm::row(frustumMatrix, 3) + glm::row(frustumMatrix, 2),
            glm::row(frustumMatrix, 3) - glm::row(frustumMatrix, 2),
        };

        std::vector<uint32_t> entitiesInFrustum;

        for (const auto& pair : entityPositions_) {
            bool insideFrustum = true;
            for (const auto& plane : frustumPlanes) {
                if (glm::dot(glm::vec4(pair.second, 1.0f), plane) < 0) {
                    insideFrustum = false;
                    break;
                }
            }

            if (insideFrustum) {
                entitiesInFrustum.push_back(pair.first);
            }
        }

        return entitiesInFrustum;
    }

private:
    ECS& ecs_;
    std::unordered_map<uint32_t, glm::vec3> entityPositions_;
};
