class SpatialSystem : public SystemBase {
public:
    SpatialSystem(ECS& ecs) : ecs_(ecs) {}

    void SetEntityPosition(const uint32_t entityId, const Vec3& position, const AABB& boundingVolume) {
        entityPositions_[entityId] = position;
        entityAABBs_[entityId] = boundingVolume;
    }

    std::vector<uint32_t> GetEntitiesInRadius(const Vec3& center, float radius) {
        std::vector<uint32_t> entitiesInRadius;

        for (const auto& pair : entityPositions_) {
            Vec3 min = entityAABBs_[pair.first].min;
            Vec3 max = entityAABBs_[pair.first].max;

            float squareDistance = squareDistanceAABBToPoint(min, max, center);

            if (squareDistance <= radius * radius) {
                entitiesInRadius.push_back(pair.first);
            }
        }

        return entitiesInRadius;
    }

    // For simplicity, GetEntitiesInFrustum() implementation is omitted.
    // Implementing it without using a library like glm involves more substantial effort.

private:
    float squareDistanceAABBToPoint(const Vec3& min, const Vec3& max, const Vec3& point) {
        float dx = std::max(std::max(min.x - point.x, 0.0f), point.x - max.x);
        float dy = std::max(std::max(min.y - point.y, 0.0f), point.y - max.y);
        float dz = std::max(std::max(min.z - point.z, 0.0f), point.z - max.z);

        return dx * dx + dy * dy + dz * dz;
    }

    ECS& ecs_;
    std::unordered_map<uint32_t, Vec3> entityPositions_;
    std::unordered_map<uint32_t, AABB> entityAABBs_;
};
```

