Sure! Here's an implementation of a basic k-d tree for the `SpatialSystem`. This version is simplified for 3D points but can be easily extended for other dimensions or attributes.

First, define the structures and helper functions:

```cpp
#include <memory>
#include <limits>
#include <algorithm>
#include <vector>
#include "ECS.h"

struct Vec3 {
    float x, y, z;
};

struct KDNode {
    uint32_t entityId;
    Vec3 point;
    std::unique_ptr<KDNode> left;
    std::unique_ptr<KDNode> right;
};

float squaredDistance(const Vec3& a, const Vec3& b) {
    float dx = a.x - b.x;
    float dy = a.y - b.y;
    float dz = a.z - b.z;

    return dx * dx + dy * dy + dz * dz;
}

bool compareX(const std::pair<uint32_t, Vec3>& a, const std::pair<uint32_t, Vec3>& b) {
    return a.second.x < b.second.x;
}

bool compareY(const std::pair<uint32_t, Vec3>& a, const std::pair<uint32_t, Vec3>& b) {
    return a.second.y < b.second.y;
}

bool compareZ(const std::pair<uint32_t, Vec3>& a, const std::pair<uint32_t, Vec3>& b) {
    return a.second.z < b.second.z;
}
```

Next, create the `SpatialSystem` class:

```cpp
class SpatialSystem : public SystemBase {
public:
    SpatialSystem(ECS& ecs) : ecs_(ecs) {}

    void SetEntityPosition(const uint32_t entityId, const Vec3& position) {
        points_.emplace_back(entityId, position);
        rootNode_ = buildKDTree(points_.begin(), points_.end(), 0);
    }

    std::vector<uint32_t> GetEntitiesInRadius(const Vec3& center, float radius) {
        std::vector<uint32_t> entitiesInRadius;
        searchKDTree(rootNode_.get(), center, radius * radius, 0, entitiesInRadius);
        return entitiesInRadius;
    }

private:
    using PointIterator = std::vector<std::pair<uint32_t, Vec3>>::iterator;

    std::unique_ptr<KDNode> buildKDTree(PointIterator start, PointIterator end, int depth) {
        if (start == end) {
            return nullptr;
        }

        int axis = depth % 3;
        PointIterator mid;

        if (axis == 0) {
            mid = start + (end - start) / 2;
            std::nth_element(start, mid, end, compareX);
        } else if (axis == 1) {
            mid = start + (end - start) / 2;
            std::nth_element(start, mid, end, compareY);
        } else {
            mid = start + (end - start) / 2;
            std::nth_element(start, mid, end, compareZ);
        }

        std::unique_ptr<KDNode> node = std::make_unique<KDNode>();
        node->entityId = mid->first;
        node->point = mid->second;
        node->left = buildKDTree(start, mid, depth + 1);
        node->right = buildKDTree(mid + 1, end, depth + 1);

        return node;
    }

    void searchKDTree(const KDNode* node, const Vec3& center, float squaredRadius, int depth, std::vector<uint32_t>& results) {
        if (!node) {
            return;
        }

        float squaredDist = squaredDistance(center, node->point);
        if (squaredDist <= squaredRadius) {
            results.push_back(node->entityId);
        }

        float planeDistance;
        int axis = depth % 3;

        if (axis == 0) {
            planeDistance = center.x - node->point.x;
        } else if (axis == 1) {
            planeDistance = center.y - node->point.y;
        } else {
            planeDistance = center.z - node->point.z;
        }

        if (-radius <= planeDistance) {
            searchKDTree(node->left.get(), center, squaredRadius, depth + 1, results);
        }

        if (planeDistance <= radius) {
            searchKDTree(node->right.get(), center, squaredRadius, depth + 1, results);
        }
    }

    ECS& ecs_;
    std::vector<std::pair<uint32_t, Vec3>> points_;
    std::unique_ptr<KDNode> rootNode_;
};
```

This implementation uses a k-d tree internally to store 3D points for each entity. The `SetEntityPosition` method adds new points to the vector, then rebuilds the k-d tree. The `GetEntitiesInRadius` method searches through the k-d tree and returns entities that lie within the given radius.

This solution is simplified and may not be suitable for larger or more complex projects. For better performance, consider using the k-d tree implementation provided by a library like [nanoflann](https://github.com/jlblancoc/nanoflann). Also, consider optimizing updates to the tree to avoid full rebuilds whenever positions are added, removed, or changed.

To optimize updates to the k-d tree, you can use the following techniques:

1. **Incremental tree updates**: Instead of rebuilding the entire k-d tree when a new point is added, perform incremental updates by inserting the new point directly into the tree. This is faster for smaller updates but may result in an unbalanced tree over time.

```cpp
void SetEntityPosition(const uint32_t entityId, const Vec3& position) {
    points_.push_back(std::make_pair(entityId, position));

    if (rootNode_ == nullptr) {
        rootNode_ = std::unique_ptr<KDNode>(new KDNode(entityId, position));
    } else {
        insertKDTree(rootNode_.get(), entityId, position, 0);
    }
}

void insertKDTree(KDNode* node, const uint32_t entityId, const Vec3& position, int depth) {
    int axis = depth % 3;
    bool insertLeft = (axis == 0 ? position.x : axis == 1 ? position.y : position.z) <
                      (axis == 0 ? node->point.x : axis == 1 ? node->point.y : node->point.z);

    if (insertLeft) {
        if (node->left) {
            insertKDTree(node->left.get(), entityId, position, depth + 1);
        } else {
            node->left = std::unique_ptr<KDNode>(new KDNode(entityId, position));
        }
    } else {
        if (node->right) {
            insertKDTree(node->right.get(), entityId, position, depth + 1);
        } else {
            node->right = std::unique_ptr<KDNode>(new KDNode(entityId, position));
        }
    }
}
```

2. **Rebalancing**: Occasionally rebalance the k-d tree to maintain its performance when searching or updating. One approach is to perform a rebuild or partial rebuild when the tree becomes significantly unbalanced (e.g., when the tree depth exceeds a certain threshold).

```cpp
void SetEntityPosition(const uint32_t entityId, const Vec3& position) {
    points_.push_back(std::make_pair(entityId, position));
    insertKDTree(rootNode_.get(), entityId, position, 0);

    // Rebalance the tree if depth exceeds the threshold, e.g. log2(N)
    if (treeDepth(rootNode_.get()) > std::log2(points_.size())) {
        rootNode_ = buildKDTree(points_.begin(), points_.end(), 0);
    }
}

int treeDepth(const KDNode* node) {
    if (!node) return 0;
    return 1 + std::max(treeDepth(node->left.get()), treeDepth(node->right.get()));
}
```

3. **Removing points**: When removing points or updating existing points, you can either modify the k-d tree in place or rebuild the tree to maintain balance.

```cpp
void RemoveEntityPosition(const uint32_t entityId) {
    // Remove point from the vector, then rebuild the k-d tree
    points_.erase(std::remove_if(points_.begin(), points_.end(), 
                 [entityId](const auto& pair) { return pair.first == entityId; }), 
                 points_.end());
    rootNode_ = buildKDTree(points_.begin(), points_.end(), 0);
}
```

Implementing these optimization techniques will allow for more efficient updates to the k-d tree structure, resulting in improved performance when inserting, deleting, or updating points. Note that the specific approach you choose will depend on your project requirements and how often updates are expected to occur.

