```c
#include <stdio.h>
#include <stdlib.h>

#define STREAM_SIZE 320

typedef struct Memory {
    int pageindex;
    struct Memory *next;
} Memory;

void LRU(int* page,int memoryCapacity){
   double hitrate = 0.0;
   Memory* top = NULL;
   Memory* bottom = NULL;
   int miss = 0;
   int count = 0;

  for(int i = 0; i < STREAM_SIZE; i++){ 
    Memory *curr = bottom;
    while (curr){
      if (page[i] == curr->pageindex ){
        break;
      }
      else {
        curr = curr->next;
      }
    }
    if (!curr){
      miss++;
      Memory *newNode = (Memory*)malloc(sizeof(Memory));
      if (newNode == NULL) {
        printf("内存分配不成功！\n");
        exit(1);
      }
      newNode->pageindex = page[i];
      newNode ->next = NULL;
      //add node into stack top
      if (bottom == NULL){
        bottom = top = newNode;
      }
      else {
        top -> next = newNode;
        top = newNode;
      }

      if (count == memoryCapacity){
        Memory* p = bottom;
        bottom = bottom ->next;
        free(p);
      }
      else {
        count++;
      }

    }
    else {
      //move curr to the top
      if (curr == bottom){
        bottom = bottom->next;
      }
      else{
        Memory* pre = bottom;
        while (pre->next != curr){
          pre = pre->next;
        }
        // This is correct
        pre->next = curr->next;
      }
      curr->next = NULL;
      top -> next = curr;
      top = curr;
    }
  }
  hitrate = 1 -((double) miss/320);
  printf("the hit rate of LRU is  %f\n",hitrate);
}

int main() {
    int page[STREAM_SIZE] = {0};  // Test with an array of zeros initially
    int memoryCapacity = 10;      // Test with a capacity of 10
    LRU(page, memoryCapacity);
    return 0;
}
