const turns = 2;
const verticesPerStrand = basePairsPerTurn * turns;

const vertices = [];
for (let strand = 0; strand < strands; strand++) {
  for (let i = 0; i < verticesPerStrand; i++) {
    const angle = Math.PI * 2 * (i / basePairsPerTurn) + (strand * Math.PI / strands);
    const z = i / verticesPerStrand;
    vertices.push([Math.cos(angle) * 0.25, Math.sin(angle) * 0.25, z]);
  }
}

const edges = [];
for (let strand = 0; strand < strands; strand++) {
  for (let i = 0; i < verticesPerStrand - 1; i++) {
    edges.push([i + strand * verticesPerStrand, i + strand * verticesPerStrand + 1]);
  }
  for (let i = 0; i < verticesPerStrand; i++) {
    edges.push([i, (i + basePairsPerTurn / 2) % verticesPerStrand + ((strand + 1) % strands) * verticesPerStrand]);
  }
}

