First, let's create a utility function for Slerp:

```js
function slerp(p0, p1, t) {
  let omega, cosOmega, sinOmega, k0, k1;
  cosOmega = dotProduct(p0, p1);

  if (cosOmega < 0) {
    cosOmega *= -1;
    p1 = p1.map(v => -v);
  }

  if (cosOmega > 0.9999) {
    k0 = 1 - t;
    k1 = t;
  } else {
    sinOmega = Math.sqrt(1 - cosOmega * cosOmega);
    omega = Math.atan2(sinOmega, cosOmega);
    k0 = Math.sin((1 - t) * omega) / sinOmega;
    k1 = Math.sin(t * omega) / sinOmega;
  }

  return p0.map((v, i) => k0 * v + k1 * p1[i]);
}
```

Then, we need utility functions for vector operations:

```js
function dotProduct(v1, v2) {
  return v1.reduce((sum, v, i) => sum + v * v2[i], 0);
}

function normalize(v) {
  const length = Math.sqrt(dotProduct(v, v));
  return v.map(el => el / length);
}
```

