#include <iostream>
#include <memory>
#include <unordered_map>

template <typename T>
class Component {
public:
    T* get() { return static_cast<T*>(this); }
};

class Position final : public Component<Position> {
public:
    Position(float x = 0, float y = 0) : x_(x), y_(y) {}

    float x() const { return x_; }
    void setX(float x) { x_ = x; }

    float y() const { return y_; }
    void setY(float y) { y_ = y; }
private:
    float x_, y_;
};

class Velocity final : public Component<Velocity> {
public:
    Velocity(float x = 0, float y = 0) : x_(x), y_(y) {}

    float x() const { return x_; }
    void setX(float x) { x_ = x; }

    float y() const { return y_; }
    void setY(float y) { y_ = y; }
private:
    float x_, y_;
};

using Entity = std::size_t;

class EntityManager {
public:
    EntityManager() : id_(0) {}

    Entity createEntity() {
        return id_++;
    }
private:
    Entity id_;
};

template <typename T>
class ComponentManager {
public:
    void addComponent(Entity e, const T& component) {
        components_[e] = component;
    }

    T* getComponent(Entity e) {
        auto it = components_.find(e);
        return it != components_.end() ? &(it->second) : nullptr;
    }

private:
    std::unordered_map<Entity, T> components_;
};

int main() {
    EntityManager entityManager;
    ComponentManager<Position> positionManager;
    ComponentManager<Velocity> velocityManager;

    Entity entity = entityManager.createEntity();
    Position pos(10, 20);
    positionManager.addComponent(entity, pos);

    Position* myPos = positionManager.getComponent(entity);

    if (myPos) {
        std::cout << "Entity(" << entity << ") position: (" << myPos->x() << "," << myPos->y() << ")\n";
    } else {
        std::cout << "Entity(" << entity << ") has no Position.\n";
    }

    Velocity* myVel = velocityManager.getComponent(entity);

    if (myVel) {
        std::cout << "Entity(" << entity << ") velocity: (" << myVel->x() << "," << myVel->y() << ")\n";
    } else {
        std::cout << "Entity(" << entity << ") has no Velocity.\n";
    }

    return 0;
}
```

This example provides a simple ECS structure consisting of an `EntityManager` and a `ComponentManager` for each component type (here `Position` and `Velocity`). The CRTP is used in the base `Component` class that has a `get()` method, which allows getting a pointer to the derived component type. This CRTP pattern essentially allows getting access to the derived class's members through the base class.

We create an `Entity` with a `Position` component and store it in the `positionManager`. At runtime, you can get the Position of an Entity and the Velocity of an Entity. Note that while this example uses a concrete implementation, you might want to write more flexible ECS with interfaces or template-based systems to handle other types of components, systems, and event handling.

