template<class C, typename... Args>
void ECS::TransitionComponentsBetweenArchetypes(const uint32_t entityId, Args&&... args) {
    Record& record = entityArchetypeMap[entityId];
    Archetype* oldArchetype = record.archetype;
    Archetype* newArchetype = GetArchetype(componentMasks[entityId]);

    // Index of the entity within the oldArchetype
    std::size_t entityIndex = std::distance(oldArchetype->entityIds.begin(), std::find(oldArchetype->entityIds.begin(), oldArchetype->entityIds.end(), entityId));

    // Move components from the oldArchetype to the newArchetype
    for (const auto& [componentTypeId, componentBase] : componentMap) {
        std::size_t oldIndex = oldArchetype->componentMask.ReturnArchetypeIndex(componentTypeId);
        std::size_t newIndex = newArchetype->componentMask.ReturnArchetypeIndex(componentTypeId);

        if (oldArchetype->componentMask.HasComponent(componentTypeId)) {
            // Move data from oldArchetype to newArchetype
            componentBase->MoveData(
                &oldArchetype->componentData[oldIndex][entityIndex * componentBase->GetSize()],
                &newArchetype->componentData[newIndex][record.index * componentBase->GetSize()]
            );
        }
    }

    // Finally, construct the new component into the new archetype
    C* newComponentPtr = AllocateNewComponent<C>(newArchetype, entityId);
    new (newComponentPtr) C(std::forward<Args>(args)...);
}

template<class C>
C* ECS::AllocateNewComponent(Archetype* archetype, const uint32_t entityId) {
    // Ensure enough space has been allocated for the new component in the new archetype
    std::size_t componentTypeId = Component<C>::GetTypeID();
    std::size_t componentSize = componentMap[componentTypeId]->GetSize();
    std::size_t componentIndex = archetype->componentMask.ReturnArchetypeIndex(componentTypeId);
    std::size_t newIndex = entityArchetypeMap[entityId].index;

    if (archetype->componentDataSize[componentIndex] < (newIndex + 1) * componentSize) {
        std::size_t newSize = (newIndex + 1) * componentSize;
        archetype->componentData[componentIndex].resize(newSize);
    }

    // Return the address where the new component can be constructed
    C* newComponentPtr = reinterpret_cast<C*>(&archetype->componentData[componentIndex][newIndex * componentSize]);
    return newComponentPtr;
}
