You can create a single HttpClient instance with a new custom handler for each request and reuse the same HttpClient instance by changing the handler.

Here's one way to accomplish this:

```csharp
public class CustomHttpClient
{
    private static HttpClient _client;
    private WinHttpHandler _handler;

    public CustomHttpClient()
    {
        if (_client == null)
        {
            _client = new HttpClient();
            _client.DefaultRequestHeaders.ExpectContinue = false;
        }
    }

    public async Task<string> Request(string url, WebProxy proxy, byte[]? post = null, CookieContainer? cookies = null, Dictionary<string, string?>? aHeaders = null)
    {
        var uri = new Uri(url);

        // Replace previous custom handler with new settings.
        _handler = new WinHttpHandler
        {
            WindowsProxyUsePolicy = WindowsProxyUsePolicy.UseCustomProxy,
            CookieUsePolicy = CookieUsePolicy.UseSpecifiedCookieContainer,
            Proxy = proxy,
            CookieContainer = cookies ?? new CookieContainer()
        };

        _client = new HttpClient(_handler, disposeHandler: true);

        // Set and send request.
        await SendRequest(uri, post, aHeaders).ConfigureAwait(false);

        try
        {
            using var response = await _client.GetAsync(uri).ConfigureAwait(false);
            return await response.Content.ReadAsStringAsync().ConfigureAwait(false);
        }
        catch (Exception e)
        {
            return e.Message;
        }
    }

    private Task SendRequest(Uri uri, byte[]? post, Dictionary<string, string?>? aHeaders)
    {
        _client.DefaultRequestHeaders.Host = uri.Host;
        _client.DefaultRequestHeaders.UserAgent.ParseAdd(UserAgent);

        var request = new HttpRequestMessage
        {
            RequestUri = uri,
            Method = post == null ? HttpMethod.Get : HttpMethod.Post,
        };

        if (aHeaders == null || aHeaders.Keys.All(k => k.ToLower() != "accept"))
            request.Headers.Accept.ParseAdd("text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9");
        if (aHeaders == null || aHeaders.Keys.All(k => k.ToLower() != "accept-encoding"))
            request.Headers.AcceptEncoding.ParseAdd("gzip, deflate, br");
        if (aHeaders == null || aHeaders.Keys.All(k => k.ToLower() != "accept-language"))
            request.Headers.AcceptLanguage.ParseAdd("en-US,en;q=0.9,ar;q=0.8");

        if (aHeaders != null)
            foreach (var header in aHeaders)
                request.Headers.TryAddWithoutValidation(header.Key, header.Value);

        return _client.SendAsync(request);
    }
}
```

