```cpp
template<class C, typename... Args>
C* ECS::AddComponent(const uint32_t entityId, Args&&... args) {
    auto newComponentID = Component<C>::GetTypeID();

    if (componentMasks[entityId].HasComponent(newComponentID)) {
        return nullptr; // Component already exists for the entity
    }

    componentMasks[entityId].AddComponent(newComponentID);
    Archetype* newArchetype = nullptr;
    C* newComponent = nullptr;

    Record& record = entityArchetypeMap[entityId];
    Archetype* oldArchetype = record.archetype;

    newArchetype = GetOrCreateArchetype(entityId);

    if (oldArchetype) {
        newComponent = MigrateEntityToArchetype(newArchetype, oldArchetype, entityId, std::forward<Args>(args)...);
    } else {
        newComponent = AddFirstComponentToEntity(newArchetype, entityId, newComponentID, record, std::forward<Args>(args)...);
    }

    return newComponent;
}

Archetype* ECS::GetOrCreateArchetype(const uint32_t entityId) {
    auto& newComponentMask = componentMasks[entityId];
    Archetype* newArchetype = GetArchetype(componentMasks[entityId]);
    return newArchetype;
}

template<class C, typename... Args>
C* ECS::MigrateEntityToArchetype(Archetype* newArchetype, Archetype* oldArchetype, const uint32_t entityId, Args&&... args) {
    auto newComponentMask = componentMasks[entityId];
    auto oldComponentMask = oldArchetype->componentMask;
    C* newComponent = nullptr;
    size_t j = 0;

    // Loop over each component bit
    for (size_t index = 0, i = 0; i < newComponentMask.GetBitsetMask().size() - 1; ++i) {
        if (newComponentMask.GetBitsetMask().test(i)) {
            const ComponentBase* const componentBase = componentMap[i];
            const std::size_t newComponentDataSize = componentBase->GetSize();

            // If the entity has this component in the old archetype
            if (oldComponentMask.HasComponent(i)) {
                TransferComponentData(componentBase, oldArchetype, newArchetype, index, j, entityId);
                ++j;
            }
            else {
                newComponent = InstantiateComponent<C>(newArchetype, entityId, newComponentDataSize, index, std::forward<Args>(args)...);
            }
            ++index;
        }
    }

    UpdateEntitiesInArchetypes(oldArchetype, newArchetype, entityId);

    return newComponent;
}

template<class C, typename... Args>
C* ECS::AddFirstComponentToEntity(Archetype* newArchetype, const uint32_t entityId, const uint32_t newComponentID, Record& record, Args&&... args) {
    const ComponentBase* const newComponentBase = componentMap[newComponentID];
    const std::size_t& newComponentDataSize = newComponentBase->GetSize();
    std::size_t currentSize = newArchetype->entityIds.size() * newComponentDataSize;
    std::size_t newSize = currentSize + newComponentDataSize;

    // Reallocate memory if necessary
    if (newSize > newArchetype->componentDataSize[0]) {
        Reallocate(newComponentBase, newComponentDataSize, newArchetype, 0);
    }

    C* newComponent = new (&newArchetype->componentData[0][currentSize]) C(std::forward<Args>(args)...);
    newArchetype->entityIds.push_back(entityId);
    record.index = newArchetype->entityIds.size() - 1;
    record.archetype = newArchetype;

    return newComponent;
}

template<class C, typename... Args>
C* ECS::InstantiateComponent(Archetype* newArchetype, const uint32_t entityId, const std::size_t componentDataSize, const size_t componentIndex, Args&&... args) {
    std::size_t currentSize = newArchetype->entityIds.size() * componentDataSize;
    return new (&newArchetype->componentData[componentIndex][currentSize]) C(std::forward<Args>(args)...);
}

void ECS::UpdateEntitiesInArchetypes(Archetype* oldArchetype, Archetype* newArchetype, const uint32_t entityId) {
    auto entityIndex = FindEntityIndex(oldArchetype, entityId);
    auto lastEntity = oldArchetype->entityIds.size() - 1;

    if (!oldArchetype->entityIds.empty() && entityIndex < oldArchetype->entityIds.size()) {
        oldArchetype->entityIds[entityIndex] = oldArchetype->entityIds[lastEntity];
        MoveAndSwapComponentData(oldArchetype, entityIndex, lastEntity);
        oldArchetype->entityIds.pop_back();
    }

    newArchetype->entityIds.push_back(entityId);
    entityArchetypeMap[entityId

].index = newArchetype->entityIds.size() - 1;
    entityArchetypeMap[entityId].archetype = newArchetype;
}

std::size_t ECS::FindEntityIndex(Archetype* archetype, const uint32_t entityId) {
    return std::find(
        archetype->entityIds.begin(),
        archetype->entityIds.end() - 1,
        entityId
    ) - archetype->entityIds.begin();
}

void ECS::MoveAndSwapComponentData(Archetype* archetype, const size_t fromIndex, const size_t toIndex) {
    auto componentMask = archetype->componentMask;

    for (std::size_t i = 0, index = 0; i < componentMask.GetBitsetMask().size() - 1; ++i) {
        if (componentMask.GetBitsetMask().test(i)) {
            const ComponentBase* const componentBase = componentMap[i];
            SwapComponentData(componentBase, archetype, index, fromIndex, toIndex);
            ++index;
        }
    }
}

void ECS::SwapComponentData(const ComponentBase* componentBase, Archetype* archetype, const size_t componentIndex, const size_t fromIndex, const size_t toIndex) {
    const std::size_t compSize = componentBase->GetSize();
    componentBase->MoveData(&archetype->componentData[componentIndex][fromIndex * compSize],
                            &archetype->componentData[componentIndex][toIndex * compSize]);
}

```

Yes, it's possible to combine the `AllocateAndAddComponent` and `TransferOrAddNewComponent` functions by modifying the `MigrateEntityToArchetype` function. You can add an 'if' condition inside the loop to check whether the entity has this component in the old archetype or not, then handle both situations accordingly.

Here's the combined version:

```cpp
template<class C, typename... Args>
C* ECS::MigrateEntityToArchetype(Archetype* newArchetype, Archetype* oldArchetype, const uint32_t entityId, Args&&... args) {
    auto newComponentMask = componentMasks[entityId];
    auto oldComponentMask = oldArchetype->componentMask;
    C* newComponent = nullptr;

    // Loop over each component bit
    for (size_t index = 0, i = 0; i < newComponentMask.GetBitsetMask().size() - 1; ++i) {
        if (newComponentMask.GetBitsetMask().test(i)) {
            const ComponentBase* const componentBase = componentMap[i];
            const std::size_t newComponentDataSize = componentBase->GetSize();

            // If the entity has this component in the old archetype
            if (oldComponentMask.HasComponent(i)) {
                size_t entityIndex = FindEntityIndex(oldArchetype, entityId);
                TransferComponentData(componentBase, oldArchetype, newArchetype, index, entityId, entityIndex);
            } else {
                std::size_t currentSize = newArchetype->entityIds.size() * newComponentDataSize;
                std::size_t newSize = currentSize + newComponentDataSize;

                // Reallocate memory if necessary
                if (newSize > newArchetype->componentDataSize[index]) {
                    Reallocate(componentBase, newComponentDataSize, newArchetype, index);
                }

                newComponent = InstantiateComponent<C>(newArchetype, entityId, newComponentDataSize, index, std::forward<Args>(args)...);
            }
            ++index;
        }
    }

    UpdateEntitiesInArchetypes(oldArchetype, newArchetype, entityId);

    return newComponent;
}
```

This way, you can handle both transferring a component and adding a new component within the same function, which makes the code more concise and easier to maintain.

