// Capture output from a command in a separate thread
use std::process::{Command, Stdio};
use std::io::{BufRead, BufReader};
use std::sync::mpsc::{channel, Receiver};
use std::thread;

fn main() {
    let (tx, rx) = channel();
    let mut child = Command::new("cargo")
        .args(&["build", "--quiet"])
        .stdout(Stdio::piped())
        .spawn()
        .expect("Failed to execute");

    let mut output = child.stdout.take().unwrap();
    let tx_clone = tx.clone();
    thread::spawn(move || {
         let reader = BufReader::new(output);

        for line in reader.lines() {
            tx_clone.send(line.unwrap()).unwrap();
        }
    });

    drop(tx);  // Close the channel after sending all lines
    for line in rx {
        println!("Build Results: {}", line);
    }
}
