fn pipe() -> std::io::Result<(File, File)> {
    let mut fds = [-1; 2];
    unsafe {
        libc::pipe(fds.as_mut_ptr());
        Ok((File::from_raw_fd(fds[0]), File::from_raw_fd(fds[1])))
    }
}
