    println!("Build Results: \n{}", build_results);
}
```

3. Solution using `std::process::Command` and `std::io::Read`

This solution reads the output in chunks using `std::io::Read`.

```rust
use std::process::{Command, Stdio};
use std::io::Read;

fn main() {
    let mut child = Command::new("cargo")
        .arg("build")
        .stdout(Stdio::piped())
        .spawn()
        .expect("Failed to execute 'cargo build'");

    let mut build_results = String::new();
    child.stdout.as_mut().unwrap().read_to_string(&mut build_results).unwrap();

    println!("Build Results: \n{}", build_results);
}
```

4. Solution using `std::thread` and `std::sync`

This solution reads the output in another thread and uses a `std::sync::mpsc` channel to send the output back.

```rust
use std::process::{Command, Stdio};
use std::io::Read;
use std::thread;
use std::sync::mpsc;

fn main() {
    let mut child = Command::new("cargo")
        .arg("build")
        .stdout(Stdio::piped())
        .spawn()
        .expect("Failed to execute 'cargo build'");

    let (tx, rx) = mpsc::channel();
    let stdout = child.stdout.take().unwrap();

    let read_thread = thread::spawn(move || {
        let mut buffer = String::new();
        let mut reader = std::io::BufReader::new(stdout);
        reader.read_to_string(&mut buffer).unwrap();
        buffer
    });

    let build_results = rx.recv().unwrap();
    println!("Build Results: \n{}", build_results);
}
```

5. Solution using `std::process::Command` with the `Stdio::inherit()` method

This solution uses the `Stdio::inherit()` method to inherit the parent process stdout.

