    std::size_t currentSize = toArch->entityIds.size() * compSize;

    compbase->MoveData(&fromArch->componentData[j][entityIndex * compSize],
        &toArch->componentData[i][currentSize]);

    compbase->DestroyData(&fromArch->componentData[j][entityIndex * compSize]);
}

#include "ComponentMask.h"

typedef unsigned char* ComponentData;
typedef std::vector<int> ArchetypeId;

struct Archetype
{
    ComponentMask componentMask;
    std::vector<ComponentData> componentData;
    std::vector<uint32_t> entityIds;
    std::vector<std::size_t> componentDataSize;
};

template<class C, typename... Args>
C* ECS::AddComponent(const uint32_t entityId, Args&&... args) {
    // 1. Get the component type ID and check if the component already exists for the entity
    auto newComponentID = GetComponentTypeID<C>();

    if (HasComponentAlready(entityId, newComponentID)) {
        return nullptr;
    }

    // 2. Update the component mask for the entity and get the new archetype
    componentMasks[entityId].AddComponent(newComponentID);
    Archetype* newArchetype = GetArchetype(componentMasks[entityId]);

    // 3. Get and store the record of the entity
    Record& record = entityArchetypeMap[entityId];
    Archetype* oldArchetype = record.archetype;

    C* newComponent = nullptr;

    // 4. If the entity has existing components, transfer or add the new component
    if (oldArchetype) {
        TransferOrAddNewComponent<C>(entityId, newArchetype, oldArchetype, std::forward<Args>(args)...);
    }
    // 5. If the entity has no existing components, allocate and add the new component
    else {
        newComponent = AllocateAndAddComponent<C>(newArchetype, std::forward<Args>(args)...);
    }

    // 6. Update the record and return the new component
    UpdateRecord(entityId, newArchetype, record);
    return newComponent;
}

template<class C>
uint32_t ECS::GetComponentTypeID() {
    auto newComponentID = Component<C>::GetTypeID();
    return newComponentID;
}

bool ECS::HasComponentAlready(const uint32_t entityId, uint32_t componentTypeID) {
    return componentMasks[entityId].HasComponent(componentTypeID);
}

template<class C, typename... Args>
void ECS::TransferOrAddNewComponent(const uint32_t entityId, Archetype* newArchetype, Archetype* oldArchetype, Args&&... args) {
    std::size_t entityIndex = GetEntityIndex(oldArchetype, entityId);
    TransferExistingComponents(entityIndex, oldArchetype, newArchetype);
    AddNewComponent<C>(entityIndex, oldArchetype, newArchetype, std::forward<Args>(args)...);
}

