package com.mindskip.xzs.controller.student;

import com.mindskip.xzs.base.BaseApiController;
import com.mindskip.xzs.base.RestResponse;
import com.mindskip.xzs.service.FileUpload;
import com.mindskip.xzs.service.UserService;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseBody;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.multipart.MultipartHttpServletRequest;

import javax.servlet.http.HttpServletRequest;

import java.io.IOException;
import java.io.InputStream;

@RestController("StudentUploadController")
@RequestMapping("/api/student/upload")
public class UploadController extends BaseApiController {
    // 注入 UserService 和 FileUpload 服务对象
    private final UserService userService;
    private final FileUpload fileUpload;

    @Autowired
    public UploadController(UserService userService, FileUpload fileUpload) {
        this.userService = userService;
        this.fileUpload = fileUpload;
    }

    // 处理上传图片的请求，返回上传图片后的文件路径
    @RequestMapping("/image")
    @ResponseBody
    public RestResponse questionUploadAndReadExcel(HttpServletRequest request) {
        // 将 HttpServletRequest 转换为 MultipartHttpServletRequest 获取上传的图片文件
        MultipartHttpServletRequest multipartHttpServletRequest = (MultipartHttpServletRequest) request;
        MultipartFile multipartFile = multipartHttpServletRequest.getFile("file");
        // 获取图片文件的大小和文件名
        long attachSize = multipartFile.getSize();
        String imgName = multipartFile.getOriginalFilename();
        try (InputStream inputStream = multipartFile.getInputStream()) {
            // 调用 FileUpload 服务的 uploadFile 方法上传图片
            String filePath = fileUpload.uploadFile(inputStream, attachSize, imgName);
            // 调用 UserService 服务的changePicture方法将图片路径更新到用户信息中
            userService.changePicture(getCurrentUser(), filePath);
            // 将上传图片后的文件路径封装成 RestResponse 并返回
