```javascript
// Generate a random number from a normal distribution with 'mean' and 'stdDev'
function randomNormal(mean, stdDev) {
  let u1 = Math.random();
  let u2 = Math.random();
  let z0 = Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2);
  return z0 * stdDev + mean;
}

// Genetic algorithm implementation for getDeviation and cpDist functions
function geneticAlgorithm(targetFunction, mean, stdDev, generations, threshold) {
  const populationSize = 100;
  const eliteSize = Math.floor(populationSize * 0.3);
  const mutationRange = { start: 0.05, end: 0.01 };
  const pDecrement = (mutationRange.start - mutationRange.end) / generations;

  // Create an initial population
  let population = Array(populationSize).fill(null).map(() => randomNormal(mean, stdDev));

  for (let g = 0; g < generations; g++) {
    // Evaluate the population
    let evaluationScores = population.map(value => targetFunction(value));

    // Check for early stopping based on evaluation score threshold
    let averageScore = evaluationScores.reduce((a, b) => a + b, 0) / evaluationScores.length;
    if (averageScore <= threshold) {
      break;
    }

    // Select the top 30% based on evaluation scores
    let eliteIndices = evaluationScores
      .map((value, index) => ({ value, index }))
      .sort((a, b) => b.value - a.value) // descending order
      .slice(0, eliteSize)
      .map(entry => entry.index);

    // Generate 30 new values from the elite individuals
    let newPopulation = eliteIndices.map(index => randomNormal(population[index], stdDev));

    // Generate 70 new values by recombination (crossover)
    for (let i = 0; i < populationSize - eliteSize; i++) {
      let parent1 = population[Math.floor(Math.random() * population.length)];
      let parent2 = population[Math.floor(Math.random() * population.length)];
      let child = (parent1 + parent2) / 2;
      newPopulation.push(child);
    }

    // Mutate the new population (except the elite)
    for (let i = eliteSize; i < populationSize; i++) {
      newPopulation[i] += randomNormal(0, mutationRange.start - g * pDecrement);
    }

    population = newPopulation;
  }

  // Return the best individual (minimum score)
  let bestIndex = evaluationScores.reduce((bestIndex, value, index) => (value < evaluationScores[bestIndex] ? index : bestIndex), 0);
  return population[bestIndex];
}

