const int ledPins[] = {0, 1, 2, 3, 4, 5, 6, 7};
const int buttonPin = 8;
const int flashingInterval = 500; // in milliseconds

bool flashing = false;
bool state = false;

Ticker timer;

void setup() {
  for (int i = 0; i < 8; i++) {
    pinMode(ledPins[i], OUTPUT);
  }
  pinMode(buttonPin, INPUT_PULLUP);

  timer.attach_ms(flashingInterval, toggleLEDs);
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {
    flashing = !flashing;
    delay(300); // To avoid button debounce
  }
}

void toggleLEDs() {
  if (!flashing) {
    return;
  }

  state = !state;

  for (int i = 0; i < 4; i++) {
    digitalWrite(ledPins[i], state);
  }

  for (int i = 4; i < 8; i++) {
    digitalWrite(ledPins[i], !state);
  }
}
