import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.channels.actor

class AccountSafe8 {
    private val actor = CoroutineScope(Dispatchers.IO).accountActor()

    suspend fun modify(difference: Double) {
        actor.send(IncOperation(difference))
    }

    suspend fun get(): Double {
        val response = CompletableDeferred<Double>()
        actor.send(GetOperation(response))
        return response.await()
    }


    // Message types for counterActor
    sealed class AccountMsg
    class IncOperation(val difference: Double) : AccountMsg() // one-way message to increment counter
    class GetOperation(val response: CompletableDeferred<Double>) : AccountMsg() // a request with reply

    // This function launches a new counter actor
    private fun CoroutineScope.accountActor() = actor<AccountMsg> {
        var balance = 0.0 // actor state
        for (msg in channel) { // iterate over incoming messages
            when (msg) {
                is IncOperation -> balance += msg.difference
                is GetOperation -> msg.response.complete(balance)
            }
        }
    }

}

