```cpp
class ComponentDataHandler {
public:
    static void TransferComponentData(const ComponentBase* componentBase, Archetype* fromArch, Archetype* toArch, size_t fromIndex, size_t toIndex) {
        std::size_t componentDataSize = componentBase->GetSize();
        std::size_t currentSize = toArch->entityIds.size() * componentDataSize;

        componentBase->MoveData(&fromArch->componentData[fromIndex], &toArch->componentData[toIndex]);
        componentBase->DestroyData(&fromArch->componentData[fromIndex]);
    }

    static void SwapComponentData(const ComponentBase* componentBase, Archetype* arch, size_t index, size_t lastEntityIndex, size_t entityIndex) {
        std::size_t componentSize = componentBase->GetSize();

        componentBase->MoveData(&arch->componentData[index] + lastEntityIndex * componentSize, &arch->componentData[index] + entityIndex * componentSize);
        componentBase->DestroyData(&arch->componentData[index] + lastEntityIndex * componentSize);
    }

    static void RemoveAndAllocateComponentData(const ComponentBase* componentBase, Archetype* fromArchetype, Archetype* toArchetype, size_t fromIndex, size_t toIndex, size_t lastEntityIndex, size_t entityIndex) {
        std::size_t componentDataSize = componentBase->GetSize();
        size_t currentSize = toArchetype->entityIds.size() * componentDataSize;

        componentBase->MoveData(&fromArchetype->componentData[fromIndex] + entityIndex * componentDataSize, &toArchetype->componentData[toIndex] + currentSize);

        if (entityIndex != lastEntityIndex) {
            componentBase->MoveData(&fromArchetype->componentData[fromIndex] + lastEntityIndex * componentDataSize, &fromArchetype->componentData[fromIndex] + entityIndex * componentDataSize);
        }

        componentBase->DestroyData(&fromArchetype->componentData[fromIndex] + lastEntityIndex * componentDataSize);
    }
};
```

