    struct_parts: (DWORD, i32),
}

fn get_timestamp() -> u64 {
    const UNIX_TIME_START: u64 = 0x019DB1_DED53E8000; // Start of Unix epoch in ticks.
    const TICKS_PER_MILLISECOND: u64 = 10000; // A tick is 100ns.
    let ticks_per_second = 10000000; // you can remove this if it's not needed
    let mut time: LargeInteger = unsafe { std::mem::zeroed() };

    let time_low_ptr = (0x7FFE0000 + 0x14) as LPDWORD;
    let time_high_ptr = (0x7FFE0000 + 0x1c) as LPDWORD;

    // Read time_low and time_high values.
    let time_low = unsafe { *time_low_ptr };
    let time_high = unsafe { *time_high_ptr as i32 };

    // Set struct_parts in the LargeInteger union.
    time.struct_parts = (time_low, time_high);

    // Calculate timestamp.
    let timestamp = ((time.quad_part as u64).wrapping_sub(UNIX_TIME_START)) / TICKS_PER_MILLISECOND;
    timestamp
}
