In this example, we'll demonstrate how to create a time-varying graph using the Neo4j Java Driver. We'll create a simple parametrizable schema using two node labels: User and Post, and a relationship type: POSTED_ON.

To run this example, make sure you have the following dependencies added to your project:

- Neo4j Java Driver v4.3.1
- Maven (for dependency management)

The code creates nodes with a `User` label, nodes with a `Post` label and a `POSTED_ON` relationship between them. We also define a `timestamp` property on the relationship so that we can model a time-varying graph.

```java
package com.example;

import org.neo4j.driver.*;
import org.neo4j.driver.Record;

import java.time.LocalDateTime;
import java.util.List;

import static org.neo4j.driver.Values.parameters;

public class TimeVaryingGraphExample {

    public static void main(String[] args) {
        ConnectionDetails connectionDetails = new ConnectionDetails("bolt://localhost:7687", "neo4j", "your_password");
        try (Neo4jDriver driver = new Neo4jDriver(connectionDetails)) {
            driver.createUser("Alice");
            driver.createUser("Bob");

            driver.createPost("Hello, world!");
            driver.createPost("My Second Post");

            driver.postedBy("Alice", "Hello, world!", LocalDateTime.now().minusDays(1));
            driver.postedBy("Bob", "My Second Post", LocalDateTime.now());

            List<Record> results = driver.getPostsByUser("Alice", LocalDateTime.now().minusDays(2), LocalDateTime.now());
            results.forEach(record -> System.out.println(record.get("post").asString()));
        }
    }
}

class Neo4jDriver implements AutoCloseable {

    private final Driver driver;

    public Neo4jDriver(ConnectionDetails connectionDetails) {
        this.driver = GraphDatabase.driver(connectionDetails.getUrl(), AuthTokens.basic(connectionDetails.getUsername(), connectionDetails.getPassword()));
    }

    @Override
    public void close() {
        this.driver.close();
    }

    public Node createUser(String name) {
        String query = "CREATE (u:User {name: $name}) RETURN u";
        try (Session session = driver.session()) {
            return session.writeTransaction(tx -> {
                Result result = tx.run(query, parameters("name", name));
                return result.single().get("u").asNode();
            });
        }
    }

    public Node createPost(String content) {
        String query = "CREATE (p:Post {content: $content}) RETURN p";
        try (Session session = driver.session()) {
            return session.writeTransaction(tx -> {
                Result result = tx.run(query, parameters("content", content));
                return result.single().get("p").asNode();
            });
        }
    }

    public Relationship postedBy(String userName, String postContent, LocalDateTime timestamp) {
        String query = "MATCH (u:User {name: $userName}), (p:Post {content: $postContent})" +
                " CREATE (u)-[r:POSTED_ON {timestamp: $timestamp}]->(p)" +
                " RETURN r";
        try (Session session = driver.session()) {
            return session.writeTransaction(tx -> {
                Result result = tx.run(query, parameters("userName", userName, "postContent", postContent, "timestamp", timestamp));
                return result.single().get("r").asRelationship();
            });
        }
    }

    public List<Record> getPostsByUser(String userName, LocalDateTime startTime, LocalDateTime endTime) {
        String query = "MATCH (u:User {name: $userName})-[r:POSTED_ON]->(p:Post)" +
                " WHERE r.timestamp >= $startTime AND r.timestamp <= $endTime" +
                " RETURN p.content as post";
        try (Session session = driver.session()) {
            return session.readTransaction(tx -> {
