Here's an example of a Neo4j Java application for an SCD2 time-varying graph with parameterizable schema and varying properties in relationships:

```java
import org.neo4j.driver.*;

import java.time.LocalDateTime;

public class SCD2GraphExample {

    public static void main(String[] args) {
        Config config = Config.builder().withoutEncryption().build();

        try (Driver driver = GraphDatabase.driver("bolt://localhost:7687", AuthTokens.basic("username", "password"), config)) {
            try (Session session = driver.session()) {

                // Set up schema
                setSchema(session);

                // Add data
                LocalDateTime time1 = LocalDateTime.now();
                addFriendship(session, "Alice", "Bob", "friend", time1);
                LocalDateTime time2 = LocalDateTime.now().plusDays(1);
                addFriendship(session, "Alice", "Bob", "close friend", time2);

                // Query time-varying graph
                LocalDateTime queryTime = LocalDateTime.now().plusHours(12);
                System.out.println(getFriendshipsSCD2(session, queryTime));

            }
        }
    }

    private static void setSchema(Session session) {
        String schema = "CALL db.createLabel($label) YIELD label "
                      + "RETURN label";
        session.run(schema, Params.parameters("label", "Person"));
    }

    private static void addFriendship(Session session, String person1, String person2, String relationshipType, LocalDateTime time) {
        String createPerson1 = "MERGE (p:Person {name: $name})";
        session.run(createPerson1, Params.parameters("name", person1));
        session.run(createPerson1, Params.parameters("name", person2));

        String createRelationship = "MATCH (a:Person {name: $name1}), (b:Person {name: $name2}) "
                                  + "MERGE (a)-[r:FRIENDS {time_start: $time_start, time_end: $time_end, type: $type}]->(b)";
        session.run(createRelationship,
                    Params.parameters("name1", person1, "name2", person2, "time_start", time.toString(), "time_end", "9999-12-31T23:59:59", "type", relationshipType));
    }

    private static Result getFriendshipsSCD2(Session session, LocalDateTime time) {
        String query = "MATCH (a:Person)-[r:FRIENDS]->(b:Person) "
                     + "WHERE r.time_start <= $time AND $time <= r.time_end "
                     + "RETURN a.name AS person1, b.name AS person2, r.type, r.time_start, r.time_end";
        return session.run(query, Params.parameters("time", time.toString()));
    }
}
```

This example creates an SCD2 time-varying graph using a "FRIENDS" relationship with "time_start" and "time_end" properties to store the time range of relationships and a "type" property to store the varying relationship type between two nodes with the "Person" label. The addFriendship method is responsible for creating new relationships with the specified time and type properties, and the getFriendshipsSCD2 method queries the graph for relationships valid during the provided time. You can customize the schema, node labels, relationship types, and properties based on your application requirements.

