const express = require("express");
const { graphqlHTTP } = require("express-graphql");
const { buildSchema } = require("graphql");
const { PubSub } = require("graphql-subscriptions");
const { SubscriptionServer } = require("subscriptions-transport-ws");
const { execute, subscribe } = require("graphql");

const pubsub = new PubSub();

const schema = buildSchema(`
  type Query {
    hello: String
  }

  type Subscription {
    count: Int
  }
`);

const root = {
  hello: () => "Hello world!",
};

const Subscription = {
  count: {
    subscribe: () => pubsub.asyncIterator("count"),
  },
};

const app = express();

app.use(
  "/graphql",
  graphqlHTTP({
    schema,
    rootValue: { ...root, Subscription },
    graphiql: true,
  })
);

const server = app.listen(4000, () => {
  console.log("Running a GraphQL API server at http://localhost:4000/graphql");
});

SubscriptionServer.create(
  {
    schema,
    execute,
    subscribe,
    onConnect: () => console.log("Client connected to subscription server"),
    onDisconnect: () => console.log("Client disconnected from subscription server"),
  },
  {
    server,
    path: "/subscriptions",
  }
);

setInterval(() => {
  pubsub.publish("count", { count: Math.floor(Math.random() * 10) });
}, 1000);
```

Клиентский код остается без изменений. Теперь ваш сервер успешно обрабатывает запросы подписки, и ваш клиентский код должен работать без ошибок.

{
  message: 'Subscription field must return Async Iterable. Received: 
undefined.'
}

Приношу извинения за путаницу. Вам потребуется небольшое изменение в схеме и в подписках. Вам необходимо определить поле `count`, предоставленное в типе `Subscription`, в объекте `Subscription`, а не в объекте `root`.

Вот обновленный код:

1. В схеме замените `count: Int` на `count: Count!`:

```javascript
const schema = buildSchema(`
  type Query {
    hello: String
  }

  type Count {
    value: Int
  }

  type Subscription {
    count: Count!
  }
`);
```

2. Создайте новый объект `Subscription`:

```javascript
const Subscription = {
  count: {
    subscribe: () => pubsub.asyncIterator('count'),
  },
};
```

3. Обновите `rootValue` аргумент в функции `graphqlHTTP`:

```javascript
app.use('/graphql', graphqlHTTP({
  schema,
  rootValue: { ...root, Subscription },
  graphiql: true,
}));
```

4. Измените параметр `setInterval`, чтобы публиковать объект `Count` вместо простого `Int`:

```javascript
setInterval(() => {
  pubsub.publish('count', { count: { value: Math.floor(Math.random() * 10) } });
}, 1000);
```

Помимо этого, давайте также уточним запрос подписки в вашем клиентском коде:

```javascript
client.request({
  query: `
    subscription {
      count {
        value
      }
    }
  `,
}).subscribe({
  next: (data) => console.log(data),
  error: (error) => console.error(error),
});
```

Теперь сервер должен работать корректно с подписками. Обратите внимание, что теперь мы отправляем и получаем объекты `Count` (содержащие поле `value`), а не просто числа.

