To implement UCS (Uniform Cost Search), we can use a priority queue to keep track of the cells to visit. The priority queue will be sorted by the cost of visiting each cell, with lower costs being prioritized. 

Here's an implementation of the UCS algorithm as a new method in the `Maze` class:

```java
public List<int[]> findShortestPath(int startRow, int startCol, int endRow, int endCol) {
    PriorityQueue<int[]> queue = new PriorityQueue<>(Comparator.comparingInt(a -> a[2])); // priority queue sorted by cost
    boolean[][] visited = new boolean[rows][cols]; // keep track of visited cells
    int[][] cameFrom = new int[rows][cols]; // keep track of the parent of each cell in the shortest path
    int[][] costSoFar = new int[rows][cols]; // keep track of the cost of the shortest path to each cell
    queue.add(new int[]{startRow, startCol, 0}); // add the start cell with cost 0
    cameFrom[startRow][startCol] = -1; // mark the start cell as the root of the path
    costSoFar[startRow][startCol] = 0; // set the cost of the start cell to 0

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int row = current[0];
        int col = current[1];
        int cost = current[2];
        if (row == endRow && col == endCol) { // exit if we found the end cell
            break;
        }
        if (visited[row][col]) { // skip visited cells
            continue;
        }
        visited[row][col] = true; // mark the cell as visited
        List<int[]> neighbors = getNeighbors(row, col);
        for (int[] neighbor : neighbors) {
            int neighborRow = neighbor[0];
            int neighborCol = neighbor[1];
            int neighborCost = maze[neighborRow][neighborCol] == 1 ? 1 : 2; // cost of visiting the neighbor
            int totalCost = cost + neighborCost; // total cost of the path to the neighbor
            if (!visited[neighborRow][neighborCol] || totalCost < costSoFar[neighborRow][neighborCol]) {
                cameFrom[neighborRow][neighborCol] = row * cols + col; // encode the parent as a single integer
                costSoFar[neighborRow][neighborCol] = totalCost;
                queue.add(new int[]{neighborRow, neighborCol, totalCost});
            }
        }
    }

    List<int[]> path = new ArrayList<>();
    int currentRow = endRow;
    int currentCol = endCol;
    while (currentRow != startRow || currentCol != startCol) {
        path.add(0, new int[]{currentRow, currentCol});
        int parent = cameFrom[currentRow][currentCol];
        currentRow = parent / cols;
        currentCol = parent % cols;
    }
    path.add(0, new int[]{startRow, startCol});

    return path;
}

private List<int[]> getNeighbors(int row, int col) {
    List<int[]> neighbors = new ArrayList<>();
    if (row > 0 && maze[row-1][col] != -1) { // top neighbor
        neighbors.add(new int[]{row-1, col});
    }
    if (row < rows-1 && maze[row+1][col] != -1) { // bottom neighbor
        neighbors.add(new int[]{row+1, col});
    }
    if (col > 0 && maze[row][col-1] != -1) { // left neighbor
        neighbors.add(new int[]{row, col-1});
    }
    if (col < cols-1 && maze[row][col+1] != -1) { // right neighbor
        neighbors.add(new int[]{row, col+1});
    }
    return neighbors;
}
```

