    private void saveImageToStorage(Bitmap bitmap) {
        try {
// создание файла для сохранения изображения
            File storageDir = getActivity().getExternalFilesDir(Environment.DIRECTORY_PICTURES);
            File imageFile = File.createTempFile(
                    "profile_picture_", ".jpg",
            storageDir);

// сохранение изображения в файл
            FileOutputStream out = new FileOutputStream(imageFile);
            bitmap.compress(Bitmap.CompressFormat.JPEG, 100, out);
            out.flush();
            out.close();

// сохранение пути к файлу в SharedPreferences
            // создание круглого Bitmap
            Bitmap circleBitmap = Bitmap.createBitmap(bitmap.getWidth(), bitmap.getHeight(), Bitmap.Config.ARGB_8888);
            BitmapShader shader = new BitmapShader(bitmap, BitmapShader.TileMode.CLAMP, BitmapShader.TileMode.CLAMP);
            Paint paint = new Paint();
            paint.setShader(shader);
            Canvas c = new Canvas(circleBitmap);
            c.drawCircle(bitmap.getWidth()/2, bitmap.getHeight()/2, bitmap.getWidth()/2, paint);

// сохранение круглого изображения в SharedPreferences
            ByteArrayOutputStream stream = new ByteArrayOutputStream();
            circleBitmap.compress(Bitmap.CompressFormat.PNG, 100, stream);
            byte[] byteArray = stream.toByteArray();
            String encodedString = Base64.encodeToString(byteArray, Base64.DEFAULT);
            SharedPreferences sharedPreferences = getActivity().getSharedPreferences("myPrefs_profile", Context.MODE_PRIVATE);
            SharedPreferences.Editor editor = sharedPreferences.edit();
            editor.putString("profile_picture_base64", encodedString);
            editor.apply();

// установка круглого изображения на ImageView
            ImageView imageViewProfile = getView().findViewById(R.id.imageButtonProfile);
            imageViewProfile.setImageBitmap(circleBitmap);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

Понимаю, спасибо за уточнение задачи. В данном случае необходимо изменить код метода "onActivityResult", чтобы сохраняемое изображение было растянуто на весь ImageView.

Вместо создания круглого Bitmap и установки его в качестве изображения в ImageView, можно просто сохранить полученное Bitmap в файловую систему и установить его в качестве исходного изображения в ImageView, установив атрибут "android:scaleType" равным "centerCrop". Это позволит растянуть изображение на весь ImageView без искажений.

Ниже приведен измененный код метода "onActivityResult":

```java
@Override
public void onActivityResult(int requestCode, int resultCode, @Nullable Intent data) {
    super.onActivityResult(requestCode, resultCode, data);
    if (requestCode == 1 && resultCode == RESULT_OK && data != null && data.getData() != null) {
        // получение выбранного изображения
        Uri imageUri = data.getData();

        try {
            // конвертация изображения в Bitmap
            Bitmap bitmap = MediaStore.Images.Media.getBitmap(getActivity().getContentResolver(), imageUri);

            // сохранение изображения в локальном хранилище
            saveImageToStorage(bitmap);

            // отображение изображения на месте круглой иконки
            ImageView imageViewProfile = getActivity().findViewById(R.id.imageButtonProfile);
            imageViewProfile.setScaleType(ImageView.ScaleType.CENTER_CROP);
            imageViewProfile.setImageBitmap(bitmap);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

Теперь выбранное изображение будет растягиваться на всю площадь ImageView, полностью заполняя его.

Чтобы сохраняемое изображение было сразу круглым, необходимо изменить код метода "onActivityResult" таким образом, чтобы изображение сохранялось уже в круглом виде.

Вместо сохранения прямоугольного изображения bitmap в файловую систему, нужно сначала создать круглое изображение circleBitmap, а затем сохранить его в файловую систему. Круглое изображение отображается на месте круглой иконки ImageView, а исходное прямоугольное изображение игнорируется.

Ниже приведен код метода "onActivityResult" с изменениями, которые позволят сохранять картинку сразу в круглом виде:

```java
@Override
public void onActivityResult(int requestCode, int resultCode, @Nullable Intent data) {
    super.onActivityResult(requestCode, resultCode, data);
    if(requestCode == 1 && resultCode == RESULT_OK && data != null && data.getData() != null) {
        // получение выбранного изображения
        Uri imageUri = data.getData();

        try {
            // конвертация изображения в Bitmap
            Bitmap bitmap = MediaStore.Images.Media.getBitmap(getActivity().getContentResolver(), imageUri);

            // создание круглого Bitmap
            Bitmap circleBitmap = Bitmap.createBitmap(bitmap.getWidth(), bitmap.getHeight(), Bitmap.Config.ARGB_8888);
            BitmapShader shader = new BitmapShader(bitmap, BitmapShader.TileMode.CLAMP, BitmapShader.TileMode.CLAMP);
            Paint paint = new Paint();
            paint.setShader(shader);
            Canvas c = new Canvas(circleBitmap);
            c.drawCircle(bitmap.getWidth()/2, bitmap.getHeight()/2, bitmap.getWidth()/2, paint);

            // сохранение круглого изображения в файл
            saveImageToStorage(circleBitmap);

            // отображение круглого изображения на месте круглой иконки
            ImageView imageViewProfile = getView().findViewById(R.id.imageButtonProfile);
            imageViewProfile.setImageBitmap(circleBitmap);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

Теперь после выбора изображения оно сразу же сохраняется как круглое изображение и отображается на месте круглой иконки.

