                            buffv = elements[j].value;
                            buffp = elements[j].priority;
                            elements[j].value = elements[j - 1].value;
                            elements[j].priority = elements[j - 1].priority;
                            elements[j - 1].value = buffv;
                            elements[j - 1].priority = buffp;
                            flag = 1;
                        }
                    }
                }
            }
        }
    }
    Element wthdrw(int index) {
        return elements[index];
    }
    Element unqueue() {
        int highestindex = highestpriority();
        Element result = elements[highestindex];
        if (size == 0) {
            cout << "Очередь пустая\n";
            return result;
        }
        for (int i = highestindex; i < size - 1; i++) {
            elements[i] = elements[i + 1];
        }
        size--;
        return result;
    }

    bool isclear() {
        return size == 0;
    }

    int getSize() {
        return size;
    }
};
int main() {
    setlocale(LC_ALL, "rus");
    queue queue1;
    queue1.enqueue(1, 10);
    queue1.enqueue(5, 30);
    queue1.enqueue(5, 20);
    queue1.enqueue(1, 40);
    queue1.enqueue(5, 25);
    queue1.enqueue(3, 50);
    for (int i = 0; i < queue1.getSize(); i++) {
        cout << "Элемент под индексом " << i + 1 << " имеет значение " << queue1.wthdrw(i).value << " и приоритет "
<< queue1.wthdrw(i).priority << endl;
    }
    cout << endl;
    while (!queue1.isclear()) {
