public class BoardParser {
    private String[][] board;
    public BoardParser(String[][] board) {
        this.board = board;
    }

    public Tile[][] parse() {
        int rows = board.length;
        int cols = board[0].length;
        Tile[][] parsedBoard = new Tile[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                String tile = board[i][j];
                char lastCharacter = Character.toLowerCase(tile.charAt(tile.length() - 1));
                Letter.Position position = new Letter.Position(i, j);
                boolean hasGem = false;
                int letterMultiplier = 1, wordMultiplier = 1;

                if (tile.contains("*")) {
                    hasGem = true;
                } else if (tile.contains("&")) {
                    wordMultiplier = 2;
                } else if (tile.contains("2")) {
                    letterMultiplier = 2;
                } else if (tile.contains("3")) {
                    letterMultiplier = 3;
                }
                parsedBoard[i][j] = new Tile(new Letter(lastCharacter, position, hasGem, letterMultiplier,
                        wordMultiplier));
            }
        }
        return parsedBoard;
    }


    public void setBoard(String[][] board) {
        this.board = board;
    }

    public String[][] getBoard() {
        return board;
    }
}
