public class Word {
    private final List<Letter> word;
    private static final int LONG_WORD_BONUS = 10;

    public Word() {
        this(new ArrayList<>());
    }

    public Word(Word other) {
        word = new ArrayList<>();
        for (Letter l : other.word) {
            word.add(l.copy());
        }
    }

    public Word(List<Letter> word) {
        this.word = word;
    }

    public static int getLongWordBonus() {
        return LONG_WORD_BONUS;
    }

    public Word append(Letter letter) {
        word.add(letter);
        return this;
    }

    public Word pop() {
        word.remove(word.size() - 1);
        return this;
    }

    public String getWord() {
        StringBuilder sb = new StringBuilder();
        for (Letter l : word) {
            sb.append(l.getLetter());
        }
        return sb.toString();
    }

    public Letter getLetterAt(int i) {
        return word.get(i);
    }

    public List<Letter> getLetters() {
        return word;
    }

    public int getPoints() {
        int points = 0;
        for (Letter l : word) {
            points += l.getValue();
        }
        points *= getMultiplier();
        if (isLongWord()) points += LONG_WORD_BONUS;
        return points;
    }

    public int getGemCount() {
        int cnt = 0;
        for (Letter l : word) {
            if (l.hasGem()) cnt++;
        }
        return cnt;
    }

    public int getResource(Resource type) {
        return switch (type) {
            case POINTS -> getPoints();
            case GEMS -> getGemCount();
        };
    }

    public int getMultiplier() {
        for (Letter l : word) {
            if (l.hasWordMultiplier()) return l.getWordMultiplier();
        }
        return 1;
    }

    public boolean hasMultiplier() {
        return getMultiplier() > 1;
    }

    public boolean isLongWord() {
        return word.size() > 6;
    }

    public Word copy() {
        return new Word(this);
    }

    @Override
    public String toString() {
        return getWord();
    }
}

