import com.dootz.spellcastsolvergui.model.board.Board;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class WordResult {
    private final Board board;
    private final List<Word> unsortedWords;
    private final List<Word> mostPointWords;
    private final List<Word> mostGemWords;
    public static final int SUBSCRIPT_ZERO = 8320;
    public static final char[] SUPERSCRIPTS = {'ᵃ', 'ᵇ', 'ᶜ', 'ᵈ', 'ᵉ', 'ᶠ', 'ᵍ', 'ʰ', 'ⁱ', 'ʲ', 'ᵏ', 'ˡ', 'ᵐ', 'ⁿ',
            'ᵒ', 'ᵖ', 'q', 'ʳ', 'ˢ', 'ᵗ', 'ᵘ', 'ᵛ', 'ʷ', 'ˣ', 'ʸ', 'ᶻ'};

    public WordResult(Board board, List<Word> words) {
        this.board = board;
        unsortedWords = words;

        mostPointWords = new ArrayList<>(List.copyOf(unsortedWords));
        mostGemWords = new ArrayList<>(List.copyOf(unsortedWords));

        mostPointWords.sort(Comparator.comparing(Word::getPoints).reversed());
        mostGemWords.sort(Comparator.comparing(Word::getGemCount).reversed());
    }

    public List<Word> getWordsBy(Resource type) {
        return switch (type) {
            case POINTS -> mostPointWords;
            case GEMS -> mostGemWords;
        };
    }

    public Word getWordBy(Resource type, int index) {
        return getWordsBy(type).get(index);
    }

    public List<Word> getFirstNElementsOf(Resource type, int elements) {
        return getWordsBy(type).stream().limit(elements).toList();
    }

    public String[][] getNthResultMatrixOf(Resource type, int n) {
        String[][] arr = board.toStringArray();
        Word word = getWordsBy(type).get(n);

        for (int i = 0; i < word.getLetters().size(); i++) {
            int r = word.getLetterAt(i).getPosition().getR();
            int c = word.getLetterAt(i).getPosition().getC();
            arr[r][c] = String.valueOf(word.getLetterAt(i).getLetter());
            if (word.getLetterAt(i).isSwapped()) arr[r][c] += getSuperScript(board.at(r, c).getLetter().getLetter());
            arr[r][c] += getSubscript(i + 1);
        }
        return arr;
    }

    public void printNthResultMatrixOf(Resource type, int n) {
        String[][] arr = getNthResultMatrixOf(type, n);
        Word word = getWordBy(type, n);

        System.out.printf("%d: %s - %d %s\n", n + 1, word.getWord(), word.getResource(type), type);
        for (String[] row : arr) {
            for (String item : row) {
                System.out.printf("%-4s", item);
            }
            System.out.println();
        }

        System.out.println(formatPointBreakdown(word));
    }

    private String formatPointBreakdown(Word word) {
        StringBuilder sb = new StringBuilder();

        for (Letter l : word.getLetters()) {
            if (l.isSwapped()) {
                sb.append("?");
            }
            if (l.hasWordMultiplier()) {
                sb.append("&");
            }
            if (l.hasLetterMultiplier()) {
                sb.append("[")
                        .append(l.getLetter())
                        .append(getSubscript(l.getBaseValue()))
                        .append("]")
                        .append(getSubscript(l.getLetterMultiplier()));
            } else {
                sb.append(l.getLetter())
                        .append(getSubscript(l.getBaseValue()));
            }
            sb.append(" ");
        }

        if (word.hasMultiplier()) {
            sb.insert(0, "(")
                    .insert(sb.length() - 1, ")")
                    .append("x")
                    .append(word.getMultiplier());
        }

        if (word.isLongWord()) {
            sb.append(" +")
                    .append(Word.getLongWordBonus());
        }

        return sb.toString();
    }

    public void printResultMatrixFromOf(Resource type, int start, int end) {
        if (end > start) {
            for (int i = start; i < end; i++) {
                printNthResultMatrixOf(type, i);
                System.out.println();
            }
        } else {
            for (int i = start; i >= end; i--) {
                printNthResultMatrixOf(type, i);
                System.out.println();
            }
        }
    }

    private String getSubscript(int i) {
        StringBuilder sb = new StringBuilder();

        if (i == 0) return String.valueOf((char) SUBSCRIPT_ZERO);

        while (i != 0) {
            sb.append((char) (SUBSCRIPT_ZERO + (i % 10)));
            i /= 10;
        }
        return sb.reverse().toString();
    }

    private char getSuperScript(char l) {
        return SUPERSCRIPTS[l - 'a'];
    }
}
package com.dootz.spellcastsolvergui.model.wordlist;

import java.io.*;
import java.util.HashMap;

public class Dictionary {
    private final TrieNode root;

    public Dictionary() {
        root = new TrieNode();
    }

    public void insert(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            if (!node.children.containsKey(c)) {
                node.children.put(c, new TrieNode());
            }
            node = node.children.get(c);
        }
        node.isEndOfWord = true;
    }

    public void insertWordsFromFile(InputStream stream) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(stream))) {
            String line = br.readLine();
            while (line != null) {
                insert(line);
                line = br.readLine();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public boolean search(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            if (!node.children.containsKey(c)) {
                return false;
            }
            node = node.children.get(c);
        }
        return node.isEndOfWord;
    }

    public boolean startsWith(String prefix) {
        TrieNode node = root;
        for (char c : prefix.toCharArray()) {
            if (!node.children.containsKey(c)) {
                return false;
            }
            node = node.children.get(c);
        }
        return true;
    }
}

class TrieNode {
    boolean isEndOfWord;
    HashMap<Character, TrieNode> children;

    public TrieNode() {
        isEndOfWord = false;
        children = new HashMap<>();
    }
}

