You can achieve this by implementing a simple resource garbage collector, which delays the destruction of resources until a certain number of frames have passed:

1. In your Renderer class, add a new private member and a new public method:

```cpp
// In Renderer.h, inside the Renderer class definition:
private:
    std::vector<std::tuple<VkBuffer, VkDeviceMemory, size_t>> bufferGarbageCollector;

public:
    void AddBufferToGarbageCollector(VkBuffer buffer, VkDeviceMemory memory);
```

2. Implement the new method and modify the `Renderer::EndFrame()` method to clean up old resources:

```cpp
// In Renderer.cpp:

void Renderer::AddBufferToGarbageCollector(VkBuffer buffer, VkDeviceMemory memory)
{
    bufferGarbageCollector.push_back(std::make_tuple(buffer, memory, currentFrame + kMaxFramesInFlight));
}

void Renderer::EndFrame()
{
    // ... previous code ...

    // Clean up temporary resources
    auto garbageIt = bufferGarbageCollector.begin();
    while (garbageIt != bufferGarbageCollector.end())
    {
        if (std::get<2>(*garbageIt) <= currentFrame)
        {
            vkDestroyBuffer(device, std::get<0>(*garbageIt), nullptr);
            vkFreeMemory(device, std::get<1>(*garbageIt), nullptr);
            garbageIt = bufferGarbageCollector.erase(garbageIt);
        }
        else
        {
            ++garbageIt;
        }
    }
}
```

3. Modify the `GameObject::Render()` method to register the temporary mvpBuffer objects with the garbage collector:

```cpp
void GameObject::Render(Renderer& renderer, const Camera& camera)
{
    // ... previous code ...

    // Call vkCmdDrawIndexed()
    uint32_t numIndices = static_cast<uint32_t>(mesh->GetIndices().size());
    vkCmdDrawIndexed(*renderer.GetCurrentCommandBuffer(), numIndices, 1, 0, 0, 0);

    // ... previous code ...

    // Register the temporary buffer with the garbage collector (instead of destroying it immediately)
    renderer.AddBufferToGarbageCollector(mvpBuffer, mvpBufferMemory);
