    public async Task<string> GetValidContent<T>(CustomHttpClient<T> client, HttpMethod httpMethod, string url, string wordsToSearch, byte[]? post = null, int timeout = 60_000, int maxTries = -1, bool autoRedirect = true, Dictionary<string, string?>? aHeaders = null) where T : HttpMessageHandler
    {
        string content;
        bool valid;
        var triesCounter = 0;
        do
        {
            content = await Request(client, httpMethod, url, post, timeout, autoRedirect, aHeaders).ConfigureAwait(false);

            if (autoRedirect == false && content.StartsWith("$Redirected to$|:"))
                break;

            valid = wordsToSearch == null || wordsToSearch.Split('|').Any(w => content.Contains(w, StringComparison.OrdinalIgnoreCase));
            if (!valid)
                await Task.Delay(700).ConfigureAwait(false);
        }
        while (!valid && (maxTries == -1 || ++triesCounter < maxTries));

        return content;
    }
    public async Task<string> GetContentDoesNotContain<T>(CustomHttpClient<T> client, HttpMethod httpMethod, string url, string wordsToSearch, byte[]? post = null, int timeout = 60_000, int maxTries = -1, bool autoRedirect = true, Dictionary<string, string?>? aHeaders = null, bool alsoNotEmpty = true, int notLessThan = 700) where T : HttpMessageHandler
    {
        string content;
        bool valid;
        var triesCounter = 0;
        do
        {
            content = await Request(client, httpMethod, url, post, timeout, autoRedirect, aHeaders).ConfigureAwait(false);

            if (autoRedirect == false && content.StartsWith("$Redirected to$|:"))
                break;

            valid = !alsoNotEmpty || content.Length > notLessThan;

            if (valid && !string.IsNullOrEmpty(wordsToSearch))
            {
                var words = wordsToSearch.Split('|');
                if (words.Any(word => content.Contains(word, StringComparison.OrdinalIgnoreCase)))
                    valid = false;
            }

            if (valid) break;

            await Task.Delay(700).ConfigureAwait(false);
        }
        while (!valid && (maxTries == -1 || ++triesCounter < maxTries));

        return content;
    }
    public async Task<HttpStatusCode> MakeSureFileDownloaded<T>(CustomHttpClient<T> client, HttpMethod httpMethod, string url, string path, bool overrideExist = true, byte[]? post = null, int timeout = 60_000, int maxTries = -1, bool autoRedirect = true, Dictionary<string, string?>? aHeaders = null) where T : HttpMessageHandler
    {
        HttpStatusCode statusCode;
        bool downloaded;
        var triesCounter = 0;
        do
        {
            statusCode = await DownloadFile(client, httpMethod, url, path, overrideExist, post, timeout, autoRedirect, aHeaders).ConfigureAwait(false);

            if (autoRedirect == false && statusCode == HttpStatusCode.Redirect)
                break;

            downloaded = statusCode is HttpStatusCode.OK or HttpStatusCode.Found;
            if (!downloaded)
                await Task.Delay(700).ConfigureAwait(false);
        }
        while (!downloaded && (maxTries == -1 || ++triesCounter < maxTries));

        return statusCode;
    }
    public async Task<byte[]?> MakeSureFileDownloadedToMemory<T>(CustomHttpClient<T> client, HttpMethod httpMethod, string url, byte[]? post = null, int timeout = 60_000, int maxTries = -1, bool autoRedirect = true, Dictionary<string, string?>? aHeaders = null) where T : HttpMessageHandler
    {
        byte[]? result;
        bool downloaded;
        var triesCounter = 0;
        do
        {
            result = await DownloadFileToMemory(client, httpMethod, url, post, timeout, autoRedirect, aHeaders).ConfigureAwait(false);

            //BadGateway > 502 | Forbidden > 403 | Unauthorized	> 401 etc....
            downloaded = result != null && result.Length != 3;

            if (downloaded || (autoRedirect == false && result == Encoding.UTF8.GetBytes(HttpStatusCode.Redirect.ToString())))
                break;

            await Task.Delay(700).ConfigureAwait(false);
        }
        while (!downloaded && (maxTries == -1 || ++triesCounter < maxTries));

        return result;
    }
    public async Task<string> Request<T>(CustomHttpClient<T> client, HttpMethod httpMethod, string url, byte[]? post = null, int timeout = 60_000, bool autoRedirect = true, Dictionary<string, string?>? aHeaders = null) where T : HttpMessageHandler
    {
        string output;
        try
        {
            var response = await SendAsync(client, httpMethod, url, post, timeout, autoRedirect, aHeaders).ConfigureAwait(false);

            if (!autoRedirect && response.StatusCode == HttpStatusCode.Redirect)
                return $"$Redirected to$|:{response.Headers.Location}";

            output = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
        }
        catch (Exception e)
        {
            var err = e.InnerException == null ? e.Message : e.InnerException.Message;
            //writeLineDEBUG(err);
            output = err;
        }
        return output;
    }
    public async Task<HttpStatusCode> DownloadFile<T>(CustomHttpClient<T> client, HttpMethod httpMethod, string url, string path, bool overrideExist = true, byte[]? post = null, int timeout = 120_000, bool autoRedirect = true, Dictionary<string, string?>? aHeaders = null) where T : HttpMessageHandler
    {
        url = TryGetValidUrl(url)!;
        if (string.IsNullOrWhiteSpace(url)) return HttpStatusCode.RequestUriTooLong;

        if (!overrideExist && File.Exists(path)) return HttpStatusCode.Found;

        try
        {
            var response = await SendAsync(client, httpMethod, url, post, timeout, autoRedirect, aHeaders).ConfigureAwait(false);

            if (response.StatusCode is not (HttpStatusCode.OK or HttpStatusCode.Found)) return response.StatusCode;

            await using var responseStream = await response.Content.ReadAsStreamAsync().ConfigureAwait(false);
            await using var fs = File.Create(path);
            await responseStream.CopyToAsync(fs).ConfigureAwait(false);
        }
        catch
        {
            return HttpStatusCode.BadRequest;
        }

        return HttpStatusCode.OK;
    }
    public async Task<byte[]?> DownloadFileToMemory<T>(CustomHttpClient<T> client, HttpMethod httpMethod, string url, byte[]? post = null, int timeout = 120_000, bool autoRedirect = true, Dictionary<string, string?>? aHeaders = null) where T : HttpMessageHandler
    {
        url = TryGetValidUrl(url)!;
        if (string.IsNullOrWhiteSpace(url)) return default;

        try
        {
            var response = await SendAsync(client, httpMethod, url, post, timeout, autoRedirect, aHeaders).ConfigureAwait(false);

            if (response.StatusCode is not HttpStatusCode.OK)
                return Encoding.UTF8.GetBytes(((int)response.StatusCode).ToString());

            return await response.Content.ReadAsByteArrayAsync().ConfigureAwait(false);
        }
        catch
        {
            return default;
        }
    }
    private Task<HttpResponseMessage> SendAsync<T>(CustomHttpClient<T> client, HttpMethod httpMethod, string url, byte[]? post = null, int timeout = 60_000, bool autoRedirect = true, Dictionary<string, string?>? aHeaders = null) where T : HttpMessageHandler
    {
        var uri = new Uri(url);
        var request = new HttpRequestMessage
        {
            RequestUri = uri,
            Method = httpMethod
        };

        request.SetTimeout(TimeSpan.FromMilliseconds(timeout));
        request.Headers.ExpectContinue = false;

        //if (aHeaders == null || aHeaders.Keys.All(k => k.ToLower() != "referer"))
        //    request.Headers.Referrer = uri;
        if (aHeaders != null)
            foreach (var header in aHeaders)
                request.Headers.TryAddWithoutValidation(header.Key, header.Value);

        if (post != null)
        {
            request.Content = new ByteArrayContent(post);

            var contentType = aHeaders?.FirstOrDefault(h => h.Key.Equals("content-type", StringComparison.InvariantCultureIgnoreCase)).Value;
            request.Content.Headers.ContentType = MediaTypeHeaderValue.Parse(contentType ?? "application/x-www-form-urlencoded");
        }

        TryToSetHandlerRedirect(client.Handler, autoRedirect);
        return client.SendAsync(request);
    }


    /// <summary>
    /// Returns a valid URL if it's valid or missing just http: |
    /// Returns null if it's not valid
    /// </summary>
    public static string? TryGetValidUrl(string? url)
    {
        if (url == null) return null;

        if (url.StartsWith("//")) url = $"http:{url}";
        return CheckUrlValid(url) ? url : null;
    }

    public static bool CheckUrlValid(string source)
    {
        return Uri.TryCreate(source, UriKind.Absolute, out var uriResult)
               && (uriResult.Scheme == Uri.UriSchemeHttp || uriResult.Scheme == Uri.UriSchemeHttps);
    }

