            SendTimeout = sTimeout,
            AutomaticDecompression = DecompressionMethods.GZip | DecompressionMethods.Deflate | DecompressionMethods.Brotli
        };
    }
#endif

    private static void TryToSetHandlerRedirect<T>(T handler, bool autoRedirect = true) where T : HttpMessageHandler
    {
        switch (handler)
        {
            case WinHttpHandler whh:
                whh.AutomaticRedirection = autoRedirect;
                break;
            case HttpClientHandler hch:
                hch.AllowAutoRedirect = autoRedirect;
                break;
        }
    }

    public class CustomHttpClient<T> : HttpClient where T : HttpMessageHandler
    {
        //public TimeSpan DefaultTimeout { get; set; } = TimeSpan.FromSeconds(100);
        public T Handler { get; }

        public CustomHttpClient(T handler, bool disposeHandler = true) : base(handler, disposeHandler)
        {
            Timeout = System.Threading.Timeout.InfiniteTimeSpan;
            Handler = handler;
        }

        public override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
#if Http2
            if (Handler is WinHttpHandler)
                request.Version = new Version("2.0");
#endif

            using var cts = GetCancellationTokenSource(request, cancellationToken);
            try
            {
                var response = await base.SendAsync(request, cts?.Token ?? cancellationToken).ConfigureAwait(false);

                if (!response.Content.Headers.TryGetValues("Content-Encoding", out var ce) || ce.First() != "br")
                    return response;

                //var buffer = await response.Content.ReadAsByteArrayAsync(cancellationToken).ConfigureAwait(false);
                //response.Content = new ByteArrayContent(Brotli.DecompressBuffer(buffer, 0, buffer.Length));
                var stream = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
                response.Content = new StreamContent(new BrotliStream(stream, CompressionMode.Decompress));
                return response;
            }
            catch (OperationCanceledException ex) when (!cancellationToken.IsCancellationRequested)
            {
                throw new TimeoutException(ex.Message, ex);
            }
        }

        private CancellationTokenSource? GetCancellationTokenSource(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            var timeout = request.GetTimeout() ?? Timeout;
            if (timeout == System.Threading.Timeout.InfiniteTimeSpan)
            {
                // No need to create a CTS if there's no timeout
                return null;
            }

            var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            cts.CancelAfter(timeout);
            return cts;
        }
    }
    #endregion
}

public static class HttpRequestExtensions
{
    private const string TimeoutPropertyKey = "RequestTimeout";
    private static readonly HttpRequestOptionsKey<TimeSpan?> TimeoutOptionsKey;

    static HttpRequestExtensions() => TimeoutOptionsKey = new HttpRequestOptionsKey<TimeSpan?>(TimeoutPropertyKey);

    public static void SetTimeout(this HttpRequestMessage request, TimeSpan? timeout)
    {
        if (request == null)
            throw new ArgumentNullException(nameof(request));

        request.Options.Set(TimeoutOptionsKey, timeout);
    }

    public static TimeSpan? GetTimeout(this HttpRequestMessage request)
    {
        if (request == null)
            throw new ArgumentNullException(nameof(request));

        return request.Options.TryGetValue(TimeoutOptionsKey, out var value) ? value : null;
    }
}

This `HttpClientHelper` class provides methods to perform HTTP requests and handle responses, such as checking for valid content, ensuring the file is downloaded, etc. It also supports creating custom HTTP clients with specified handlers, cookies, and proxies.

Here are a few examples of how to use this helper class:

1. Creating a custom HTTP client with a specific HttpClientHandler:

```csharp
using System.Net;

var cookies = new CookieContainer();
var proxy = new WebProxy("http://proxy.example.com:8080");
var handler = HttpClientHelper.CreateHttpHandler(cookies, proxy);
var client = HttpClientHelper.CreateHttpClient(handler);
```

2. Sending an HTTP GET request and checking if the response contains certain words:

```csharp
var url = "https://www.example.com";
var wordsToSearch = "word1|word2|word3";
var maxTries = 3;
var response = await new HttpClientHelper().GetValidContent(client, HttpMethod.Get, url, wordsToSearch, maxTries: maxTries);
```

3. Downloading a file using an HTTP GET request and making sure it's completed:

```csharp
var url = "https://www.example.com/somefile.zip";
var path = "C:/path/to/downloaded/file.zip";
var statusCode = await new HttpClientHelper().MakeSureFileDownloaded(client, HttpMethod.Get, url, path);
```

Remember to add the appropriate `using` statements to your code before using the `HttpClientHelper`.

出现以上情况的原因可能是因为A项目的 @Component 注解加在了一个非 Spring 容器管理的类上，导致 @Value 注解无法获取到配置文件的值。解决方法如下：

1. 确认 A 项目中被 @Component 注解标注的所有类均被 Spring 管理。

2. 在 A 项目中，使用 @PropertySource 注解来指定要读取的配置文件，例如：

   ```java
   @Configuration
   @PropertySource("classpath:application.properties")
   public class AppConfig {
       // ...
   }
   ```

   这样可以让 Spring 容器知道要读取哪个配置文件，从而使 @Value 注解能够正确获取值。

3. 在 A 项目中，对于常量类、枚举类等，可以考虑使用 @ConfigurationProperties 注解来获取配置文件中的值，例如：

   ```java
   @Component
   @ConfigurationProperties(prefix = "myconfig")
   public class MyConfig {
       private String value1;
       private int value2;
       // ... getter 方法
   }
   ```

   这样可以直接将配置文件中的值注入到属性中，而无需使用 @Value 注解。

4. 如果以上方法无法解决问题，可以考虑在 B 项目中手动加载 A 项目中的配置文件，例如：

   ```java
   @SpringBootApplication
   @ImportResource(locations = {"classpath:/applicationContext.xml"})
   public class MyApplication {
       // ...
   }
   ```

   这样，在 B 项目中，通过 @ImportResource 注解加载 A 项目中的 applicationContext.xml，就能够让 Spring 知道要读取哪个配置文件。

