    const g = Math.floor(128 + (255 - 128) * ratio);
    const b = Math.floor(0 + (255 - 0) * ratio);
    return `rgb(${r}, ${g}, ${b})`;
  };

  const deepRed = (ratio: number): string => {
    const r = Math.floor(255 + (255 - 255) * ratio);
    const g = Math.floor(0 + (255 - 0) * ratio);
    const b = Math.floor(0 + (255 - 0) * ratio);
    return `rgb(${r}, ${g}, ${b})`;
  };

  const clamp = (value: number, min: number, max: number): number => {
    return Math.min(Math.max(value, min), max);
  };

  const renderTrade = (prev: CupItem, item: CupItem, index: number) => {
    if (orderFeedCanvas.current) {
