const renderCupItem = (ctx, item, xPos, yPos, maxVolume) => {
  const sizeRatio = item.quantity / maxVolume;
  const bubbleSize = 35 * sizeRatio;

  // Set the fill color and stroke color
  const fillColor = item.side === "Sell" ? deepGreen : deepRed;
  ctx.fillStyle = fillColor;
  ctx.strokeStyle = "black";

  // Draw the circle on the canvas
  ctx.beginPath();
  ctx.arc(xPos, yPos, bubbleSize, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // Render the text
  const labelText = abbreviateNumber(item.quantity);
  const { width: textWidth } = ctx.measureText(labelText);
  ctx.fillStyle = "#FFFFFF";
  ctx.fillText(labelText, xPos - textWidth / 2, yPos + rowHeight / 2 - 2);
};
