Here is a Java program that accepts a year and the first day of the year (i.e. which day of the week January 1st falls on) and displays a calendar for that year:

```
import java.util.Scanner;

public class CalendarProgram {

    // constants for days of the week
    public static final String[] DAYS_OF_WEEK = {"Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"};

    public static void main(String[] args) {

        // initialize scanner for user input
        Scanner scanner = new Scanner(System.in);

        // prompt user for year and first day of the year
        System.out.print("Enter year: ");
        int year = scanner.nextInt();
        System.out.print("Enter first day of the year (0 for Sunday, 1 for Monday, etc.): ");
        int firstDayOfYear = scanner.nextInt();

        // display calendar for the year
        displayCalendar(year, firstDayOfYear);

        // close scanner
        scanner.close();
    }

    // method to display a calendar for a given year
    public static void displayCalendar(int year, int firstDayOfYear) {

        // loop through months of the year
        for (int month = 1; month <= 12; month++) {

            // determine number of days in the month
            int numDaysInMonth = getNumDaysInMonth(year, month);

            // print month and year heading
            System.out.println(getMonthName(month) + " " + year);

            // print days of the week header
            for (String dayOfWeek : DAYS_OF_WEEK) {
                System.out.print(dayOfWeek + "\t");
            }
            System.out.println();

            // print leading spaces for the first day of the month
            for (int i = 0; i < firstDayOfMonth(year, month, firstDayOfYear); i++) {
                System.out.print("\t");
            }

            // print days of the month
            for (int day = 1; day <= numDaysInMonth; day++) {
                System.out.print(day + "\t");
                if (((firstDayOfMonth(year, month, firstDayOfYear) + day) % 7 == 0) || (day == numDaysInMonth)) {
                    System.out.println();
                }
            }
            // update the first day of the next month
            firstDayOfYear = (firstDayOfYear + numDaysInMonth) % 7;
            System.out.println();
        }
    }

    // method to determine the number of days in a given month of a given year
    public static int getNumDaysInMonth(int year, int month) {
        if (month == 2) {
            return (isLeapYear(year) ? 29 : 28);
        }
        else if ((month == 4) || (month == 6) || (month == 9) || (month == 11)) {
            return 30;
        }
        else {
            return 31;
        }
    }

    // method to determine if a given year is a leap year
    public static boolean isLeapYear(int year) {
        return ((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0);
    }

    // method to determine the name of a given month
    public static String getMonthName(int month) {
        switch (month) {
            case 1:
                return "January";
            case 2:
                return "February";
            case 3:
                return "March";
            case 4:
                return "April";
            case 5:
                return "May";
            case 6:
                return "June";
            case 7:
                return "July";
            case 8:
                return "August";
            case 9:
                return "September";
            case 10:
                return "October";
            case 11:
                return "November";
            case 12:
                return "December";
            default:
                return "";
        }
    }

    // method to determine the day of the week of the first day of a given month of a given year
    public static int firstDayOfMonth(int year, int month, int firstDayOfYear) {
        int numDays = 0;
        for (int i = 1; i < month; i++) {
            numDays += getNumDaysInMonth(year, i);
        }
        return (firstDayOfYear + numDays) % 7;
    }

}
```

To use this program, simply run it and enter the year and the first day of the year as prompted. The program will then display a calendar for the year, with each month's days printed in rows of 7 starting with the first day of the week.

