using UnityEngine;

public class Layout : IEnumerable<Vector2>
{
    public enum GrowthDirections
    {
        RightDown,
        RightUp,
        LeftDown,
        LeftUp,
        VerticalCentered,
        HorizontalCentered
    }

    private Vector2 originPosition;
    private Vector2 originSize;
    private float padding;
    private GrowthDirections growthDirection;
    private Vector2 elementSize;
    private int elementCount;
    private List<Vector2> positions;
    private bool isDirty;

    public void SetDirty(bool isDirty)
    {
        this.isDirty = isDirty;
    }

    public void Update(Vector2 originPosition, Vector2 originSize, float padding, GrowthDirections growthDirection, Vector2 elementSize, int elementCount)
    {
        if (!isDirty && elementCount == this.elementCount)
        {
            return;
        }

        this.originPosition = originPosition;
        this.originSize = originSize;
        this.padding = padding;
        this.growthDirection = growthDirection;
        this.elementSize = elementSize;
        this.elementCount = elementCount;

        positions = new List<Vector2>();
        CalculatePositions();
        isDirty = false;
    }

    private void CalculatePositions()
    {
        Vector2 currentPosition = originPosition;
        int currentRow = 1;
        int currentColumn = 1;

        positions.Clear();

        for (int i = 0; i < elementCount; i++)
        {
            Vector2 newPosition = currentPosition;

            switch (growthDirection)
            {
                case GrowthDirections.RightDown:
                    newPosition = new Vector2(currentPosition.x, currentPosition.y);
                    break;
                case GrowthDirections.RightUp:
                    newPosition = new Vector2(currentPosition.x, -(currentPosition.y));
                    break;
                case GrowthDirections.LeftDown:
                    newPosition = new Vector2(-(currentPosition.x), currentPosition.y);
                    break;
                case GrowthDirections.LeftUp:
                    newPosition = new Vector2(-(currentPosition.x), -(currentPosition.y));
                    break;
                case GrowthDirections.VerticalCentered:
                    newPosition = new Vector2(currentPosition.x, -(currentPosition.y));
                    break;
                case GrowthDirections.HorizontalCentered:
                    newPosition = new Vector2(-(currentPosition.x), currentPosition.y);
                    break;
            }

            positions.Add(newPosition);

            switch (growthDirection)
            {
                case GrowthDirections.VerticalCentered:
                case GrowthDirections.RightDown:
                case GrowthDirections.RightUp:
                    currentPosition.x += elementSize.x + padding;
                    if (currentPosition.x + elementSize.x > originSize.x)
                    {
                        currentPosition.x = originPosition.x;
                        currentPosition.y += elementSize.y + padding;
                    }
                    break;
                case GrowthDirections.HorizontalCentered:
                case GrowthDirections.LeftDown:
                case GrowthDirections.LeftUp:
                    currentPosition.y += elementSize.y + padding;
                    if (currentPosition.y + elementSize.y > originSize.y)
                    {
                        currentPosition.y = originPosition.y;
                        currentPosition.x += elementSize.x + padding;
                    }
                    break;
            }
        }
    }

    public IEnumerator<Vector2> GetEnumerator()
    {
        return positions.GetEnumerator();
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}
