To create a simple Unity game with ML agents, follow these steps:

1. Create a new Unity project with 2D settings.
2. Create a new folder called "Scripts" in the Assets folder.
3. Download and import "ml-agents" and "ml-agents.extensions" Unity packages in the project: https://github.com/Unity-Technologies/ml-agents/releases
4. Inside the "Scripts" folder, create a new "C#" script called "PlayerAgent".
5. Replace the content of the "PlayerAgent" script with the following code:

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Unity.MLAgents;
using Unity.MLAgents.Sensors;

public class PlayerAgent : Agent
{
    public float speed = 5.0f;
    public Transform target;
    private Rigidbody2D rb;

    private void Start()
    {
        rb = GetComponent<Rigidbody2D>();
    }

    public override void OnActionReceived(float[] vectorAction)
    {
        Vector2 movement = new Vector2(vectorAction[0], vectorAction[1]).normalized;

        float distanceToTarget = Vector2.Distance(transform.position, target.position);

        if (distanceToTarget < 1.0f)
        {
            AddReward(1.0f);
            EndEpisode();
        }

        AddReward(-0.001f * distanceToTarget);
        rb.velocity = movement * speed;
    }

    public override void Heuristic(float[] actionsOut)
    {
        // Input from keyboard
        actionsOut[0] = Input.GetAxisRaw("Horizontal");
        actionsOut[1] = Input.GetAxisRaw("Vertical");
    }

    public override void OnEpisodeBegin()
    {
        transform.position = new Vector2(Random.Range(-8f, 8f), Random.Range(-8f, 8f));
        target.position = new Vector2(Random.Range(-8f, 8f), Random.Range(-8f, 8f));
    }

    public override void CollectObservations(VectorSensor sensor)
    {
        sensor.AddObservation(transform.position);
        sensor.AddObservation(target.position);
        sensor.AddObservation(rb.velocity);
    }
}
```

6. In the Hierarchy, create a new GameObject called "Game" and add the "PlayerAgent" script to it. Create another GameObject called "Target". Assign the Target object to the "Target" field in the "Game" GameObject.
7. Add a Rigidbody2D component to the "Game" GameObject and set its Gravity Scale to 0.
8. Create a new folder called "Prefabs" in the Assets folder and drag both "Game" and "Target" objects to create prefabs.
9. Remove the "Game" and "Target" objects from the Hierarchy.
10. Inside the "ml-agents" folder, create an "agent.yaml" file with the following content:
```yaml
behaviors:
  PlayerAgent:
    trainer_type: ppo
    hyperparameters:
      batch_size: 10
      buffer_size: 100
      learning_rate: 0.0003
      beta: 0.005
      epsilon: 0.2
      lambd: 0.95
      num_epoch: 3
