    void RegisterCallback(std::function<void(const EventType&)> callback)
    {
        using EventTypePointer = void (*)(const EventType&);
        auto wrapper = [callback](const Event* eventPtr) {
            callback(static_cast<const EventType&>(*eventPtr));
