An `EventBus` class is already defined in the given `ECS` code. Below I will provide an extended version of the `EventBus` class along with the necessary modifications in the `ECS` class to support event handling in the current ECS architecture.

First, extend the `EventBus` class:
```cpp
#include <functional>
#include <unordered_map>
#include <vector>

class EventBus
{
public:
    template <typename EventType>
    using Callback = std::function<void(const EventType&)>;

    // Subscribes a callback to an event type.
    template <typename EventType>
    void Subscribe(const Callback<EventType>& callback);

    // Unsubscribes a callback from an event type.
    template <typename EventType>
    void Unsubscribe(const Callback<EventType>& callback);

    // Publishes an event to all subscribed callbacks.
    template <typename EventType>
    void Publish(const EventType& event);

private:
    typedef std::vector<void*> CallbackVector;

    std::unordered_map<size_t, CallbackVector> subscribers_;
};

template <typename EventType>
void EventBus::Subscribe(const Callback<EventType>& callback)
{
    size_t typeId = typeid(EventType).hash_code();
    auto it = subscribers_.find(typeId);

    if (it == subscribers_.end())
    {
        it = subscribers_.emplace(typeId, CallbackVector{}).first;
    }

    it->second.push_back(new Callback<EventType>(callback));
}

template <typename EventType>
void EventBus::Unsubscribe(const Callback<EventType>& callback)
{
    size_t typeId = typeid(EventType).hash_code();
    auto it = subscribers_.find(typeId);

    if (it != subscribers_.end())
    {
        auto& callbacks = it->second;

        for (auto iter = callbacks.begin(); iter != callbacks.end();)
        {
            const auto& targetCallback = *reinterpret_cast<const Callback<EventType>*>(*iter);

            if (&targetCallback.target_type() == &callback.target_type()
                && targetCallback.target<void(const EventType&)>() == callback.target<void(const EventType&)>())
            {
                iter = callbacks.erase(iter);
            }
            else
            {
                ++iter;
            }
        }
    }
}

template <typename EventType>
void EventBus::Publish(const EventType& event)
{
    size_t typeId = typeid(EventType).hash_code();
    auto it = subscribers_.find(typeId);

    if (it != subscribers_.end())
    {
        for (const auto& storedCallback : it->second)
        {
            const auto& callback = *reinterpret_cast<const Callback<EventType>*>(storedCallback);
            callback(event);
        }
    }
}
```

