Vue.createApp({
    data() {
        return {
            currentSVG: 1,
            svg1: `M344.5 244.5L308 291L231 279L74.5 296.5H11V241L0 98.5L41.5 0L158.5 18.5L280.5 0L359.27 13.5279 L368.5 79L344.5 244.5Z`,
