public class PlayerAgent : Agent
{
    [SerializeField] private float moveSpeed = 3.0f;
    private Rigidbody2D playerRigidbody;
    private Vector2 startLocation;

    public override void Initialize()
    {
        playerRigidbody = GetComponent<Rigidbody2D>();
        startLocation = transform.position;
    }

    public override void OnEpisodeBegin()
    {
        transform.position = new Vector2(
            Random.Range(startLocation.x - 5, startLocation.x + 5),
            Random.Range(startLocation.y - 5, startLocation.y + 5)
        );
    }

    public override void CollectObservations(VectorSensor sensor)
    {
        sensor.AddObservation(playerRigidbody.velocity);
    }

    public override void OnActionReceived(ActionBuffers actions)
    {
        float moveX = Mathf.Clamp(actions.ContinuousActions[0], -1, 1);
        float moveY = Mathf.Clamp(actions.ContinuousActions[1], -1, 1);
        Vector2 direction = new Vector2(moveX, moveY).normalized;
        playerRigidbody.velocity = direction * moveSpeed;
    }

    public override void Heuristic(in ActionBuffers actionsOut)
    {
        var continuousActionsOut = actionsOut.ContinuousActions;
        continuousActionsOut[0] = Input.GetAxis("Horizontal");
        continuousActionsOut[1] = Input.GetAxis("Vertical");
    }

    private void OnTriggerEnter2D(Collider2D other)
