using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class FoodSpawner : MonoBehaviour
{
    [SerializeField] private GameObject foodPrefab;
    [SerializeField] private int foodCount = 10;

    private BoxCollider2D boxCollider;
    private List<GameObject> foodInstances;

    void Awake()
    {
        boxCollider = GetComponent<BoxCollider2D>();
        foodInstances = new List<GameObject>();

        SpawnNewFoods();
    }

    public void SpawnNewFoods()
    {
        if (foodInstances != null)
        {
            foreach (GameObject foodInstance in foodInstances)
            {
                Destroy(foodInstance);
            }
            foodInstances.Clear();
        }

        for (int i = 0; i < foodCount; i++)
        {
            Vector2 randomSpawnPos = GetRandomPositionInBounds();
            GameObject foodInstance = Instantiate(foodPrefab, randomSpawnPos, Quaternion.identity);
            foodInstances.Add(foodInstance);
        }
    }

    private Vector2 GetRandomPositionInBounds()
    {
        Vector2 randomSpawnPos = new Vector2(
            Random.Range(boxCollider.bounds.min.x, boxCollider.bounds.max.x),
            Random.Range(boxCollider.bounds.min.y, boxCollider.bounds.max.y)
        );

        return randomSpawnPos;
    }
}
