Here's a simple C program that creates an HTTP server with the GET method, listening on port 8080. It allows clients to download files in a specified directory. 

Please note that this example is quite minimalistic and doesn't include error handling, security checks or support for different MIME types.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

void *connection_handler(void *socket_desc);

int main(int argc , char *argv[])
{
    int socket_desc, client_sock, c;
    struct sockaddr_in server, client;
    pthread_t thread_id;

    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1)
    {
        printf("Could not create socket");
    }

    server.sin_family = AF_INET;
    server.sin_addr.s_addr = INADDR_ANY;
    server.sin_port = htons(8080);

    if (bind(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0)
    {
        perror("bind failed");
        return 1;
    }

    listen(socket_desc, 3);
    c = sizeof(struct sockaddr_in);

    while ((client_sock = accept(socket_desc, (struct sockaddr *)&client, (socklen_t*)&c)))
    {
        if (pthread_create(&thread_id, NULL, connection_handler, (void*)&client_sock) < 0)
        {
            perror("could not create thread");
            return 1;
        }
    }

    if (client_sock < 0)
    {
        perror("accept failed");
        return 1;
    }

    return 0;
}

void *connection_handler(void *socket_desc)
{
    int sock = *(int*)socket_desc;
    int read_size;
    char buffer[1024], response[4096], file_path[255];
    FILE *file;
    long file_size;
    size_t result;

    memset(buffer, 0, sizeof buffer);

    read_size = recv(sock, buffer, sizeof buffer, 0);
    if (read_size > 0)
    {
        if (strncmp(buffer, "GET", 3) == 0)
        {
            sscanf(buffer, "GET /%255s", file_path);

            file = fopen(file_path, "rb");
            if (file)
            {
                fseek(file, 0, SEEK_END);
                file_size = ftell(file);
                rewind(file);

                snprintf(response, sizeof response,
                    "HTTP/1.1 200 OK\r\n"
                    "Content-Type: application/octet-stream\r\n"
                    "Content-Length: %ld\r\n"
                    "Content-Disposition: attachment; filename=\"%s\"\r\n"
                    "\r\n", file_size, file_path);

                send(sock, response, strlen(response), 0);

                memset(response, 0, sizeof response);
                while ((result = fread(response, 1, sizeof response, file)) > 0)
                {
                    send(sock, response, result, 0);
                }

                fclose(file);
            }
            else
            {
                snprintf(response, sizeof response, 
                    "HTTP/1.1 404 Not Found\r\n"
                    "Content-Type: text/plain\r\n"
                    "Content-Length: 20\r\n"
                    "\r\n"
                    "Error 404: Not Found");

                send(sock, response, strlen(response), 0);
            }
        }
    }

    close(sock);
    return 0;
}
```

