  vertices.forEach((vertex, index) => {
    let [screenX, screenY] = project(vertex.x, vertex.y, vertex.z);

    let distance = Math.sqrt((x - screenX) ** 2 + (y - screenY) ** 2);
    if (distance < closestDistance) {
      closestDistance = distance;
      closestIndex = index;
    }
  });

  if (closestDistance < 10) {
    indexToDrag = closestIndex;
  } else {
    indexToDrag = -1;
  }
}

function drag(event) {
