    const cx = vertex.x - offsetX;
    const cy = vertex.y - offsetY;
    const cz = vertex.z - offsetY;

    const rotated = transform(transform(transform([cx, cy, cz], rotX), rotY), rotZ);

    return {
      x: rotated[0] + offsetX,
      y: rotated[1] + offsetY,
      z: rotated[2] + offsetY
    };
