// Load the next packet from the input format context, return whether a packet was loaded
// If the end of file is reached, it will seek to the beginning to loop the input
char load_packet(AVFormatContext *inputFormatContext, AVPacket *pkt, int64_t *lastPts, int64_t *lastDts)
{
    while (av_read_frame(inputFormatContext, pkt) >= 0)
    {
        int64_t pts = pkt->pts == AV_NOPTS_VALUE ? lastPts[pkt->stream_index] : pkt->pts;
        int64_t dts = pkt->dts == AV_NOPTS_VALUE ? lastDts[pkt->stream_index] : pkt->dts;

        if (pts >= lastPts[pkt->stream_index] && dts >= lastDts[pkt->stream_index])
        {
            lastPts[pkt->stream_index] = pts;
            lastDts[pkt->stream_index] = dts;
            return 1;
        }

        av_packet_unref(pkt);
    }

    // Seek to the beginning and try reading again
    av_seek_frame(inputFormatContext, -1, 0, AVSEEK_FLAG_BACKWARD);
