  [3, 7],
  [4, 5],
  [5, 6],
  [6, 7],
  [7, 4],
];

const scale = 200;
const offsetX = canvas.width / 2;
const offsetY = canvas.height / 2;
const distanceToProjectionPlane = 200;

let selectedVertex = null;

function project(vertex) {
  const [x, y, z] = vertex;
  return [
    x * (distanceToProjectionPlane / (z + distanceToProjectionPlane)) * scale + offsetX,
    y * (distanceToProjectionPlane / (z + distanceToProjectionPlane)) * scale + offsetY,
  ];
}

function vertexDistanceSquared(vertex1, vertex2) {
  return (vertex1[0] - vertex2[0]) ** 2 + (vertex1[1] - vertex2[1]) ** 2;
}

function getClosestVertex(mouse) {
  const projectedVertices = vertices.map(vertex => project(vertex));
  let closestVertexIndex = -1;
  let closestDistanceSquared = Infinity;

  for (let i = 0; i < projectedVertices.length; i++) {
    const distanceSquared = vertexDistanceSquared(projectedVertices[i], mouse);

    if (distanceSquared < closestDistanceSquared) {
      closestDistanceSquared = distanceSquared;
      closestVertexIndex = i;
    }
  }

  return closestVertexIndex;
}

