function getDistanceFromPointToLine(px, py, x1, y1, x2, y2) {
  const dX = x2 - x1;
  const dY = y2 - y1;
  const lenSq = dX * dX + dY * dY;
  const t = ((px - x1) * dX + (py - y1) * dY) / lenSq;

  if (t < 0) return Math.sqrt((px - x1) ** 2 + (py - y1) ** 2);
  if (t > 1) return Math.sqrt((px - x2) ** 2 + (py - y2) ** 2);

  const projX = x1 + t * dX;
  const projY = y1 + t * dY;

  return Math.sqrt((px - projX) ** 2 + (py - projY) ** 2);
}

function snapToGrid(x, y, gridSize) {
  const newX = Math.round(x / gridSize) * gridSize;
  const newY = Math.round(y / gridSize) * gridSize;
  return [newX, newY];
}

