```javascript
const approvalTx = await tokenToSwapContract.approve(
  uniswapV3SwapRouterAddress,
  tokenToSwapAmount,
  { gasLimit: 250000 } // Remove 'gasPrice: customGasPrice,' from this line
);

const swapTx = await uniswapV3SwapRouterContract.exactInputSingle(
