Here is the implementation of the `AABBVsAABB` function that tests two axis-aligned bounding boxes (AABB) for intersection, and returns the intersection information including normal, depth, intersection points, and type (overlaps or nested).

```cpp
std::optional<isect_s> AABBVsAABB(const vec2f& origin1, const vec2f& vMins1, const vec2f& vMaxs1, const vec2f& origin2, const vec2f& vMins2, const vec2f& vMaxs2) {
	// Check if the boxes are not intersecting along any axis
	for (int axis = 0; axis < 2; ++axis) {
		if (origin1[axis] + vMaxs1[axis] < origin2[axis] + vMins2[axis] || origin1[axis] + vMins1[axis] > origin2[axis] + vMaxs2[axis])
			return std::nullopt; // No intersection
	}

	// Calculate the shortest displacement vector to separate the boxes
	vec2f overlap, normal;
	float depth = std::numeric_limits<float>::max();
	for (int axis = 0; axis < 2; ++axis) {
		float o1 = origin1[axis] + vMaxs1[axis] - (origin2[axis] + vMins2[axis]);
		float o2 = origin2[axis] + vMaxs2[axis] - (origin1[axis] + vMins1[axis]);

		if (o1 < o2) {
			overlap[axis] = o1;
			normal[axis] = (axis == 0) ? 1.0f : -1.0f;
		} else {
			overlap[axis] = o2;
			normal[axis] = (axis == 0) ? -1.0f : 1.0f;
		}

		if (overlap[axis] < depth) {
			depth = overlap[axis];
			normal = vec2f((axis == 0) ? normal.x : 0, (axis == 1) ? normal.y : 0);
		}
	}

	isect_s isect;
	isect.normal = normal;
	isect.depth = depth;

	// Check if the boxes are coincident (completely overlapping)
	if (is_same(vMins1.x, vMins2.x) && is_same(vMaxs1.x, vMaxs2.x) && is_same(vMins1.y, vMins2.y) && is_same(vMaxs1.y, vMaxs2.y)) {
		isect.type = isect_type_e::NESTED;
		isect.points = std::nullopt;
	} else {
		isect.type = isect_type_e::OVERLAPS;
		// Calculate the intersection points by finding the overlapping region of the boxes
		vec2f minIntersection = vec2f(std::max(origin1.x + vMins1.x, origin2.x + vMins2.x), std::max(origin1.y + vMins1.y, origin2.y + vMins2.y));
		vec2f maxIntersection = vec2f(std::min(origin1.x + vMaxs1.x, origin2.x + vMaxs2.x), std::min(origin1.y + vMaxs1.y, origin2.y + vMaxs2.y));
		isect.points = std::vector<vec2f>({minIntersection, maxIntersection});
	}

	return isect;
