            normal = vec2f((axis == 0) ? normal.x : 0, (axis == 1) ? normal.y : 0);
        }
    }

    isect.normal = normal;
    isect.depth = depth;

    if (isect.type == isect_type_e::OVERLAPS) {
        // Calculate the intersection points by finding the overlapping region of the boxes
        vec2f minIntersection = vec2f(std::max(origin1.x + vMins1.x, origin2.x + vMins2.x), std::max(origin1.y + vMins1.y, origin2.y + vMins2.y));
